writeNewRepair("omniflow-backend-patch/portal_kb_files.py", "class ExtractError", false,
    "\"\"\"Knowledge file import (\u00a7219): text out of PDF and Word (.docx) files.\n\nThe owner uploads a document on the Knowledge page; the website posts it\nbase64-encoded to ``POST /api/v1/portal/kb/extract``; this module returns\nthe readable text, which the owner reviews and then adds as a DRAFT\nsource through the normal ingest path (the KB auto-publish lock stays:\nnothing here stores or publishes anything).\n\n* DOCX is read with the standard library only (zipfile + ElementTree):\n  headings (built-in, localised style ids and outline levels) become\n  markdown ``#`` lines so the chunker labels sections, numbered/bulleted\n  paragraphs become ``- `` lines, table rows become ``a | b`` lines, and\n  content controls are included. Zip-bomb guard (declared unpacked size\n  checked before reading) and DTD/entity markup refused.\n* PDF uses ``pypdf`` (pure Python, imported lazily so the Control Plane\n  boots without it). Encrypted files that need a password, scanned pages\n  without selectable text (no OCR) and damaged files return honest\n  owner-readable errors.\n\nLimits come from env (no hardcoding):\nOF_KB_FILE_BYTES_MAX, OF_KB_PDF_PAGES_MAX, OF_KB_EXTRACT_SECONDS,\nOF_KB_DOCX_PART_BYTES_MAX, OF_KB_SOURCE_CHARS_MAX.\n\"\"\"\n\nimport base64\nimport binascii\nimport io\nimport logging\nimport os\nimport re\nimport time\nimport zipfile\nimport xml.etree.ElementTree as ET\nfrom typing import Any, Dict, List, Optional, Tuple\n\nlogger = logging.getLogger(\"omniflow.portal-kb-files\")\n\n\ndef _env_int(name: str, default: int, lo: int, hi: int) -> int:\n    try:\n        value = int(os.environ.get(name, \"\") or default)\n    except Exception:\n        value = default\n    return max(lo, min(hi, value))\n\n\nFILE_BYTES_MAX = _env_int(\"OF_KB_FILE_BYTES_MAX\", 3000000, 10000, 50000000)\nPDF_PAGES_MAX = _env_int(\"OF_KB_PDF_PAGES_MAX\", 300, 1, 5000)\nEXTRACT_SECONDS = _env_int(\"OF_KB_EXTRACT_SECONDS\", 20, 2, 300)\nDOCX_PART_BYTES_MAX = _env_int(\"OF_KB_DOCX_PART_BYTES_MAX\", 30000000, 1000, 500000000)\nTEXT_CHARS_MAX = _env_int(\"OF_KB_SOURCE_CHARS_MAX\", 200000, 1000, 2000000)\nFILE_TYPES: Tuple[str, ...] = (\"pdf\", \"docx\")\nMAX_TITLE_CHARS = 120\n\nW_NS = \"{http://schemas.openxmlformats.org/wordprocessingml/2006/main}\"\nDC_TITLE = \"{http://purl.org/dc/elements/1.1/}title\"\n_UNSAFE_XML = re.compile(rb\"<!DOCTYPE|<!ENTITY\", re.IGNORECASE)\n_BUILTIN_HEADING = re.compile(r\"^heading\\s*([1-9])$\", re.IGNORECASE)\n\n\nclass ExtractError(Exception):\n    \"\"\"Owner-readable extraction failure. ``code`` is one of bad_request,\n    too_large, unsupported_type, extract_failed, encrypted, no_text,\n    pdf_unavailable.\"\"\"\n\n    def __init__(self, code: str, message: str):\n        super().__init__(message)\n        self.code = code\n        self.message = message\n\n\ndef _mb(value: int) -> str:\n    return \"%g MB\" % (value / 1000000.0)\n\n\ndef file_type(filename: Any) -> str:\n    name = str(filename or \"\").strip().lower()\n    ext = name.rsplit(\".\", 1)[-1] if \".\" in name else \"\"\n    return ext if ext in FILE_TYPES else \"\"\n\n\ndef decode_base64(value: Any) -> bytes:\n    \"\"\"Bytes from a base64 string or data URL. The size limit is checked\n    on the encoded length first, so an oversized upload is refused\n    without decoding it.\"\"\"\n    text = str(value or \"\").strip()\n    if text.startswith(\"data:\") and \",\" in text:\n        text = text.split(\",\", 1)[1]\n    text = re.sub(r\"\\s+\", \"\", text)\n    if not text:\n        raise ExtractError(\"bad_request\", \"No file was received.\")\n    if len(text) * 3 // 4 > FILE_BYTES_MAX + 2:\n        raise ExtractError(\"too_large\", \"That file is larger than \"\n                           + _mb(FILE_BYTES_MAX) + \".\")\n    try:\n        data = base64.b64decode(text, validate=True)\n    except (binascii.Error, ValueError):\n        raise ExtractError(\"bad_request\",\n                           \"The file could not be read (damaged upload).\")\n    if not data:\n        raise ExtractError(\"bad_request\", \"No file was received.\")\n    return data\n\n\ndef _collapse(text: str) -> str:\n    return re.sub(r\"\\s+\", \" \", text).strip()\n\n\n# ---------------------------------------------------------------------------\n# DOCX\n# ---------------------------------------------------------------------------\n\ndef _read_part(archive: zipfile.ZipFile, name: str) -> Optional[bytes]:\n    try:\n        info = archive.getinfo(name)\n    except KeyError:\n        return None\n    if info.file_size > DOCX_PART_BYTES_MAX:\n        raise ExtractError(\"too_large\", \"This Word document is too large to\"\n                           \" import once unpacked.\")\n    data = archive.read(info)\n    if _UNSAFE_XML.search(data):\n        raise ExtractError(\"extract_failed\", \"This Word document contains\"\n                           \" unsupported markup.\")\n    return data\n\n\ndef _parse(data: bytes) -> ET.Element:\n    try:\n        return ET.fromstring(data)\n    except ET.ParseError:\n        raise ExtractError(\"extract_failed\", \"This file is not a valid Word\"\n                           \" document (.docx).\")\n\n\ndef _style_levels(styles: Optional[bytes]) -> Dict[str, int]:\n    \"\"\"styleId -> heading level from styles.xml: the English style name\n    (\"heading 2\", \"Title\") survives localisation even when the id does\n    not (\"berschrift2\"); an outline level also counts.\"\"\"\n    levels: Dict[str, int] = {}\n    if not styles:\n        return levels\n    root = _parse(styles)\n    for style in root.iter(W_NS + \"style\"):\n        style_id = style.get(W_NS + \"styleId\") or \"\"\n        name_el = style.find(W_NS + \"name\")\n        name = (name_el.get(W_NS + \"val\") if name_el is not None else \"\") or \"\"\n        match = _BUILTIN_HEADING.match(name.strip())\n        if match:\n            levels[style_id] = int(match.group(1))\n        elif name.strip().lower() == \"title\":\n            levels[style_id] = 1\n        else:\n            outline = style.find(W_NS + \"pPr/\" + W_NS + \"outlineLvl\")\n            if outline is not None:\n                try:\n                    levels[style_id] = int(outline.get(W_NS + \"val\") or 0) + 1\n                except ValueError:\n                    pass\n    return levels\n\n\ndef _builtin_level(style_id: str) -> int:\n    if style_id.lower() == \"title\":\n        return 1\n    match = re.match(r\"^heading([1-9])$\", style_id, re.IGNORECASE)\n    return int(match.group(1)) if match else 0\n\n\ndef _paragraph(p: ET.Element, levels: Dict[str, int]) -> Tuple[str, str]:\n    \"\"\"(kind, text) for one w:p - kind is heading:<n>, item or text.\"\"\"\n    parts: List[str] = []\n    for node in p.iter():\n        tag = node.tag\n        if tag == W_NS + \"t\":\n            parts.append(node.text or \"\")\n        elif tag == W_NS + \"tab\":\n            parts.append(\" \")\n        elif tag in (W_NS + \"br\", W_NS + \"cr\"):\n            parts.append(\"\\n\")\n    lines = [_collapse(line) for line in \"\".join(parts).split(\"\\n\")]\n    text = \"\\n\".join(line for line in lines if line)\n    if not text:\n        return \"text\", \"\"\n    ppr = p.find(W_NS + \"pPr\")\n    level = 0\n    numbered = False\n    if ppr is not None:\n        style = ppr.find(W_NS + \"pStyle\")\n        style_id = (style.get(W_NS + \"val\") if style is not None else \"\") or \"\"\n        if style_id:\n            level = levels.get(style_id) or _builtin_level(style_id)\n        outline = ppr.find(W_NS + \"outlineLvl\")\n        if not level and outline is not None:\n            try:\n                level = int(outline.get(W_NS + \"val\") or 0) + 1\n            except ValueError:\n                level = 0\n        numbered = ppr.find(W_NS + \"numPr\") is not None\n    if 0 < level <= 9:\n        return \"heading\", \"#\" * min(level, 6) + \" \" + _collapse(text)\n    if numbered:\n        return \"item\", \"- \" + text.replace(\"\\n\", \" \")\n    return \"text\", text\n\n\ndef _plain(kind: str, text: str) -> str:\n    \"\"\"Paragraph text without its markdown prefix (table cells).\"\"\"\n    if kind == \"heading\":\n        text = re.sub(r\"^#+ \", \"\", text)\n    elif kind == \"item\":\n        text = text[2:]\n    return text.replace(\"\\n\", \" \")\n\n\ndef _table(tbl: ET.Element, levels: Dict[str, int]) -> str:\n    rows: List[str] = []\n    for tr in tbl.findall(W_NS + \"tr\"):\n        cells: List[str] = []\n        for tc in tr.findall(W_NS + \"tc\"):\n            texts = [_plain(*_paragraph(p, levels)) for p in tc.iter(W_NS + \"p\")]\n            cells.append(_collapse(\" \".join(t for t in texts if t)))\n        if any(cells):\n            rows.append(\" | \".join(cells))\n    return \"\\n\".join(rows)\n\n\ndef _blocks(container: ET.Element, levels: Dict[str, int],\n            out: List[Tuple[str, str]]) -> None:\n    for child in list(container):\n        if child.tag == W_NS + \"p\":\n            kind, text = _paragraph(child, levels)\n            if text:\n                out.append((kind, text))\n        elif child.tag == W_NS + \"tbl\":\n            text = _table(child, levels)\n            if text:\n                out.append((\"table\", text))\n        elif child.tag == W_NS + \"sdt\":\n            content = child.find(W_NS + \"sdtContent\")\n            if content is not None:\n                _blocks(content, levels, out)\n        elif child.tag in (W_NS + \"customXml\", W_NS + \"smartTag\"):\n            _blocks(child, levels, out)\n\n\ndef docx_text(data: bytes) -> Tuple[str, str]:\n    \"\"\"(text, title) of a .docx file.\"\"\"\n    try:\n        archive = zipfile.ZipFile(io.BytesIO(data))\n    except (zipfile.BadZipFile, ValueError, OSError):\n        raise ExtractError(\"extract_failed\", \"This file is not a valid Word\"\n                           \" document (.docx).\")\n    with archive:\n        document = _read_part(archive, \"word/document.xml\")\n        if document is None:\n            raise ExtractError(\"extract_failed\", \"This file is not a valid\"\n                               \" Word document (.docx).\")\n        levels = _style_levels(_read_part(archive, \"word/styles.xml\"))\n        core = _read_part(archive, \"docProps/core.xml\")\n    root = _parse(document)\n    body = root.find(W_NS + \"body\")\n    found: List[Tuple[str, str]] = []\n    if body is not None:\n        _blocks(body, levels, found)\n    blocks: List[str] = []\n    previous = \"\"\n    for kind, text in found:\n        if kind == \"item\" and previous == \"item\":\n            blocks[-1] += \"\\n\" + text  # one list = one block\n        else:\n            blocks.append(text)\n        previous = kind\n    title = \"\"\n    if core:\n        node = _parse(core).find(\".//\" + DC_TITLE)\n        if node is not None and node.text:\n            title = _collapse(node.text)[:MAX_TITLE_CHARS]\n    return \"\\n\\n\".join(blocks), title\n\n\n# ---------------------------------------------------------------------------\n# PDF\n# ---------------------------------------------------------------------------\n\ndef _pdf_unavailable() -> ExtractError:\n    return ExtractError(\"pdf_unavailable\", \"PDF import is not available on\"\n                        \" this server yet (the pypdf package is not\"\n                        \" installed). Paste the text instead.\")\n\n\ndef pdf_text(data: bytes, max_chars: int) -> Dict[str, Any]:\n    \"\"\"Text, page count, metadata title and truncation flag of a PDF.\"\"\"\n    if b\"%PDF-\" not in data[:1024]:\n        raise ExtractError(\"extract_failed\", \"This file is not a valid PDF.\")\n    try:\n        from pypdf import PdfReader\n    except Exception:\n        raise _pdf_unavailable()\n    try:\n        reader = PdfReader(io.BytesIO(data))\n        encrypted = bool(reader.is_encrypted)\n    except Exception:\n        raise ExtractError(\"extract_failed\", \"This PDF could not be read (it\"\n                           \" may be damaged).\")\n    if encrypted:\n        try:\n            opened = reader.decrypt(\"\")\n        except Exception:\n            opened = 0\n        if not opened:\n            raise ExtractError(\"encrypted\", \"This PDF is password-protected.\"\n                               \" Remove the password and upload it again.\")\n    try:\n        total = len(reader.pages)\n    except Exception:\n        raise ExtractError(\"extract_failed\", \"This PDF could not be read (it\"\n                           \" may be damaged).\")\n    deadline = time.monotonic() + EXTRACT_SECONDS\n    truncated = total > PDF_PAGES_MAX\n    pages: List[str] = []\n    size = 0\n    for index in range(min(total, PDF_PAGES_MAX)):\n        if time.monotonic() > deadline:\n            truncated = True\n            break\n        try:\n            raw = reader.pages[index].extract_text() or \"\"\n        except Exception as error:  # one bad page never sinks the file\n            logger.info(\"pdf page %s skipped: %s\", index + 1, error)\n            continue\n        lines = [_collapse(line) for line in raw.replace(\"\\r\", \"\\n\").split(\"\\n\")]\n        text = \"\\n\".join(line for line in lines if line)\n        if not text:\n            continue\n        pages.append(text)\n        size += len(text) + 2\n        if size > max_chars:\n            truncated = True\n            break\n    text = \"\\n\\n\".join(pages)\n    if not text.strip():\n        raise ExtractError(\"no_text\", \"This PDF has no selectable text (it\"\n                           \" looks scanned). OCR is not supported yet - paste\"\n                           \" the text instead.\")\n    title = \"\"\n    try:\n        meta = reader.metadata\n        title = _collapse(str((meta.title if meta else \"\") or \"\"))[:MAX_TITLE_CHARS]\n    except Exception:\n        title = \"\"\n    return {\"text\": text, \"pages\": total, \"title\": title, \"truncated\": truncated}\n\n\ndef pdf_available() -> bool:\n    try:\n        import pypdf  # noqa: F401\n    except Exception:\n        return False\n    return True\n\n\n# ---------------------------------------------------------------------------\n# Entry point\n# ---------------------------------------------------------------------------\n\ndef _cap(text: str, max_chars: int) -> Tuple[str, bool]:\n    if len(text) <= max_chars:\n        return text, False\n    cut = text.rfind(\" \", 0, max_chars)\n    if cut < max_chars // 2:\n        cut = max_chars\n    return text[:cut].rstrip(), True\n\n\ndef extract(filename: Any, data: bytes,\n            max_chars: Optional[int] = None) -> Dict[str, Any]:\n    \"\"\"{type, text, title, pages, truncated} for an uploaded file.\n    Raises ExtractError with an owner-readable message.\"\"\"\n    name = str(filename or \"\").strip().lower()\n    kind = file_type(name)\n    if name.endswith(\".doc\"):\n        raise ExtractError(\"unsupported_type\", \"Older .doc files are not\"\n                           \" supported. Save the document as .docx or PDF and\"\n                           \" upload it again.\")\n    if not kind:\n        raise ExtractError(\"unsupported_type\", \"Only PDF and Word (.docx)\"\n                           \" files can be imported.\")\n    if len(data or b\"\") > FILE_BYTES_MAX:\n        raise ExtractError(\"too_large\", \"That file is larger than \"\n                           + _mb(FILE_BYTES_MAX) + \".\")\n    limit = max(1, int(max_chars or TEXT_CHARS_MAX))\n    if kind == \"docx\":\n        text, title = docx_text(data or b\"\")\n        if not text.strip():\n            raise ExtractError(\"no_text\", \"This Word document has no text to\"\n                               \" import.\")\n        text, truncated = _cap(text, limit)\n        return {\"type\": \"docx\", \"text\": text, \"title\": title, \"pages\": 0,\n                \"truncated\": truncated}\n    result = pdf_text(data or b\"\", limit)\n    text, cut = _cap(result[\"text\"], limit)\n    return {\"type\": \"pdf\", \"text\": text, \"title\": result[\"title\"],\n            \"pages\": result[\"pages\"],\n            \"truncated\": bool(result[\"truncated\"] or cut)}\n\n\ndef limits() -> Dict[str, Any]:\n    return {\"file_types\": list(FILE_TYPES), \"file_bytes_max\": FILE_BYTES_MAX,\n            \"pdf_pages_max\": PDF_PAGES_MAX, \"pdf_available\": pdf_available()}\n");
writeNewRepair("OmniFlow-Control-Plane/portal_kb_files.py", "class ExtractError", true,
    "\"\"\"Knowledge file import (\u00a7219): text out of PDF and Word (.docx) files.\n\nThe owner uploads a document on the Knowledge page; the website posts it\nbase64-encoded to ``POST /api/v1/portal/kb/extract``; this module returns\nthe readable text, which the owner reviews and then adds as a DRAFT\nsource through the normal ingest path (the KB auto-publish lock stays:\nnothing here stores or publishes anything).\n\n* DOCX is read with the standard library only (zipfile + ElementTree):\n  headings (built-in, localised style ids and outline levels) become\n  markdown ``#`` lines so the chunker labels sections, numbered/bulleted\n  paragraphs become ``- `` lines, table rows become ``a | b`` lines, and\n  content controls are included. Zip-bomb guard (declared unpacked size\n  checked before reading) and DTD/entity markup refused.\n* PDF uses ``pypdf`` (pure Python, imported lazily so the Control Plane\n  boots without it). Encrypted files that need a password, scanned pages\n  without selectable text (no OCR) and damaged files return honest\n  owner-readable errors.\n\nLimits come from env (no hardcoding):\nOF_KB_FILE_BYTES_MAX, OF_KB_PDF_PAGES_MAX, OF_KB_EXTRACT_SECONDS,\nOF_KB_DOCX_PART_BYTES_MAX, OF_KB_SOURCE_CHARS_MAX.\n\"\"\"\n\nimport base64\nimport binascii\nimport io\nimport logging\nimport os\nimport re\nimport time\nimport zipfile\nimport xml.etree.ElementTree as ET\nfrom typing import Any, Dict, List, Optional, Tuple\n\nlogger = logging.getLogger(\"omniflow.portal-kb-files\")\n\n\ndef _env_int(name: str, default: int, lo: int, hi: int) -> int:\n    try:\n        value = int(os.environ.get(name, \"\") or default)\n    except Exception:\n        value = default\n    return max(lo, min(hi, value))\n\n\nFILE_BYTES_MAX = _env_int(\"OF_KB_FILE_BYTES_MAX\", 3000000, 10000, 50000000)\nPDF_PAGES_MAX = _env_int(\"OF_KB_PDF_PAGES_MAX\", 300, 1, 5000)\nEXTRACT_SECONDS = _env_int(\"OF_KB_EXTRACT_SECONDS\", 20, 2, 300)\nDOCX_PART_BYTES_MAX = _env_int(\"OF_KB_DOCX_PART_BYTES_MAX\", 30000000, 1000, 500000000)\nTEXT_CHARS_MAX = _env_int(\"OF_KB_SOURCE_CHARS_MAX\", 200000, 1000, 2000000)\nFILE_TYPES: Tuple[str, ...] = (\"pdf\", \"docx\")\nMAX_TITLE_CHARS = 120\n\nW_NS = \"{http://schemas.openxmlformats.org/wordprocessingml/2006/main}\"\nDC_TITLE = \"{http://purl.org/dc/elements/1.1/}title\"\n_UNSAFE_XML = re.compile(rb\"<!DOCTYPE|<!ENTITY\", re.IGNORECASE)\n_BUILTIN_HEADING = re.compile(r\"^heading\\s*([1-9])$\", re.IGNORECASE)\n\n\nclass ExtractError(Exception):\n    \"\"\"Owner-readable extraction failure. ``code`` is one of bad_request,\n    too_large, unsupported_type, extract_failed, encrypted, no_text,\n    pdf_unavailable.\"\"\"\n\n    def __init__(self, code: str, message: str):\n        super().__init__(message)\n        self.code = code\n        self.message = message\n\n\ndef _mb(value: int) -> str:\n    return \"%g MB\" % (value / 1000000.0)\n\n\ndef file_type(filename: Any) -> str:\n    name = str(filename or \"\").strip().lower()\n    ext = name.rsplit(\".\", 1)[-1] if \".\" in name else \"\"\n    return ext if ext in FILE_TYPES else \"\"\n\n\ndef decode_base64(value: Any) -> bytes:\n    \"\"\"Bytes from a base64 string or data URL. The size limit is checked\n    on the encoded length first, so an oversized upload is refused\n    without decoding it.\"\"\"\n    text = str(value or \"\").strip()\n    if text.startswith(\"data:\") and \",\" in text:\n        text = text.split(\",\", 1)[1]\n    text = re.sub(r\"\\s+\", \"\", text)\n    if not text:\n        raise ExtractError(\"bad_request\", \"No file was received.\")\n    if len(text) * 3 // 4 > FILE_BYTES_MAX + 2:\n        raise ExtractError(\"too_large\", \"That file is larger than \"\n                           + _mb(FILE_BYTES_MAX) + \".\")\n    try:\n        data = base64.b64decode(text, validate=True)\n    except (binascii.Error, ValueError):\n        raise ExtractError(\"bad_request\",\n                           \"The file could not be read (damaged upload).\")\n    if not data:\n        raise ExtractError(\"bad_request\", \"No file was received.\")\n    return data\n\n\ndef _collapse(text: str) -> str:\n    return re.sub(r\"\\s+\", \" \", text).strip()\n\n\n# ---------------------------------------------------------------------------\n# DOCX\n# ---------------------------------------------------------------------------\n\ndef _read_part(archive: zipfile.ZipFile, name: str) -> Optional[bytes]:\n    try:\n        info = archive.getinfo(name)\n    except KeyError:\n        return None\n    if info.file_size > DOCX_PART_BYTES_MAX:\n        raise ExtractError(\"too_large\", \"This Word document is too large to\"\n                           \" import once unpacked.\")\n    data = archive.read(info)\n    if _UNSAFE_XML.search(data):\n        raise ExtractError(\"extract_failed\", \"This Word document contains\"\n                           \" unsupported markup.\")\n    return data\n\n\ndef _parse(data: bytes) -> ET.Element:\n    try:\n        return ET.fromstring(data)\n    except ET.ParseError:\n        raise ExtractError(\"extract_failed\", \"This file is not a valid Word\"\n                           \" document (.docx).\")\n\n\ndef _style_levels(styles: Optional[bytes]) -> Dict[str, int]:\n    \"\"\"styleId -> heading level from styles.xml: the English style name\n    (\"heading 2\", \"Title\") survives localisation even when the id does\n    not (\"berschrift2\"); an outline level also counts.\"\"\"\n    levels: Dict[str, int] = {}\n    if not styles:\n        return levels\n    root = _parse(styles)\n    for style in root.iter(W_NS + \"style\"):\n        style_id = style.get(W_NS + \"styleId\") or \"\"\n        name_el = style.find(W_NS + \"name\")\n        name = (name_el.get(W_NS + \"val\") if name_el is not None else \"\") or \"\"\n        match = _BUILTIN_HEADING.match(name.strip())\n        if match:\n            levels[style_id] = int(match.group(1))\n        elif name.strip().lower() == \"title\":\n            levels[style_id] = 1\n        else:\n            outline = style.find(W_NS + \"pPr/\" + W_NS + \"outlineLvl\")\n            if outline is not None:\n                try:\n                    levels[style_id] = int(outline.get(W_NS + \"val\") or 0) + 1\n                except ValueError:\n                    pass\n    return levels\n\n\ndef _builtin_level(style_id: str) -> int:\n    if style_id.lower() == \"title\":\n        return 1\n    match = re.match(r\"^heading([1-9])$\", style_id, re.IGNORECASE)\n    return int(match.group(1)) if match else 0\n\n\ndef _paragraph(p: ET.Element, levels: Dict[str, int]) -> Tuple[str, str]:\n    \"\"\"(kind, text) for one w:p - kind is heading:<n>, item or text.\"\"\"\n    parts: List[str] = []\n    for node in p.iter():\n        tag = node.tag\n        if tag == W_NS + \"t\":\n            parts.append(node.text or \"\")\n        elif tag == W_NS + \"tab\":\n            parts.append(\" \")\n        elif tag in (W_NS + \"br\", W_NS + \"cr\"):\n            parts.append(\"\\n\")\n    lines = [_collapse(line) for line in \"\".join(parts).split(\"\\n\")]\n    text = \"\\n\".join(line for line in lines if line)\n    if not text:\n        return \"text\", \"\"\n    ppr = p.find(W_NS + \"pPr\")\n    level = 0\n    numbered = False\n    if ppr is not None:\n        style = ppr.find(W_NS + \"pStyle\")\n        style_id = (style.get(W_NS + \"val\") if style is not None else \"\") or \"\"\n        if style_id:\n            level = levels.get(style_id) or _builtin_level(style_id)\n        outline = ppr.find(W_NS + \"outlineLvl\")\n        if not level and outline is not None:\n            try:\n                level = int(outline.get(W_NS + \"val\") or 0) + 1\n            except ValueError:\n                level = 0\n        numbered = ppr.find(W_NS + \"numPr\") is not None\n    if 0 < level <= 9:\n        return \"heading\", \"#\" * min(level, 6) + \" \" + _collapse(text)\n    if numbered:\n        return \"item\", \"- \" + text.replace(\"\\n\", \" \")\n    return \"text\", text\n\n\ndef _plain(kind: str, text: str) -> str:\n    \"\"\"Paragraph text without its markdown prefix (table cells).\"\"\"\n    if kind == \"heading\":\n        text = re.sub(r\"^#+ \", \"\", text)\n    elif kind == \"item\":\n        text = text[2:]\n    return text.replace(\"\\n\", \" \")\n\n\ndef _table(tbl: ET.Element, levels: Dict[str, int]) -> str:\n    rows: List[str] = []\n    for tr in tbl.findall(W_NS + \"tr\"):\n        cells: List[str] = []\n        for tc in tr.findall(W_NS + \"tc\"):\n            texts = [_plain(*_paragraph(p, levels)) for p in tc.iter(W_NS + \"p\")]\n            cells.append(_collapse(\" \".join(t for t in texts if t)))\n        if any(cells):\n            rows.append(\" | \".join(cells))\n    return \"\\n\".join(rows)\n\n\ndef _blocks(container: ET.Element, levels: Dict[str, int],\n            out: List[Tuple[str, str]]) -> None:\n    for child in list(container):\n        if child.tag == W_NS + \"p\":\n            kind, text = _paragraph(child, levels)\n            if text:\n                out.append((kind, text))\n        elif child.tag == W_NS + \"tbl\":\n            text = _table(child, levels)\n            if text:\n                out.append((\"table\", text))\n        elif child.tag == W_NS + \"sdt\":\n            content = child.find(W_NS + \"sdtContent\")\n            if content is not None:\n                _blocks(content, levels, out)\n        elif child.tag in (W_NS + \"customXml\", W_NS + \"smartTag\"):\n            _blocks(child, levels, out)\n\n\ndef docx_text(data: bytes) -> Tuple[str, str]:\n    \"\"\"(text, title) of a .docx file.\"\"\"\n    try:\n        archive = zipfile.ZipFile(io.BytesIO(data))\n    except (zipfile.BadZipFile, ValueError, OSError):\n        raise ExtractError(\"extract_failed\", \"This file is not a valid Word\"\n                           \" document (.docx).\")\n    with archive:\n        document = _read_part(archive, \"word/document.xml\")\n        if document is None:\n            raise ExtractError(\"extract_failed\", \"This file is not a valid\"\n                               \" Word document (.docx).\")\n        levels = _style_levels(_read_part(archive, \"word/styles.xml\"))\n        core = _read_part(archive, \"docProps/core.xml\")\n    root = _parse(document)\n    body = root.find(W_NS + \"body\")\n    found: List[Tuple[str, str]] = []\n    if body is not None:\n        _blocks(body, levels, found)\n    blocks: List[str] = []\n    previous = \"\"\n    for kind, text in found:\n        if kind == \"item\" and previous == \"item\":\n            blocks[-1] += \"\\n\" + text  # one list = one block\n        else:\n            blocks.append(text)\n        previous = kind\n    title = \"\"\n    if core:\n        node = _parse(core).find(\".//\" + DC_TITLE)\n        if node is not None and node.text:\n            title = _collapse(node.text)[:MAX_TITLE_CHARS]\n    return \"\\n\\n\".join(blocks), title\n\n\n# ---------------------------------------------------------------------------\n# PDF\n# ---------------------------------------------------------------------------\n\ndef _pdf_unavailable() -> ExtractError:\n    return ExtractError(\"pdf_unavailable\", \"PDF import is not available on\"\n                        \" this server yet (the pypdf package is not\"\n                        \" installed). Paste the text instead.\")\n\n\ndef pdf_text(data: bytes, max_chars: int) -> Dict[str, Any]:\n    \"\"\"Text, page count, metadata title and truncation flag of a PDF.\"\"\"\n    if b\"%PDF-\" not in data[:1024]:\n        raise ExtractError(\"extract_failed\", \"This file is not a valid PDF.\")\n    try:\n        from pypdf import PdfReader\n    except Exception:\n        raise _pdf_unavailable()\n    try:\n        reader = PdfReader(io.BytesIO(data))\n        encrypted = bool(reader.is_encrypted)\n    except Exception:\n        raise ExtractError(\"extract_failed\", \"This PDF could not be read (it\"\n                           \" may be damaged).\")\n    if encrypted:\n        try:\n            opened = reader.decrypt(\"\")\n        except Exception:\n            opened = 0\n        if not opened:\n            raise ExtractError(\"encrypted\", \"This PDF is password-protected.\"\n                               \" Remove the password and upload it again.\")\n    try:\n        total = len(reader.pages)\n    except Exception:\n        raise ExtractError(\"extract_failed\", \"This PDF could not be read (it\"\n                           \" may be damaged).\")\n    deadline = time.monotonic() + EXTRACT_SECONDS\n    truncated = total > PDF_PAGES_MAX\n    pages: List[str] = []\n    size = 0\n    for index in range(min(total, PDF_PAGES_MAX)):\n        if time.monotonic() > deadline:\n            truncated = True\n            break\n        try:\n            raw = reader.pages[index].extract_text() or \"\"\n        except Exception as error:  # one bad page never sinks the file\n            logger.info(\"pdf page %s skipped: %s\", index + 1, error)\n            continue\n        lines = [_collapse(line) for line in raw.replace(\"\\r\", \"\\n\").split(\"\\n\")]\n        text = \"\\n\".join(line for line in lines if line)\n        if not text:\n            continue\n        pages.append(text)\n        size += len(text) + 2\n        if size > max_chars:\n            truncated = True\n            break\n    text = \"\\n\\n\".join(pages)\n    if not text.strip():\n        raise ExtractError(\"no_text\", \"This PDF has no selectable text (it\"\n                           \" looks scanned). OCR is not supported yet - paste\"\n                           \" the text instead.\")\n    title = \"\"\n    try:\n        meta = reader.metadata\n        title = _collapse(str((meta.title if meta else \"\") or \"\"))[:MAX_TITLE_CHARS]\n    except Exception:\n        title = \"\"\n    return {\"text\": text, \"pages\": total, \"title\": title, \"truncated\": truncated}\n\n\ndef pdf_available() -> bool:\n    try:\n        import pypdf  # noqa: F401\n    except Exception:\n        return False\n    return True\n\n\n# ---------------------------------------------------------------------------\n# Entry point\n# ---------------------------------------------------------------------------\n\ndef _cap(text: str, max_chars: int) -> Tuple[str, bool]:\n    if len(text) <= max_chars:\n        return text, False\n    cut = text.rfind(\" \", 0, max_chars)\n    if cut < max_chars // 2:\n        cut = max_chars\n    return text[:cut].rstrip(), True\n\n\ndef extract(filename: Any, data: bytes,\n            max_chars: Optional[int] = None) -> Dict[str, Any]:\n    \"\"\"{type, text, title, pages, truncated} for an uploaded file.\n    Raises ExtractError with an owner-readable message.\"\"\"\n    name = str(filename or \"\").strip().lower()\n    kind = file_type(name)\n    if name.endswith(\".doc\"):\n        raise ExtractError(\"unsupported_type\", \"Older .doc files are not\"\n                           \" supported. Save the document as .docx or PDF and\"\n                           \" upload it again.\")\n    if not kind:\n        raise ExtractError(\"unsupported_type\", \"Only PDF and Word (.docx)\"\n                           \" files can be imported.\")\n    if len(data or b\"\") > FILE_BYTES_MAX:\n        raise ExtractError(\"too_large\", \"That file is larger than \"\n                           + _mb(FILE_BYTES_MAX) + \".\")\n    limit = max(1, int(max_chars or TEXT_CHARS_MAX))\n    if kind == \"docx\":\n        text, title = docx_text(data or b\"\")\n        if not text.strip():\n            raise ExtractError(\"no_text\", \"This Word document has no text to\"\n                               \" import.\")\n        text, truncated = _cap(text, limit)\n        return {\"type\": \"docx\", \"text\": text, \"title\": title, \"pages\": 0,\n                \"truncated\": truncated}\n    result = pdf_text(data or b\"\", limit)\n    text, cut = _cap(result[\"text\"], limit)\n    return {\"type\": \"pdf\", \"text\": text, \"title\": result[\"title\"],\n            \"pages\": result[\"pages\"],\n            \"truncated\": bool(result[\"truncated\"] or cut)}\n\n\ndef limits() -> Dict[str, Any]:\n    return {\"file_types\": list(FILE_TYPES), \"file_bytes_max\": FILE_BYTES_MAX,\n            \"pdf_pages_max\": PDF_PAGES_MAX, \"pdf_available\": pdf_available()}\n");
writeNewRepair("omniflow-backend-patch/portal_knowledge.py", "def kick_refresh(", false,
    "\"\"\"Knowledge engine (MASTER-UPGRADE engine 4): document / page ingestion,\ndeterministic chunking, versioning, health and keyword retrieval for the\nAI. D1 (delivered \u00a7211): ``portal_kb_semantic`` plugs meaning-based\nrecall into ``retrieve`` below (hybrid keyword + embeddings, reciprocal\nrank fusion) without changing the retrieval contract; keyword-only is\nthe automatic fallback.\n\nAudit-first (what already existed and stays):\n\n* ``portal_kb_entries`` (portal_kb) - owner-written Q&A answers with\n  trigger keywords. They still power the instant auto-reply on the\n  ingest path and the assist panel, untouched. Retrieval here searches\n  them TOGETHER with the new document chunks so the brain sees one\n  ranked knowledge list.\n* ``portal_kb_gaps`` (portal_growth) - unanswered questions; unchanged.\n* The KB auto-publish LOCK (owner law): nothing ingested here is ever\n  used by the AI until the owner publishes the source. New sources start\n  as ``draft``; ``published`` sources feed retrieval; ``paused`` sources\n  are kept but silent.\n\nSources (``portal_kb_sources``) are pasted text, uploaded text files\n(the browser reads .txt/.md/.csv/.json/.html and posts the text), PDF /\nWord files (\u00a7219: ``POST /kb/extract`` returns their text via\n``portal_kb_files`` for the owner to review - nothing is stored until\nthe owner adds it as a draft) or web pages (fetched server-side with an\nSSRF guard). Web pages can opt in to ``auto_refresh`` (\u00a7219): the\nconnector tick re-fetches them in the background every\nOF_KB_AUTO_REFRESH_HOURS; a changed page becomes a new version written\nby ``system`` and keeps its publication state (auto-publish lock). Every ingest writes a\nnew version snapshot (``portal_kb_source_versions``, raw text kept so a\nversion can be rolled back or re-chunked) and replaces the source's\nchunks (``portal_kb_chunks``). Retrieval is a single tenant-scoped SQL\ncandidate fetch (ILIKE on the query tokens) plus a deterministic\nBM25-style ranking in Python: term frequency, inverse candidate\nfrequency, heading/title boosts, phrase bonus and query coverage. Every\nhit carries a citation (source title + section) so the brain trace can\nshow where an answer came from. Fail-soft everywhere.\n\"\"\"\n\nimport html as html_lib\nimport ipaddress\nimport logging\nimport math\nimport os\nimport re\nimport socket\nimport threading\nimport time\nimport urllib.error\nimport urllib.parse\nimport urllib.request\nfrom datetime import datetime, timedelta, timezone\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nimport portal_kb_files\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-knowledge\")\n\nbp = Blueprint(\"portal_knowledge\", __name__, url_prefix=\"/api/v1/portal\")\n\nSOURCES_TABLE = \"portal_kb_sources\"\nVERSIONS_TABLE = \"portal_kb_source_versions\"\nCHUNKS_TABLE = \"portal_kb_chunks\"\nENTRIES_TABLE = \"portal_kb_entries\"\n\nKINDS: Tuple[str, ...] = (\"text\", \"file\", \"url\")\nSTATUSES: Tuple[str, ...] = (\"draft\", \"published\", \"paused\")\n\n\ndef _env_int(name: str, default: int, lo: int, hi: int) -> int:\n    try:\n        value = int(os.environ.get(name, \"\") or default)\n    except Exception:\n        value = default\n    return max(lo, min(hi, value))\n\n\nMAX_SOURCES = _env_int(\"OF_KB_SOURCES_MAX\", 50, 1, 1000)\nMAX_SOURCE_CHARS = _env_int(\"OF_KB_SOURCE_CHARS_MAX\", 200000, 1000, 2000000)\nCHUNK_CHARS = _env_int(\"OF_KB_CHUNK_CHARS\", 700, 200, 4000)\nCHUNK_OVERLAP = _env_int(\"OF_KB_CHUNK_OVERLAP\", 80, 0, 400)\nMAX_VERSIONS = _env_int(\"OF_KB_VERSIONS_MAX\", 10, 1, 100)\nURL_TIMEOUT = _env_int(\"OF_KB_URL_TIMEOUT\", 8, 2, 60)\nURL_BYTES_MAX = _env_int(\"OF_KB_URL_BYTES_MAX\", 1500000, 10000, 20000000)\nURL_STALE_DAYS = _env_int(\"OF_KB_URL_STALE_DAYS\", 30, 1, 365)\nRETRIEVE_CANDIDATES = _env_int(\"OF_KB_RETRIEVE_CANDIDATES\", 200, 10, 2000)\nQUERY_TOKENS_MAX = _env_int(\"OF_KB_QUERY_TOKENS_MAX\", 12, 3, 32)\nREFRESH_HOURS = _env_int(\"OF_KB_AUTO_REFRESH_HOURS\", 168, 1, 8760)\nREFRESH_BATCH = _env_int(\"OF_KB_REFRESH_BATCH\", 3, 1, 50)\nREFRESH_TICK_SECONDS = _env_int(\"OF_KB_REFRESH_TICK_SECONDS\", 900, 30, 86400)\nMAX_TITLE_CHARS = 120\nMAX_HEADING_CHARS = 160\nSNIPPET_CHARS = 400\nMIN_CHUNK_CHARS = 20\nINSERT_BATCH = 200\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_kb_sources (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  title TEXT NOT NULL DEFAULT '',\n  kind TEXT NOT NULL DEFAULT 'text',\n  origin TEXT NOT NULL DEFAULT '',\n  status TEXT NOT NULL DEFAULT 'draft',\n  version INT NOT NULL DEFAULT 0,\n  chunk_count INT NOT NULL DEFAULT 0,\n  char_count INT NOT NULL DEFAULT 0,\n  last_error TEXT NOT NULL DEFAULT '',\n  ingested_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_sources_client\n  ON portal_kb_sources (client_id, status);\nCREATE TABLE IF NOT EXISTS portal_kb_source_versions (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  source_id BIGINT NOT NULL,\n  version INT NOT NULL,\n  content TEXT NOT NULL DEFAULT '',\n  chunk_count INT NOT NULL DEFAULT 0,\n  char_count INT NOT NULL DEFAULT 0,\n  note TEXT NOT NULL DEFAULT '',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_source_versions_source\n  ON portal_kb_source_versions (client_id, source_id, version DESC);\nCREATE TABLE IF NOT EXISTS portal_kb_chunks (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  source_id BIGINT NOT NULL,\n  version INT NOT NULL DEFAULT 1,\n  position INT NOT NULL DEFAULT 0,\n  heading TEXT NOT NULL DEFAULT '',\n  content TEXT NOT NULL DEFAULT '',\n  char_count INT NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_chunks_source\n  ON portal_kb_chunks (client_id, source_id, position);\nALTER TABLE portal_kb_sources\n  ADD COLUMN IF NOT EXISTS auto_refresh BOOLEAN NOT NULL DEFAULT FALSE;\nALTER TABLE portal_kb_sources\n  ADD COLUMN IF NOT EXISTS checked_at TIMESTAMPTZ;\nALTER TABLE portal_kb_sources\n  ADD COLUMN IF NOT EXISTS refresh_attempt_at TIMESTAMPTZ;\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\n# ---------------------------------------------------------------------------\n# Pure text helpers: normalisation, tokens, HTML, chunking, ranking\n# ---------------------------------------------------------------------------\n\n#: Function words that carry no retrieval signal (English + Roman Urdu).\nSTOPWORDS = frozenset(\"\"\"\na an the is are am was were be been being of to in on at for and or but if\nthen than so as by with from into onto about over under up down out off this\nthat these those it its i me my we our you your he she they them their his\nher what which who whom whose when where why how do does did done have has\nhad having can could will would shall should may might must not no yes ok\nokay please plz pls hi hello hey thanks thank\nka ki ke ko ki se me mein main hai hain he hen ho hoon hun hu tha thi the\nthay thi ye yeh wo woh is us un in ab aur or ya bhi to per par pe ap aap tum\nmera meri mere hamara hamari apna apni apne kya kia kyun kyu kaise kaisa\nkaisi kab kahan kon konsa kar karo karen karein kro krna karna kiya raha\nrahi rahe hoga hogi honge chahiye chaiye bhai ji han haan nahi nhi na\n\"\"\".split())\n\n_WORD_RE = re.compile(r\"\\w+\", re.UNICODE)\n_BLANK_RE = re.compile(r\"\\n\\s*\\n\")\n_SENTENCE_RE = re.compile(r\"(?<=[.!?\\u06d4])\\s+\")\n_HEADING_RE = re.compile(r\"^(#{1,6}\\s+|\\d+(\\.\\d+)*[.)]\\s+)\")\n_LIST_OR_ROW_RE = re.compile(r\"^[-*\\u2022]\\s\")\n\n\ndef normalize(text: Any) -> str:\n    return re.sub(r\"\\s+\", \" \", str(text or \"\").lower()).strip()\n\n\ndef _collapse(text: Any) -> str:\n    \"\"\"Whitespace-collapsed but case-preserving (titles and headings are\n    shown to the owner; matching lower-cases separately).\"\"\"\n    return re.sub(r\"\\s+\", \" \", str(text or \"\")).strip()\n\n\ndef words(text: Any) -> List[str]:\n    return [w for w in _WORD_RE.findall(str(text or \"\").lower())]\n\n\ndef tokenize(text: Any, limit: int = 0, keep_stopwords: bool = False) -> List[str]:\n    \"\"\"Unique retrieval tokens in order of appearance (stop words and\n    one-character fragments dropped). ``limit`` keeps the longest tokens\n    first so the SQL candidate fetch uses the most selective ones.\"\"\"\n    seen: List[str] = []\n    for word in words(text):\n        if len(word) < 2:\n            continue\n        if not keep_stopwords and word in STOPWORDS:\n            continue\n        if word not in seen:\n            seen.append(word)\n    if limit and len(seen) > limit:\n        seen = sorted(seen, key=lambda w: (-len(w), seen.index(w)))[:limit]\n    return seen\n\n\ndef query_tokens(text: Any) -> List[str]:\n    \"\"\"Tokens for a customer question; falls back to stop words when the\n    question is made of them only (\\\"kya hai\\\") so short questions still\n    get a candidate fetch.\"\"\"\n    tokens = tokenize(text, QUERY_TOKENS_MAX)\n    if not tokens:\n        tokens = tokenize(text, QUERY_TOKENS_MAX, keep_stopwords=True)\n    return tokens\n\n\n_TAG_RE = re.compile(r\"<[^>]+>\")\n_DROP_RE = re.compile(\n    r\"<(script|style|noscript|svg|head|template|iframe)[^>]*>.*?</\\1\\s*>\",\n    re.IGNORECASE | re.DOTALL)\n_COMMENT_RE = re.compile(r\"<!--.*?-->\", re.DOTALL)\n_BLOCK_RE = re.compile(\n    r\"</?(p|div|br|li|ul|ol|tr|td|th|table|section|article|header|footer|\"\n    r\"h[1-6]|blockquote|pre|hr|dd|dt|dl|nav|main|aside|figure|figcaption)\"\n    r\"[^>]*>\", re.IGNORECASE)\n_HEAD_TAG_RE = re.compile(r\"<h([1-6])[^>]*>(.*?)</h\\1\\s*>\",\n                          re.IGNORECASE | re.DOTALL)\n_TITLE_RE = re.compile(r\"<title[^>]*>(.*?)</title>\", re.IGNORECASE | re.DOTALL)\n\n\ndef html_title(markup: str) -> str:\n    match = _TITLE_RE.search(str(markup or \"\"))\n    if not match:\n        return \"\"\n    return _collapse(html_lib.unescape(_TAG_RE.sub(\" \", match.group(1))))[\n        :MAX_TITLE_CHARS]\n\n\ndef html_to_text(markup: str) -> str:\n    \"\"\"Readable text from HTML: scripts/styles/head dropped, headings kept\n    as markdown-style lines (so chunking can carry them), block tags become\n    paragraph breaks, entities unescaped, whitespace collapsed.\"\"\"\n    text = str(markup or \"\")\n    text = _COMMENT_RE.sub(\" \", text)\n    text = _DROP_RE.sub(\" \", text)\n    text = _HEAD_TAG_RE.sub(\n        lambda m: \"\\n\\n\" + \"#\" * int(m.group(1)) + \" \"\n        + _TAG_RE.sub(\" \", m.group(2)).strip() + \"\\n\\n\", text)\n    text = _BLOCK_RE.sub(\"\\n\\n\", text)\n    text = _TAG_RE.sub(\" \", text)\n    text = html_lib.unescape(text)\n    text = text.replace(\"\\xa0\", \" \")\n    lines = [re.sub(r\"[ \\t]+\", \" \", line).strip() for line in text.split(\"\\n\")]\n    out: List[str] = []\n    blank = False\n    for line in lines:\n        if line:\n            out.append(line)\n            blank = False\n        elif not blank and out:\n            out.append(\"\")\n            blank = True\n    return \"\\n\".join(out).strip()\n\n\ndef clean_text(text: Any) -> str:\n    \"\"\"Normalise pasted / uploaded text: CRLF, tabs, trailing spaces, at\n    most one blank line in a row.\"\"\"\n    value = str(text or \"\").replace(\"\\r\\n\", \"\\n\").replace(\"\\r\", \"\\n\")\n    value = value.replace(\"\\t\", \" \").replace(\"\\x00\", \"\")\n    lines = [re.sub(r\"[ ]+\", \" \", line).rstrip() for line in value.split(\"\\n\")]\n    out: List[str] = []\n    blank = False\n    for line in lines:\n        if line.strip():\n            out.append(line)\n            blank = False\n        elif not blank and out:\n            out.append(\"\")\n            blank = True\n    return \"\\n\".join(out).strip()\n\n\ndef _is_heading(block: str) -> bool:\n    if \"\\n\" in block or len(block) > 80:\n        return False\n    if _HEADING_RE.match(block):\n        return True\n    stripped = block.rstrip(\":\").strip()\n    if block.endswith(\":\") and len(stripped.split()) <= 8:\n        return True\n    letters = [c for c in stripped if c.isalpha()]\n    return bool(letters) and len(stripped.split()) <= 6 and all(\n        c.isupper() for c in letters)\n\n\ndef _heading_text(block: str) -> str:\n    return _collapse(_HEADING_RE.sub(\"\", block).rstrip(\":\"))[:MAX_HEADING_CHARS]\n\n\ndef _split_heading(block: str) -> Tuple[str, str]:\n    \"\"\"(heading, body) for a block whose first line is a heading and the\n    rest a paragraph (\"Returns\\nItems can be returned...\"); (\"\", block)\n    otherwise. A first line counts as a heading when it is short, has no\n    sentence punctuation and the line after it is longer.\"\"\"\n    if \"\\n\" not in block:\n        return \"\", block\n    first, rest = block.split(\"\\n\", 1)\n    first, rest = first.strip(), rest.strip()\n    if not first or not rest:\n        return \"\", block\n    if _LIST_OR_ROW_RE.match(first) or \" | \" in first:\n        return \"\", block  # a list item or table row (PDF/Word import)\n    if _is_heading(first):\n        return _heading_text(first), rest\n    if (len(first) <= 60 and len(first.split()) <= 8\n            and not first.endswith((\".\", \"!\", \"?\", \",\", \";\"))\n            and len(rest.split(\"\\n\", 1)[0]) > len(first)):\n        return _heading_text(first), rest\n    return \"\", block\n\n\ndef _split_long(block: str, size: int) -> List[str]:\n    \"\"\"A block bigger than one chunk: pack sentences up to ``size``; a\n    single sentence longer than that is cut at its last space.\"\"\"\n    pieces: List[str] = []\n    current = \"\"\n    for sentence in _SENTENCE_RE.split(block):\n        sentence = sentence.strip()\n        if not sentence:\n            continue\n        parts: List[str] = []\n        while len(sentence) > size:\n            cut = sentence.rfind(\" \", 0, size)\n            if cut < size // 2:\n                cut = size\n            parts.append(sentence[:cut].strip())\n            sentence = sentence[cut:].strip()\n        if sentence:\n            parts.append(sentence)\n        for part in parts:\n            if current and len(current) + len(part) + 1 > size:\n                pieces.append(current)\n                current = part\n            else:\n                current = (current + \" \" + part).strip()\n    if current:\n        pieces.append(current)\n    return pieces\n\n\ndef _overlap_tail(text: str, overlap: int) -> str:\n    if overlap <= 0 or len(text) <= overlap:\n        return \"\"\n    tail = text[-overlap:]\n    cut = tail.find(\" \")\n    return tail[cut + 1:].strip() if cut >= 0 else tail.strip()\n\n\ndef chunk_text(text: str, size: int = 0,\n               overlap: Optional[int] = None) -> List[Dict[str, Any]]:\n    \"\"\"Deterministic, heading-aware chunks: paragraphs are packed up to\n    ``size`` characters, headings label the chunks that follow them, over-\n    long paragraphs split at sentence boundaries, and each chunk starts\n    with a short overlap from the previous one so context is not cut.\"\"\"\n    size = size or CHUNK_CHARS\n    overlap = CHUNK_OVERLAP if overlap is None else max(0, overlap)\n    overlap = min(overlap, size // 3)\n    blocks = [b.strip() for b in _BLANK_RE.split(clean_text(text)) if b.strip()]\n    chunks: List[Dict[str, Any]] = []\n    heading = \"\"\n    current = \"\"\n    current_heading = \"\"\n    previous_text = \"\"\n\n    def flush() -> None:\n        nonlocal current, previous_text\n        body = current.strip()\n        if body:\n            chunks.append({\"position\": len(chunks),\n                           \"heading\": current_heading, \"content\": body})\n            previous_text = body\n        current = \"\"\n\n    for block in blocks:\n        if _is_heading(block):\n            flush()\n            previous_text = \"\"  # no overlap across sections\n            heading = _heading_text(block)\n            continue\n        inline_heading, block = _split_heading(block)\n        if inline_heading:\n            flush()\n            previous_text = \"\"\n            heading = inline_heading\n        # long paragraphs are packed a little below ``size`` so the overlap\n        # carried in from the previous chunk still fits\n        pieces = [block] if len(block) <= size else _split_long(\n            block, max(size // 2, size - overlap))\n        for piece in pieces:\n            if current and len(current) + len(piece) + 2 > size:\n                flush()\n            if not current:\n                current_heading = heading\n                tail = _overlap_tail(previous_text, overlap)\n                current = (tail + \" \" + piece).strip() if tail and len(\n                    tail) + len(piece) + 1 <= size else piece\n            else:\n                current = current + \"\\n\\n\" + piece\n    flush()\n    if len(chunks) > 1:\n        # a tiny chunk is noise unless its heading makes it meaningful\n        # (\"Charges\" + \"Call 0300-1234567\" stays; \"B\" + \"ok\" goes)\n        chunks = [c for c in chunks if len(c[\"content\"]) >= MIN_CHUNK_CHARS\n                  or (c[\"heading\"] and len(c[\"heading\"]) + 1\n                      + len(c[\"content\"]) >= MIN_CHUNK_CHARS)]\n        for index, chunk in enumerate(chunks):\n            chunk[\"position\"] = index\n    return chunks\n\n\ndef _matches(word: str, token: str) -> bool:\n    \"\"\"Exact match, or a prefix match once the token is long enough to be\n    a stem (return -> returned/returns, deliver -> delivery). Short Roman\n    Urdu words (din, kab) stay exact.\"\"\"\n    if word == token:\n        return True\n    if len(token) >= 4 and word.startswith(token):\n        return True\n    return len(word) >= 4 and token.startswith(word) and len(token) - len(word) <= 3\n\n\ndef _count(token: str, word_list: List[str]) -> int:\n    return sum(1 for w in word_list if _matches(w, token))\n\n\ndef score_candidates(tokens: List[str], candidates: List[Dict[str, Any]],\n                     n: int) -> List[Dict[str, Any]]:\n    \"\"\"BM25-style ranking without an index: per-token tf saturation,\n    inverse candidate frequency, title/heading boost, adjacent-token phrase\n    bonus and query coverage. Deterministic; ties break on shorter text\n    then id.\"\"\"\n    if not tokens or not candidates:\n        return []\n    prepared = []\n    for row in candidates:\n        title_words = words(row.get(\"title\"))\n        body_words = words(row.get(\"content\")) + words(row.get(\"extra\"))\n        title_hits = {t: _count(t, title_words) for t in tokens}\n        body_hits = {t: _count(t, body_words) for t in tokens}\n        prepared.append((row, title_words, body_words, title_hits, body_hits))\n    total = len(prepared)\n    df = {t: sum(1 for p in prepared if p[3][t] or p[4][t]) for t in tokens}\n    idf = {t: math.log(1.0 + total / (1.0 + df[t])) + 0.1 for t in tokens}\n    ranked = []\n    for row, title_words, body_words, title_hits, body_hits in prepared:\n        matched: List[str] = []\n        score = 0.0\n        for token in tokens:\n            tf = body_hits[token]\n            in_title = title_hits[token] > 0\n            if not tf and not in_title:\n                continue\n            matched.append(token)\n            weight = (1.0 + math.log(1.0 + tf)) if tf else 0.6\n            if in_title:\n                weight += 1.5\n            score += weight * idf[token]\n        if not matched:\n            continue\n        if len(tokens) > 1:\n            text_words = title_words + body_words\n            for a, b in zip(tokens, tokens[1:]):\n                for i in range(len(text_words) - 1):\n                    if _matches(text_words[i], a) and _matches(text_words[i + 1], b):\n                        score += 1.0\n                        break\n        coverage = len(matched) / float(len(tokens))\n        score *= 0.5 + 0.5 * coverage\n        ranked.append((round(score, 4), matched, row))\n    ranked.sort(key=lambda item: (-item[0], len(str(item[2].get(\"content\") or \"\")),\n                                  int(item[2].get(\"id\") or 0)))\n    hits = []\n    for score, matched, row in ranked[:max(1, n)]:\n        content = str(row.get(\"content\") or \"\")\n        hits.append({\n            \"kind\": str(row.get(\"kind\") or \"entry\"),\n            \"id\": int(row.get(\"id\") or 0),\n            \"title\": str(row.get(\"title\") or \"\"),\n            \"content\": content[:SNIPPET_CHARS],\n            \"source_id\": int(row.get(\"source_id\") or 0),\n            \"source\": str(row.get(\"source_title\") or \"\"),\n            \"position\": int(row.get(\"position\") or 0),\n            \"score\": score,\n            \"matched\": matched,\n        })\n    return hits\n\n\n# ---------------------------------------------------------------------------\n# URL fetch with SSRF guard\n# ---------------------------------------------------------------------------\n\ndef assert_public_url(url: str, resolver=None) -> Tuple[str, str]:\n    \"\"\"Validate an owner-supplied URL: http(s) only, a real host name, no\n    credentials, and every resolved address public (no loopback, private,\n    link-local, multicast or reserved ranges). Returns (scheme, host).\n    Raises ValueError with an owner-readable message.\"\"\"\n    parsed = urllib.parse.urlsplit(str(url or \"\").strip())\n    if parsed.scheme not in (\"http\", \"https\"):\n        raise ValueError(\"Only http and https links are supported.\")\n    host = (parsed.hostname or \"\").strip().lower().rstrip(\".\")\n    if not host or parsed.username or parsed.password:\n        raise ValueError(\"That link is not a valid web address.\")\n    if host == \"localhost\" or host.endswith(\".localhost\") or host.endswith(\n            \".local\") or host.endswith(\".internal\"):\n        raise ValueError(\"Internal addresses cannot be fetched.\")\n    resolve = resolver or socket.getaddrinfo\n    try:\n        infos = resolve(host, parsed.port or (443 if parsed.scheme == \"https\"\n                                                else 80))\n    except Exception:\n        raise ValueError(\"That web address could not be resolved.\")\n    addresses = []\n    for info in infos or []:\n        try:\n            addresses.append(ipaddress.ip_address(info[4][0]))\n        except Exception:\n            continue\n    if not addresses:\n        raise ValueError(\"That web address could not be resolved.\")\n    for address in addresses:\n        if (address.is_private or address.is_loopback or address.is_link_local\n                or address.is_multicast or address.is_reserved\n                or address.is_unspecified):\n            raise ValueError(\"Internal addresses cannot be fetched.\")\n    return parsed.scheme, host\n\n\nclass _SafeRedirectHandler(urllib.request.HTTPRedirectHandler):\n    \"\"\"Re-validates every redirect target (a public page may not bounce\n    the fetch onto an internal address).\"\"\"\n\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\n        assert_public_url(newurl)\n        return super().redirect_request(req, fp, code, msg, headers, newurl)\n\n\ndef fetch_url(url: str) -> Tuple[str, str]:\n    \"\"\"Download a public page and return (text, title). Raises ValueError\n    with an owner-readable message on any problem.\"\"\"\n    assert_public_url(url)\n    req = urllib.request.Request(str(url).strip(), method=\"GET\")\n    req.add_header(\"Accept\", \"text/html, text/plain;q=0.9, */*;q=0.5\")\n    req.add_header(\"User-Agent\", \"OmniFlow-Knowledge/1.0 (+knowledge sources)\")\n    opener = urllib.request.build_opener(_SafeRedirectHandler())\n    try:\n        with opener.open(req, timeout=URL_TIMEOUT) as resp:\n            content_type = str(resp.headers.get(\"Content-Type\") or \"\").lower()\n            raw = resp.read(URL_BYTES_MAX + 1)\n    except urllib.error.HTTPError as error:\n        raise ValueError(\"The page answered with HTTP \" + str(error.code) + \".\")\n    except ValueError:\n        raise\n    except Exception:\n        raise ValueError(\"The page could not be fetched (timeout or \"\n                         \"connection error).\")\n    if len(raw) > URL_BYTES_MAX:\n        raise ValueError(\"The page is too large to import (limit \"\n                         + str(URL_BYTES_MAX // 1000) + \" KB).\")\n    kind = content_type.split(\";\")[0].strip()\n    if kind and not (kind.startswith(\"text/\") or kind in (\n            \"application/json\", \"application/xhtml+xml\", \"application/xml\")):\n        raise ValueError(\"Only web pages and text files can be imported \"\n                         \"from a link (got \" + kind + \").\")\n    charset = \"utf-8\"\n    match = re.search(r\"charset=([\\w-]+)\", content_type)\n    if match:\n        charset = match.group(1)\n    try:\n        body = raw.decode(charset, \"replace\")\n    except Exception:\n        body = raw.decode(\"utf-8\", \"replace\")\n    if kind in (\"text/html\", \"application/xhtml+xml\") or \"<html\" in body[:2000].lower():\n        return html_to_text(body), html_title(body)\n    return clean_text(body), \"\"\n\n\n# ---------------------------------------------------------------------------\n# DB helpers\n# ---------------------------------------------------------------------------\n\nSOURCE_COLS = (\"id, client_id, title, kind, origin, status, version, chunk_count,\"\n               \" char_count, last_error, ingested_at, created_at, updated_at,\"\n               \" auto_refresh, checked_at\")\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None or value == \"\":\n        return None\n    if hasattr(value, \"isoformat\"):\n        return value.isoformat()\n    return str(value)\n\n\ndef _is_stale(row: Dict[str, Any]) -> bool:\n    \"\"\"A web page neither indexed nor confirmed unchanged (automatic\n    refresh) within OF_KB_URL_STALE_DAYS.\"\"\"\n    if str(row.get(\"kind\") or \"\") != \"url\":\n        return False\n    stamps = []\n    for key in (\"ingested_at\", \"checked_at\"):\n        stamp = row.get(key)\n        if isinstance(stamp, datetime):\n            stamps.append(stamp if stamp.tzinfo else stamp.replace(\n                tzinfo=timezone.utc))\n    if not stamps:\n        return False\n    return max(stamps) < datetime.now(timezone.utc) - timedelta(days=URL_STALE_DAYS)\n\n\ndef source_public(row: Dict[str, Any]) -> Dict[str, Any]:\n    return {\n        \"id\": int(row.get(\"id\") or 0),\n        \"title\": str(row.get(\"title\") or \"\"),\n        \"kind\": str(row.get(\"kind\") or \"text\"),\n        \"origin\": str(row.get(\"origin\") or \"\"),\n        \"status\": str(row.get(\"status\") or \"draft\"),\n        \"version\": int(row.get(\"version\") or 0),\n        \"chunk_count\": int(row.get(\"chunk_count\") or 0),\n        \"char_count\": int(row.get(\"char_count\") or 0),\n        \"last_error\": str(row.get(\"last_error\") or \"\"),\n        \"stale\": _is_stale(row),\n        \"auto_refresh\": bool(row.get(\"auto_refresh\"))\n        and str(row.get(\"kind\") or \"\") == \"url\",\n        \"checked_at\": _iso(row.get(\"checked_at\")),\n        \"ingested_at\": _iso(row.get(\"ingested_at\")),\n        \"created_at\": _iso(row.get(\"created_at\")),\n        \"updated_at\": _iso(row.get(\"updated_at\")),\n    }\n\n\ndef get_source(cur, client_id: int, source_id: int) -> Optional[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT \" + SOURCE_COLS + \" FROM \" + portal_db._q(SOURCES_TABLE) +\n        \" WHERE id = %s AND client_id = %s\",\n        (int(source_id), client_id),\n    )\n    rows = portal_db.rows(cur)\n    return rows[0] if rows else None\n\n\ndef list_sources(cur, client_id: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT \" + SOURCE_COLS + \" FROM \" + portal_db._q(SOURCES_TABLE) +\n        \" WHERE client_id = %s ORDER BY updated_at DESC, id DESC LIMIT %s\",\n        (client_id, MAX_SOURCES + 50),\n    )\n    return portal_db.rows(cur)\n\n\ndef health(sources: List[Dict[str, Any]]) -> Dict[str, Any]:\n    out = {\"sources\": len(sources), \"published\": 0, \"drafts\": 0, \"paused\": 0,\n           \"chunks\": 0, \"errors\": 0, \"stale\": 0}\n    for row in sources:\n        status = str(row.get(\"status\") or \"draft\")\n        if status == \"published\":\n            out[\"published\"] += 1\n            out[\"chunks\"] += int(row.get(\"chunk_count\") or 0)\n        elif status == \"paused\":\n            out[\"paused\"] += 1\n        else:\n            out[\"drafts\"] += 1\n        if str(row.get(\"last_error\") or \"\"):\n            out[\"errors\"] += 1\n        if _is_stale(row):\n            out[\"stale\"] += 1\n    return out\n\n\ndef stored_text(text: Any) -> str:\n    \"\"\"Exactly what ingest stores as a version (the refresh job compares\n    a fresh fetch against it).\"\"\"\n    return clean_text(text)[:MAX_SOURCE_CHARS]\n\n\ndef ingest(cur, client_id: int, source: Dict[str, Any], text: str,\n           note: str = \"\", actor_user_id: Optional[int] = None,\n           origin: Optional[str] = None,\n           actor_kind: str = \"customer_user\") -> Dict[str, Any]:\n    \"\"\"Chunk ``text`` for ``source``: replace its chunks, snapshot the raw\n    text as the next version, prune old versions, refresh the counters and\n    audit. ``origin`` replaces the stored file name (new upload of a file\n    source). Returns the updated source row. Never publishes.\"\"\"\n    source_id = int(source.get(\"id\") or 0)\n    content = stored_text(text)\n    chunks = chunk_text(content)\n    version = int(source.get(\"version\") or 0) + 1\n    cur.execute(\n        \"DELETE FROM \" + portal_db._q(CHUNKS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s\",\n        (client_id, source_id),\n    )\n    for start in range(0, len(chunks), INSERT_BATCH):\n        batch = chunks[start:start + INSERT_BATCH]\n        values = \", \".join([\"(%s, %s, %s, %s, %s, %s, %s)\"] * len(batch))\n        params: List[Any] = []\n        for chunk in batch:\n            params.extend([client_id, source_id, version, chunk[\"position\"],\n                           chunk[\"heading\"], chunk[\"content\"],\n                           len(chunk[\"content\"])])\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(CHUNKS_TABLE) +\n            \" (client_id, source_id, version, position, heading, content,\"\n            \" char_count) VALUES \" + values,\n            tuple(params),\n        )\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(VERSIONS_TABLE) +\n        \" (client_id, source_id, version, content, chunk_count, char_count,\"\n        \" note) VALUES (%s, %s, %s, %s, %s, %s, %s)\",\n        (client_id, source_id, version, content, len(chunks), len(content),\n         str(note or \"\")[:200]),\n    )\n    cur.execute(\n        \"DELETE FROM \" + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s AND version <= %s\",\n        (client_id, source_id, version - MAX_VERSIONS),\n    )\n    params: List[Any] = [version, len(chunks), len(content)]\n    if origin:\n        params.append(str(origin)[:200])\n    cur.execute(\n        \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n        \" SET version = %s, chunk_count = %s, char_count = %s, last_error = '',\"\n        + (\" origin = %s,\" if origin else \"\") +\n        \" ingested_at = NOW(), checked_at = NOW(), updated_at = NOW()\"\n        \" WHERE id = %s AND client_id = %s RETURNING \" + SOURCE_COLS,\n        tuple(params + [source_id, client_id]),\n    )\n    rows = portal_db.rows(cur)\n    updated = rows[0] if rows else dict(source, version=version,\n                                        chunk_count=len(chunks),\n                                        char_count=len(content), last_error=\"\")\n    portal_db.log_action(\n        cur, client_id, \"kb.source_ingested\", actor_kind, actor_user_id,\n        None, \"Indexed '\" + str(updated.get(\"title\") or \"\")[:60] + \"' v\"\n        + str(version) + \" (\" + str(len(chunks)) + \" sections, \"\n        + str(len(content)) + \" chars)\" + (\" - \" + note if note else \"\"),\n    )\n    return updated\n\n\ndef record_error(cur, client_id: int, source_id: int, message: str) -> None:\n    cur.execute(\n        \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n        \" SET last_error = %s, updated_at = NOW()\"\n        \" WHERE id = %s AND client_id = %s\",\n        (str(message or \"\")[:300], int(source_id), client_id),\n    )\n\n\ndef version_content(cur, client_id: int, source_id: int,\n                    version: Optional[int] = None) -> Optional[Dict[str, Any]]:\n    where = \" AND version = %s\" if version else \"\"\n    params: Tuple[Any, ...] = (client_id, int(source_id)) + (\n        (int(version),) if version else ())\n    cur.execute(\n        \"SELECT version, content, chunk_count, char_count, note, created_at FROM \"\n        + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s\" + where +\n        \" ORDER BY version DESC LIMIT 1\",\n        params,\n    )\n    rows = portal_db.rows(cur)\n    return rows[0] if rows else None\n\n\ndef list_versions(cur, client_id: int, source_id: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT version, chunk_count, char_count, note, created_at FROM \"\n        + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s ORDER BY version DESC LIMIT %s\",\n        (client_id, int(source_id), MAX_VERSIONS),\n    )\n    return [{\"version\": int(r.get(\"version\") or 0),\n             \"chunk_count\": int(r.get(\"chunk_count\") or 0),\n             \"char_count\": int(r.get(\"char_count\") or 0),\n             \"note\": str(r.get(\"note\") or \"\"),\n             \"created_at\": _iso(r.get(\"created_at\"))}\n            for r in portal_db.rows(cur)]\n\n\ndef retrieve(cur, client_id: int, query: str, n: int = 5,\n             include_entries: bool = True) -> List[Dict[str, Any]]:\n    \"\"\"The one knowledge read for the brain and the owner's tester: active\n    Q&A entries + chunks of PUBLISHED sources, ranked deterministically.\n\n    Keyword ranking first (BM25-style over the query tokens); when the\n    semantic index is active and populated, meaning-based hits are fused\n    in (portal_kb_semantic.hybrid). Every hit carries ``via``\n    (keyword|semantic|both) and ``semantic`` (similarity or None).\n    Blank query -> [] without touching the DB.\"\"\"\n    if not str(query or \"\").strip():\n        return []\n    tokens = query_tokens(query)\n    keyword = _keyword_hits(cur, client_id, tokens,\n                            max(n, SEMANTIC_KEYWORD_POOL), include_entries)\n    try:\n        import portal_kb_semantic\n\n        fused = portal_kb_semantic.hybrid(cur, client_id, query, keyword, n,\n                                          include_entries, SNIPPET_CHARS)\n    except Exception as error:  # fail-soft: keyword ranking stands\n        logger.info(\"semantic retrieval skipped: %s\", error)\n        fused = None\n    if fused is not None:\n        return fused\n    out = []\n    for hit in keyword[:max(1, n)]:\n        hit[\"via\"] = \"keyword\"\n        hit[\"semantic\"] = None\n        out.append(hit)\n    return out\n\n\nSEMANTIC_KEYWORD_POOL = _env_int(\"OF_KB_HYBRID_KEYWORD_POOL\", 12, 1, 100)\n\n\ndef _keyword_hits(cur, client_id: int, tokens: List[str], n: int,\n                  include_entries: bool) -> List[Dict[str, Any]]:\n    \"\"\"Keyword candidates (ILIKE on the tokens) ranked by score_candidates.\n    No tokens -> [] without touching the DB.\"\"\"\n    if not tokens:\n        return []\n    patterns = [\"%\" + t + \"%\" for t in tokens]\n    limit = RETRIEVE_CANDIDATES\n    parts: List[str] = []\n    params: List[Any] = []\n    if include_entries:\n        parts.append(\n            \"SELECT 'entry' AS kind, e.id AS id, e.title AS title,\"\n            \" e.content AS content, e.keywords AS extra, 0 AS source_id,\"\n            \" '' AS source_title, 0 AS position FROM \"\n            + portal_db._q(ENTRIES_TABLE) + \" e\"\n            \" WHERE e.client_id = %s AND e.is_active IS TRUE\"\n            \" AND (e.title ILIKE ANY(%s) OR e.keywords ILIKE ANY(%s)\"\n            \" OR e.content ILIKE ANY(%s))\")\n        params.extend([client_id, patterns, patterns, patterns])\n    parts.append(\n        \"SELECT 'chunk' AS kind, c.id AS id, c.heading AS title,\"\n        \" c.content AS content, '' AS extra, c.source_id AS source_id,\"\n        \" s.title AS source_title, c.position AS position FROM \"\n        + portal_db._q(CHUNKS_TABLE) + \" c JOIN \" + portal_db._q(SOURCES_TABLE) +\n        \" s ON s.id = c.source_id AND s.client_id = c.client_id\"\n        \" WHERE c.client_id = %s AND s.status = 'published'\"\n        \" AND (c.heading ILIKE ANY(%s) OR c.content ILIKE ANY(%s))\")\n    params.extend([client_id, patterns, patterns])\n    params.append(limit)\n    cur.execute(\" UNION ALL \".join(parts) + \" LIMIT %s\", tuple(params))\n    return score_candidates(tokens, portal_db.rows(cur), n)\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\ndef _human_or_error():\n    principal, error = _principal_or_error()\n    if error:\n        return None, error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return None, forbidden\n    return principal, None\n\n\ndef _bad(message: str, code: str = \"bad_request\", status: int = 400):\n    return jsonify({\"error\": {\"code\": code, \"message\": message}}), status\n\n\ndef _limits() -> Dict[str, Any]:\n    out = {\"max_sources\": MAX_SOURCES, \"max_chars\": MAX_SOURCE_CHARS,\n           \"chunk_chars\": CHUNK_CHARS, \"max_versions\": MAX_VERSIONS,\n           \"kinds\": list(KINDS), \"refresh_hours\": REFRESH_HOURS}\n    out.update(portal_kb_files.limits())\n    return out\n\n\ndef _title_from(text: str, fallback: str) -> str:\n    for line in str(text or \"\").split(\"\\n\"):\n        line = _HEADING_RE.sub(\"\", line).strip().strip(\"#\").strip()\n        if line:\n            return line[:MAX_TITLE_CHARS]\n    return fallback[:MAX_TITLE_CHARS]\n\n\n@bp.get(\"/kb/sources\")\ndef get_sources():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            rows = list_sources(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"sources\": [source_public(r) for r in rows],\n                    \"health\": health(rows), \"limits\": _limits()}), 200\n\n\n@bp.post(\"/kb/sources\")\ndef post_source():\n    \"\"\"Create a source and index it right away. It stays a DRAFT until the\n    owner publishes it (KB auto-publish lock).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    kind = str(payload.get(\"kind\") or \"text\").strip().lower()\n    if kind not in KINDS:\n        return _bad(\"kind must be one of text, file, url.\")\n    title = str(payload.get(\"title\") or \"\").strip()[:MAX_TITLE_CHARS]\n    origin = \"\"\n    auto_refresh = kind == \"url\" and payload.get(\"auto_refresh\") is True\n    if kind == \"url\":\n        url = str(payload.get(\"url\") or \"\").strip()[:2000]\n        if not url:\n            return _bad(\"A web address is required.\")\n        try:\n            text, page_title = fetch_url(url)\n        except ValueError as problem:\n            return _bad(str(problem), \"fetch_failed\")\n        origin = url\n        title = title or page_title or _title_from(text, url)\n    else:\n        text = clean_text(payload.get(\"text\"))\n        origin = str(payload.get(\"filename\") or \"\").strip()[:200] if kind == \"file\" else \"\"\n        title = title or _title_from(text, origin or \"Pasted text\")\n    if len(text) < MIN_CHUNK_CHARS:\n        return _bad(\"There is not enough text to index (at least \"\n                    + str(MIN_CHUNK_CHARS) + \" characters).\")\n    if len(text) > MAX_SOURCE_CHARS:\n        return _bad(\"That source is too long (limit \"\n                    + str(MAX_SOURCE_CHARS) + \" characters). Split it into\"\n                    \" smaller documents.\", \"too_long\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"SELECT COUNT(*) AS n FROM \" + portal_db._q(SOURCES_TABLE) +\n                \" WHERE client_id = %s\",\n                (client_id,),\n            )\n            rows = portal_db.rows(cur)\n            if int((rows[0] if rows else {}).get(\"n\") or 0) >= MAX_SOURCES:\n                conn.rollback()\n                return _bad(\"This workspace already has the maximum of \"\n                            + str(MAX_SOURCES) + \" sources.\", \"limit\", 409)\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(SOURCES_TABLE) +\n                \" (client_id, title, kind, origin, status, auto_refresh)\"\n                \" VALUES (%s, %s, %s, %s, 'draft', %s) RETURNING \" + SOURCE_COLS,\n                (client_id, title, kind, origin, auto_refresh),\n            )\n            rows = portal_db.rows(cur)\n            source = rows[0] if rows else {\"id\": 0, \"title\": title,\n                                           \"kind\": kind, \"version\": 0}\n            source = ingest(cur, client_id, source, text, \"created\",\n                            principal.get(\"user_id\"))\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.put(\"/kb/sources/<int:source_id>\")\ndef put_source(source_id: int):\n    \"\"\"Owner review: publish / pause / back to draft, rename, and switch\n    automatic refresh of a web page on or off (audited).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    status = str(payload.get(\"status\") or \"\").strip().lower()\n    title = str(payload.get(\"title\") or \"\").strip()[:MAX_TITLE_CHARS]\n    if status and status not in STATUSES:\n        return _bad(\"status must be one of draft, published, paused.\")\n    auto_refresh = payload.get(\"auto_refresh\")\n    if auto_refresh is not None and not isinstance(auto_refresh, bool):\n        return _bad(\"auto_refresh must be true or false.\")\n    if not status and not title and auto_refresh is None:\n        return _bad(\"Nothing to update.\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            if status == \"published\" and int(source.get(\"chunk_count\") or 0) == 0:\n                conn.rollback()\n                return _bad(\"This source has no indexed text yet. Re-index it\"\n                            \" before publishing.\", \"empty_source\")\n            if auto_refresh and str(source.get(\"kind\") or \"\") != \"url\":\n                conn.rollback()\n                return _bad(\"Automatic refresh is only available for web\"\n                            \" pages.\")\n            sets = [\"updated_at = NOW()\"]\n            params: List[Any] = []\n            if status:\n                sets.append(\"status = %s\")\n                params.append(status)\n            if title:\n                sets.append(\"title = %s\")\n                params.append(title)\n            if auto_refresh is not None:\n                sets.append(\"auto_refresh = %s\")\n                params.append(auto_refresh)\n            params.extend([int(source_id), client_id])\n            cur.execute(\n                \"UPDATE \" + portal_db._q(SOURCES_TABLE) + \" SET \" +\n                \", \".join(sets) + \" WHERE id = %s AND client_id = %s RETURNING \"\n                + SOURCE_COLS,\n                tuple(params),\n            )\n            rows = portal_db.rows(cur)\n            updated = rows[0] if rows else dict(source)\n            if status and status != str(source.get(\"status\") or \"\"):\n                portal_db.log_action(\n                    cur, client_id, \"kb.source_\" + status, \"customer_user\",\n                    principal.get(\"user_id\"), None,\n                    (\"Published\" if status == \"published\" else\n                     \"Paused\" if status == \"paused\" else \"Unpublished\")\n                    + \" source '\" + str(updated.get(\"title\") or \"\")[:60] + \"'\",\n                )\n            if auto_refresh is not None and auto_refresh != bool(\n                    source.get(\"auto_refresh\")):\n                portal_db.log_action(\n                    cur, client_id, \"kb.source_auto_refresh_\"\n                    + (\"on\" if auto_refresh else \"off\"), \"customer_user\",\n                    principal.get(\"user_id\"), None,\n                    (\"Turned on\" if auto_refresh else \"Turned off\")\n                    + \" automatic refresh for '\"\n                    + str(updated.get(\"title\") or \"\")[:60] + \"'\",\n                )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(updated)}), 200\n\n\n@bp.delete(\"/kb/sources/<int:source_id>\")\ndef delete_source(source_id: int):\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(CHUNKS_TABLE) +\n                \" WHERE client_id = %s AND source_id = %s\",\n                (client_id, int(source_id)),\n            )\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(VERSIONS_TABLE) +\n                \" WHERE client_id = %s AND source_id = %s\",\n                (client_id, int(source_id)),\n            )\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(SOURCES_TABLE) +\n                \" WHERE id = %s AND client_id = %s\",\n                (int(source_id), client_id),\n            )\n            portal_db.log_action(\n                cur, client_id, \"kb.source_deleted\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                \"Deleted source '\" + str(source.get(\"title\") or \"\")[:60] + \"'\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.post(\"/kb/sources/<int:source_id>/reindex\")\ndef reindex_source(source_id: int):\n    \"\"\"Re-fetch a web page, or re-chunk pasted/uploaded text (new text in\n    the body, else the latest stored version). A file source given new\n    text plus ``filename`` is a new upload (the stored file name follows).\n    Publication state is kept.\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    new_text = clean_text(payload.get(\"text\"))\n    filename = str(payload.get(\"filename\") or \"\").strip()[:200]\n    if new_text and len(new_text) > MAX_SOURCE_CHARS:\n        return _bad(\"That text is too long (limit \" + str(MAX_SOURCE_CHARS)\n                    + \" characters).\", \"too_long\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            note = \"re-indexed\"\n            origin = None\n            if str(source.get(\"kind\") or \"\") == \"url\":\n                try:\n                    text, _title = fetch_url(str(source.get(\"origin\") or \"\"))\n                except ValueError as problem:\n                    record_error(cur, client_id, source_id, str(problem))\n                    conn.commit()\n                    return _bad(str(problem), \"fetch_failed\")\n                note = \"re-fetched\"\n            elif new_text:\n                text = new_text\n                note = \"text replaced\"\n                if filename and str(source.get(\"kind\") or \"\") == \"file\":\n                    note = \"new upload: \" + filename\n                    origin = filename\n            else:\n                latest = version_content(cur, client_id, source_id)\n                text = str((latest or {}).get(\"content\") or \"\")\n                if len(text) < MIN_CHUNK_CHARS:\n                    conn.rollback()\n                    return _bad(\"No stored text to re-index. Paste the text\"\n                                \" again.\", \"empty_source\")\n            if len(text) < MIN_CHUNK_CHARS:\n                record_error(cur, client_id, source_id,\n                             \"The page returned no readable text.\")\n                conn.commit()\n                return _bad(\"The page returned no readable text.\",\n                            \"fetch_failed\")\n            source = ingest(cur, client_id, source, text, note,\n                            principal.get(\"user_id\"), origin)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.get(\"/kb/sources/<int:source_id>/versions\")\ndef get_versions(source_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            versions = list_versions(cur, client_id, source_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"source\": source_public(source), \"versions\": versions}), 200\n\n\n@bp.post(\"/kb/sources/<int:source_id>/rollback\")\ndef rollback_source(source_id: int):\n    \"\"\"Re-index from an earlier version's stored text (creates a new\n    version, so history is never rewritten).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    try:\n        version = int(payload.get(\"version\") or 0)\n    except Exception:\n        version = 0\n    if version <= 0:\n        return _bad(\"version is required.\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            snapshot = version_content(cur, client_id, source_id, version)\n            if snapshot is None or len(str(snapshot.get(\"content\") or \"\")) < MIN_CHUNK_CHARS:\n                conn.rollback()\n                return _bad(\"That version is no longer stored.\", \"not_found\", 404)\n            source = ingest(cur, client_id, source, str(snapshot.get(\"content\")),\n                            \"rolled back to v\" + str(version),\n                            principal.get(\"user_id\"))\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.get(\"/kb/search\")\ndef search_knowledge():\n    \"\"\"Owner tester: exactly what the AI would retrieve for a question.\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    query = str(request.args.get(\"q\") or \"\").strip()[:300]\n    if not query:\n        return _bad(\"q is required.\")\n    try:\n        n = int(request.args.get(\"n\") or 5)\n    except Exception:\n        n = 5\n    n = max(1, min(10, n))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            hits = retrieve(cur, client_id, query, n)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"query\": query, \"tokens\": query_tokens(query),\n                    \"hits\": hits}), 200\n\n\n@bp.post(\"/kb/extract\")\ndef extract_file():\n    \"\"\"\u00a7219: text of an uploaded PDF / Word file for the owner to review.\n    Human-only; stores nothing (the reviewed text is added through POST\n    /kb/sources as a draft, or as a new version through /reindex).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    payload = request.get_json(silent=True) or {}\n    filename = str(payload.get(\"filename\") or \"\").strip()[:200]\n    if not filename:\n        return _bad(\"filename is required.\")\n    try:\n        data = portal_kb_files.decode_base64(payload.get(\"file_base64\"))\n        result = portal_kb_files.extract(filename, data, MAX_SOURCE_CHARS)\n    except portal_kb_files.ExtractError as problem:\n        return _bad(problem.message, problem.code,\n                    413 if problem.code == \"too_large\" else 400)\n    except Exception as problem:  # fail-soft: never a 500 for a bad file\n        logger.info(\"kb extract failed: %s\", problem)\n        return _bad(\"That file could not be read.\", \"extract_failed\")\n    return jsonify({\"filename\": filename, \"type\": result[\"type\"],\n                    \"text\": result[\"text\"], \"title\": result[\"title\"],\n                    \"pages\": result[\"pages\"], \"truncated\": result[\"truncated\"],\n                    \"chars\": len(result[\"text\"])}), 200\n\n\n# ---------------------------------------------------------------------------\n# \u00a7219 scheduled re-fetch of web pages (opt-in per source)\n# ---------------------------------------------------------------------------\n\n_DUE_AT = (\"GREATEST(COALESCE(checked_at, ingested_at, 'epoch'::timestamptz),\"\n           \" COALESCE(refresh_attempt_at, 'epoch'::timestamptz))\")\n_DUE = _DUE_AT + \" < NOW() - make_interval(hours => %s)\"\n_REFRESH_LOCK = threading.Lock()\n_REFRESH_RUNNING: set = set()\n_REFRESH_LAST: Dict[int, float] = {}\n\n\ndef due_refresh(cur, client_id: int, limit: int = 0) -> List[Dict[str, Any]]:\n    \"\"\"Opted-in web pages not checked for OF_KB_AUTO_REFRESH_HOURS, oldest\n    first, at most OF_KB_REFRESH_BATCH per run.\"\"\"\n    cur.execute(\n        \"SELECT \" + SOURCE_COLS + \" FROM \" + portal_db._q(SOURCES_TABLE) +\n        \" WHERE client_id = %s AND kind = 'url' AND auto_refresh AND \" + _DUE +\n        \" ORDER BY \" + _DUE_AT + \" ASC, id ASC LIMIT %s\",\n        (client_id, REFRESH_HOURS, int(limit or REFRESH_BATCH)),\n    )\n    return portal_db.rows(cur)\n\n\ndef _refresh_problem(cur, client_id: int, source_id: int, message: str) -> str:\n    cur.execute(\n        \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n        \" SET last_error = %s WHERE id = %s AND client_id = %s\",\n        ((\"Automatic refresh: \" + message)[:300], source_id, client_id),\n    )\n    return \"error\"\n\n\ndef refresh_source(client_id: int, source: Dict[str, Any]) -> str:\n    \"\"\"Re-fetch one opted-in page on its own connection. The row is claimed\n    atomically first (refresh_attempt_at), so two workers never fetch the\n    same page. Unchanged page -> only checked_at moves; changed page -> a\n    new version written by 'system' (publication state untouched).\n    Returns changed | unchanged | skipped | error; never raises.\"\"\"\n    source_id = int(source.get(\"id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n                \" SET refresh_attempt_at = NOW() WHERE id = %s AND client_id = %s\"\n                \" AND kind = 'url' AND auto_refresh AND \" + _DUE +\n                \" RETURNING id\",\n                (source_id, client_id, REFRESH_HOURS),\n            )\n            claimed = portal_db.rows(cur)\n            conn.commit()\n            if not claimed:\n                return \"skipped\"\n            try:\n                text, _title = fetch_url(str(source.get(\"origin\") or \"\"))\n            except ValueError as problem:\n                outcome = _refresh_problem(cur, client_id, source_id, str(problem))\n                conn.commit()\n                return outcome\n            except Exception as problem:\n                logger.info(\"kb refresh fetch crashed: %s\", problem)\n                outcome = _refresh_problem(cur, client_id, source_id,\n                                           \"the page could not be fetched.\")\n                conn.commit()\n                return outcome\n            content = stored_text(text)\n            if len(content) < MIN_CHUNK_CHARS:\n                outcome = _refresh_problem(cur, client_id, source_id,\n                                           \"the page returned no readable text.\")\n                conn.commit()\n                return outcome\n            latest = version_content(cur, client_id, source_id)\n            if latest is not None and str(latest.get(\"content\") or \"\") == content:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n                    \" SET checked_at = NOW(), last_error = ''\"\n                    \" WHERE id = %s AND client_id = %s\",\n                    (source_id, client_id),\n                )\n                conn.commit()\n                return \"unchanged\"\n            current = get_source(cur, client_id, source_id)\n            if current is None or str(current.get(\"kind\") or \"\") != \"url\" \\\n                    or not current.get(\"auto_refresh\"):\n                conn.commit()\n                return \"skipped\"\n            ingest(cur, client_id, current, content,\n                   \"automatic refresh: page changed\", None, None, \"system\")\n            conn.commit()\n            return \"changed\"\n    except Exception as problem:  # fail-soft: the next run retries\n        logger.info(\"kb refresh failed: %s\", problem)\n        try:\n            conn.rollback()\n        except Exception:\n            pass\n        return \"error\"\n    finally:\n        conn.close()\n\n\ndef run_refresh(client_id: int) -> Dict[str, int]:\n    \"\"\"One bounded refresh run for a tenant. Each page is isolated; a\n    changed page schedules a semantic-index sync.\"\"\"\n    counts = {\"changed\": 0, \"unchanged\": 0, \"error\": 0, \"skipped\": 0}\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            due = due_refresh(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    for source in due:\n        try:\n            outcome = refresh_source(client_id, source)\n        except Exception as problem:\n            logger.info(\"kb refresh crashed: %s\", problem)\n            outcome = \"error\"\n        counts[outcome if outcome in counts else \"error\"] += 1\n    if counts[\"changed\"]:\n        try:\n            import portal_kb_semantic\n\n            portal_kb_semantic.kick(client_id, \"edit\")\n        except Exception:\n            pass\n    return counts\n\n\ndef _refresh_job(client_id: int) -> None:\n    try:\n        run_refresh(client_id)\n    except Exception as problem:\n        logger.info(\"kb refresh job failed: %s\", problem)\n    finally:\n        with _REFRESH_LOCK:\n            _REFRESH_RUNNING.discard(client_id)\n\n\ndef kick_refresh(client_id: int) -> bool:\n    \"\"\"Connector-tick hook: start a background refresh run for the tenant,\n    at most once per OF_KB_REFRESH_TICK_SECONDS and one run at a time.\n    Returns True when a run was started.\"\"\"\n    try:\n        client_id = int(client_id or 0)\n    except Exception:\n        return False\n    if client_id <= 0:\n        return False\n    now = time.monotonic()\n    with _REFRESH_LOCK:\n        if client_id in _REFRESH_RUNNING:\n            return False\n        if now - _REFRESH_LAST.get(client_id, -1e18) < REFRESH_TICK_SECONDS:\n            return False\n        _REFRESH_RUNNING.add(client_id)\n        _REFRESH_LAST[client_id] = now\n    try:\n        threading.Thread(target=_refresh_job, args=(client_id,),\n                         name=\"kb-refresh-\" + str(client_id),\n                         daemon=True).start()\n    except Exception:\n        with _REFRESH_LOCK:\n            _REFRESH_RUNNING.discard(client_id)\n        return False\n    return True\n\n\n@bp.after_request\ndef _kb_semantic_after(response):\n    \"\"\"D1: a successful owner write schedules a semantic-index sync\n    (extract stores nothing, so it schedules nothing).\"\"\"\n    try:\n        if request.path.endswith(\"/kb/extract\"):\n            return response\n        import portal_kb_semantic\n\n        return portal_kb_semantic.kick_after_mutation(response)\n    except Exception:\n        return response\n\n");
writeNewRepair("OmniFlow-Control-Plane/portal_knowledge.py", "def kick_refresh(", true,
    "\"\"\"Knowledge engine (MASTER-UPGRADE engine 4): document / page ingestion,\ndeterministic chunking, versioning, health and keyword retrieval for the\nAI. D1 (delivered \u00a7211): ``portal_kb_semantic`` plugs meaning-based\nrecall into ``retrieve`` below (hybrid keyword + embeddings, reciprocal\nrank fusion) without changing the retrieval contract; keyword-only is\nthe automatic fallback.\n\nAudit-first (what already existed and stays):\n\n* ``portal_kb_entries`` (portal_kb) - owner-written Q&A answers with\n  trigger keywords. They still power the instant auto-reply on the\n  ingest path and the assist panel, untouched. Retrieval here searches\n  them TOGETHER with the new document chunks so the brain sees one\n  ranked knowledge list.\n* ``portal_kb_gaps`` (portal_growth) - unanswered questions; unchanged.\n* The KB auto-publish LOCK (owner law): nothing ingested here is ever\n  used by the AI until the owner publishes the source. New sources start\n  as ``draft``; ``published`` sources feed retrieval; ``paused`` sources\n  are kept but silent.\n\nSources (``portal_kb_sources``) are pasted text, uploaded text files\n(the browser reads .txt/.md/.csv/.json/.html and posts the text), PDF /\nWord files (\u00a7219: ``POST /kb/extract`` returns their text via\n``portal_kb_files`` for the owner to review - nothing is stored until\nthe owner adds it as a draft) or web pages (fetched server-side with an\nSSRF guard). Web pages can opt in to ``auto_refresh`` (\u00a7219): the\nconnector tick re-fetches them in the background every\nOF_KB_AUTO_REFRESH_HOURS; a changed page becomes a new version written\nby ``system`` and keeps its publication state (auto-publish lock). Every ingest writes a\nnew version snapshot (``portal_kb_source_versions``, raw text kept so a\nversion can be rolled back or re-chunked) and replaces the source's\nchunks (``portal_kb_chunks``). Retrieval is a single tenant-scoped SQL\ncandidate fetch (ILIKE on the query tokens) plus a deterministic\nBM25-style ranking in Python: term frequency, inverse candidate\nfrequency, heading/title boosts, phrase bonus and query coverage. Every\nhit carries a citation (source title + section) so the brain trace can\nshow where an answer came from. Fail-soft everywhere.\n\"\"\"\n\nimport html as html_lib\nimport ipaddress\nimport logging\nimport math\nimport os\nimport re\nimport socket\nimport threading\nimport time\nimport urllib.error\nimport urllib.parse\nimport urllib.request\nfrom datetime import datetime, timedelta, timezone\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nimport portal_kb_files\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-knowledge\")\n\nbp = Blueprint(\"portal_knowledge\", __name__, url_prefix=\"/api/v1/portal\")\n\nSOURCES_TABLE = \"portal_kb_sources\"\nVERSIONS_TABLE = \"portal_kb_source_versions\"\nCHUNKS_TABLE = \"portal_kb_chunks\"\nENTRIES_TABLE = \"portal_kb_entries\"\n\nKINDS: Tuple[str, ...] = (\"text\", \"file\", \"url\")\nSTATUSES: Tuple[str, ...] = (\"draft\", \"published\", \"paused\")\n\n\ndef _env_int(name: str, default: int, lo: int, hi: int) -> int:\n    try:\n        value = int(os.environ.get(name, \"\") or default)\n    except Exception:\n        value = default\n    return max(lo, min(hi, value))\n\n\nMAX_SOURCES = _env_int(\"OF_KB_SOURCES_MAX\", 50, 1, 1000)\nMAX_SOURCE_CHARS = _env_int(\"OF_KB_SOURCE_CHARS_MAX\", 200000, 1000, 2000000)\nCHUNK_CHARS = _env_int(\"OF_KB_CHUNK_CHARS\", 700, 200, 4000)\nCHUNK_OVERLAP = _env_int(\"OF_KB_CHUNK_OVERLAP\", 80, 0, 400)\nMAX_VERSIONS = _env_int(\"OF_KB_VERSIONS_MAX\", 10, 1, 100)\nURL_TIMEOUT = _env_int(\"OF_KB_URL_TIMEOUT\", 8, 2, 60)\nURL_BYTES_MAX = _env_int(\"OF_KB_URL_BYTES_MAX\", 1500000, 10000, 20000000)\nURL_STALE_DAYS = _env_int(\"OF_KB_URL_STALE_DAYS\", 30, 1, 365)\nRETRIEVE_CANDIDATES = _env_int(\"OF_KB_RETRIEVE_CANDIDATES\", 200, 10, 2000)\nQUERY_TOKENS_MAX = _env_int(\"OF_KB_QUERY_TOKENS_MAX\", 12, 3, 32)\nREFRESH_HOURS = _env_int(\"OF_KB_AUTO_REFRESH_HOURS\", 168, 1, 8760)\nREFRESH_BATCH = _env_int(\"OF_KB_REFRESH_BATCH\", 3, 1, 50)\nREFRESH_TICK_SECONDS = _env_int(\"OF_KB_REFRESH_TICK_SECONDS\", 900, 30, 86400)\nMAX_TITLE_CHARS = 120\nMAX_HEADING_CHARS = 160\nSNIPPET_CHARS = 400\nMIN_CHUNK_CHARS = 20\nINSERT_BATCH = 200\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_kb_sources (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  title TEXT NOT NULL DEFAULT '',\n  kind TEXT NOT NULL DEFAULT 'text',\n  origin TEXT NOT NULL DEFAULT '',\n  status TEXT NOT NULL DEFAULT 'draft',\n  version INT NOT NULL DEFAULT 0,\n  chunk_count INT NOT NULL DEFAULT 0,\n  char_count INT NOT NULL DEFAULT 0,\n  last_error TEXT NOT NULL DEFAULT '',\n  ingested_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_sources_client\n  ON portal_kb_sources (client_id, status);\nCREATE TABLE IF NOT EXISTS portal_kb_source_versions (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  source_id BIGINT NOT NULL,\n  version INT NOT NULL,\n  content TEXT NOT NULL DEFAULT '',\n  chunk_count INT NOT NULL DEFAULT 0,\n  char_count INT NOT NULL DEFAULT 0,\n  note TEXT NOT NULL DEFAULT '',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_source_versions_source\n  ON portal_kb_source_versions (client_id, source_id, version DESC);\nCREATE TABLE IF NOT EXISTS portal_kb_chunks (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  source_id BIGINT NOT NULL,\n  version INT NOT NULL DEFAULT 1,\n  position INT NOT NULL DEFAULT 0,\n  heading TEXT NOT NULL DEFAULT '',\n  content TEXT NOT NULL DEFAULT '',\n  char_count INT NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_kb_chunks_source\n  ON portal_kb_chunks (client_id, source_id, position);\nALTER TABLE portal_kb_sources\n  ADD COLUMN IF NOT EXISTS auto_refresh BOOLEAN NOT NULL DEFAULT FALSE;\nALTER TABLE portal_kb_sources\n  ADD COLUMN IF NOT EXISTS checked_at TIMESTAMPTZ;\nALTER TABLE portal_kb_sources\n  ADD COLUMN IF NOT EXISTS refresh_attempt_at TIMESTAMPTZ;\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\n# ---------------------------------------------------------------------------\n# Pure text helpers: normalisation, tokens, HTML, chunking, ranking\n# ---------------------------------------------------------------------------\n\n#: Function words that carry no retrieval signal (English + Roman Urdu).\nSTOPWORDS = frozenset(\"\"\"\na an the is are am was were be been being of to in on at for and or but if\nthen than so as by with from into onto about over under up down out off this\nthat these those it its i me my we our you your he she they them their his\nher what which who whom whose when where why how do does did done have has\nhad having can could will would shall should may might must not no yes ok\nokay please plz pls hi hello hey thanks thank\nka ki ke ko ki se me mein main hai hain he hen ho hoon hun hu tha thi the\nthay thi ye yeh wo woh is us un in ab aur or ya bhi to per par pe ap aap tum\nmera meri mere hamara hamari apna apni apne kya kia kyun kyu kaise kaisa\nkaisi kab kahan kon konsa kar karo karen karein kro krna karna kiya raha\nrahi rahe hoga hogi honge chahiye chaiye bhai ji han haan nahi nhi na\n\"\"\".split())\n\n_WORD_RE = re.compile(r\"\\w+\", re.UNICODE)\n_BLANK_RE = re.compile(r\"\\n\\s*\\n\")\n_SENTENCE_RE = re.compile(r\"(?<=[.!?\\u06d4])\\s+\")\n_HEADING_RE = re.compile(r\"^(#{1,6}\\s+|\\d+(\\.\\d+)*[.)]\\s+)\")\n_LIST_OR_ROW_RE = re.compile(r\"^[-*\\u2022]\\s\")\n\n\ndef normalize(text: Any) -> str:\n    return re.sub(r\"\\s+\", \" \", str(text or \"\").lower()).strip()\n\n\ndef _collapse(text: Any) -> str:\n    \"\"\"Whitespace-collapsed but case-preserving (titles and headings are\n    shown to the owner; matching lower-cases separately).\"\"\"\n    return re.sub(r\"\\s+\", \" \", str(text or \"\")).strip()\n\n\ndef words(text: Any) -> List[str]:\n    return [w for w in _WORD_RE.findall(str(text or \"\").lower())]\n\n\ndef tokenize(text: Any, limit: int = 0, keep_stopwords: bool = False) -> List[str]:\n    \"\"\"Unique retrieval tokens in order of appearance (stop words and\n    one-character fragments dropped). ``limit`` keeps the longest tokens\n    first so the SQL candidate fetch uses the most selective ones.\"\"\"\n    seen: List[str] = []\n    for word in words(text):\n        if len(word) < 2:\n            continue\n        if not keep_stopwords and word in STOPWORDS:\n            continue\n        if word not in seen:\n            seen.append(word)\n    if limit and len(seen) > limit:\n        seen = sorted(seen, key=lambda w: (-len(w), seen.index(w)))[:limit]\n    return seen\n\n\ndef query_tokens(text: Any) -> List[str]:\n    \"\"\"Tokens for a customer question; falls back to stop words when the\n    question is made of them only (\\\"kya hai\\\") so short questions still\n    get a candidate fetch.\"\"\"\n    tokens = tokenize(text, QUERY_TOKENS_MAX)\n    if not tokens:\n        tokens = tokenize(text, QUERY_TOKENS_MAX, keep_stopwords=True)\n    return tokens\n\n\n_TAG_RE = re.compile(r\"<[^>]+>\")\n_DROP_RE = re.compile(\n    r\"<(script|style|noscript|svg|head|template|iframe)[^>]*>.*?</\\1\\s*>\",\n    re.IGNORECASE | re.DOTALL)\n_COMMENT_RE = re.compile(r\"<!--.*?-->\", re.DOTALL)\n_BLOCK_RE = re.compile(\n    r\"</?(p|div|br|li|ul|ol|tr|td|th|table|section|article|header|footer|\"\n    r\"h[1-6]|blockquote|pre|hr|dd|dt|dl|nav|main|aside|figure|figcaption)\"\n    r\"[^>]*>\", re.IGNORECASE)\n_HEAD_TAG_RE = re.compile(r\"<h([1-6])[^>]*>(.*?)</h\\1\\s*>\",\n                          re.IGNORECASE | re.DOTALL)\n_TITLE_RE = re.compile(r\"<title[^>]*>(.*?)</title>\", re.IGNORECASE | re.DOTALL)\n\n\ndef html_title(markup: str) -> str:\n    match = _TITLE_RE.search(str(markup or \"\"))\n    if not match:\n        return \"\"\n    return _collapse(html_lib.unescape(_TAG_RE.sub(\" \", match.group(1))))[\n        :MAX_TITLE_CHARS]\n\n\ndef html_to_text(markup: str) -> str:\n    \"\"\"Readable text from HTML: scripts/styles/head dropped, headings kept\n    as markdown-style lines (so chunking can carry them), block tags become\n    paragraph breaks, entities unescaped, whitespace collapsed.\"\"\"\n    text = str(markup or \"\")\n    text = _COMMENT_RE.sub(\" \", text)\n    text = _DROP_RE.sub(\" \", text)\n    text = _HEAD_TAG_RE.sub(\n        lambda m: \"\\n\\n\" + \"#\" * int(m.group(1)) + \" \"\n        + _TAG_RE.sub(\" \", m.group(2)).strip() + \"\\n\\n\", text)\n    text = _BLOCK_RE.sub(\"\\n\\n\", text)\n    text = _TAG_RE.sub(\" \", text)\n    text = html_lib.unescape(text)\n    text = text.replace(\"\\xa0\", \" \")\n    lines = [re.sub(r\"[ \\t]+\", \" \", line).strip() for line in text.split(\"\\n\")]\n    out: List[str] = []\n    blank = False\n    for line in lines:\n        if line:\n            out.append(line)\n            blank = False\n        elif not blank and out:\n            out.append(\"\")\n            blank = True\n    return \"\\n\".join(out).strip()\n\n\ndef clean_text(text: Any) -> str:\n    \"\"\"Normalise pasted / uploaded text: CRLF, tabs, trailing spaces, at\n    most one blank line in a row.\"\"\"\n    value = str(text or \"\").replace(\"\\r\\n\", \"\\n\").replace(\"\\r\", \"\\n\")\n    value = value.replace(\"\\t\", \" \").replace(\"\\x00\", \"\")\n    lines = [re.sub(r\"[ ]+\", \" \", line).rstrip() for line in value.split(\"\\n\")]\n    out: List[str] = []\n    blank = False\n    for line in lines:\n        if line.strip():\n            out.append(line)\n            blank = False\n        elif not blank and out:\n            out.append(\"\")\n            blank = True\n    return \"\\n\".join(out).strip()\n\n\ndef _is_heading(block: str) -> bool:\n    if \"\\n\" in block or len(block) > 80:\n        return False\n    if _HEADING_RE.match(block):\n        return True\n    stripped = block.rstrip(\":\").strip()\n    if block.endswith(\":\") and len(stripped.split()) <= 8:\n        return True\n    letters = [c for c in stripped if c.isalpha()]\n    return bool(letters) and len(stripped.split()) <= 6 and all(\n        c.isupper() for c in letters)\n\n\ndef _heading_text(block: str) -> str:\n    return _collapse(_HEADING_RE.sub(\"\", block).rstrip(\":\"))[:MAX_HEADING_CHARS]\n\n\ndef _split_heading(block: str) -> Tuple[str, str]:\n    \"\"\"(heading, body) for a block whose first line is a heading and the\n    rest a paragraph (\"Returns\\nItems can be returned...\"); (\"\", block)\n    otherwise. A first line counts as a heading when it is short, has no\n    sentence punctuation and the line after it is longer.\"\"\"\n    if \"\\n\" not in block:\n        return \"\", block\n    first, rest = block.split(\"\\n\", 1)\n    first, rest = first.strip(), rest.strip()\n    if not first or not rest:\n        return \"\", block\n    if _LIST_OR_ROW_RE.match(first) or \" | \" in first:\n        return \"\", block  # a list item or table row (PDF/Word import)\n    if _is_heading(first):\n        return _heading_text(first), rest\n    if (len(first) <= 60 and len(first.split()) <= 8\n            and not first.endswith((\".\", \"!\", \"?\", \",\", \";\"))\n            and len(rest.split(\"\\n\", 1)[0]) > len(first)):\n        return _heading_text(first), rest\n    return \"\", block\n\n\ndef _split_long(block: str, size: int) -> List[str]:\n    \"\"\"A block bigger than one chunk: pack sentences up to ``size``; a\n    single sentence longer than that is cut at its last space.\"\"\"\n    pieces: List[str] = []\n    current = \"\"\n    for sentence in _SENTENCE_RE.split(block):\n        sentence = sentence.strip()\n        if not sentence:\n            continue\n        parts: List[str] = []\n        while len(sentence) > size:\n            cut = sentence.rfind(\" \", 0, size)\n            if cut < size // 2:\n                cut = size\n            parts.append(sentence[:cut].strip())\n            sentence = sentence[cut:].strip()\n        if sentence:\n            parts.append(sentence)\n        for part in parts:\n            if current and len(current) + len(part) + 1 > size:\n                pieces.append(current)\n                current = part\n            else:\n                current = (current + \" \" + part).strip()\n    if current:\n        pieces.append(current)\n    return pieces\n\n\ndef _overlap_tail(text: str, overlap: int) -> str:\n    if overlap <= 0 or len(text) <= overlap:\n        return \"\"\n    tail = text[-overlap:]\n    cut = tail.find(\" \")\n    return tail[cut + 1:].strip() if cut >= 0 else tail.strip()\n\n\ndef chunk_text(text: str, size: int = 0,\n               overlap: Optional[int] = None) -> List[Dict[str, Any]]:\n    \"\"\"Deterministic, heading-aware chunks: paragraphs are packed up to\n    ``size`` characters, headings label the chunks that follow them, over-\n    long paragraphs split at sentence boundaries, and each chunk starts\n    with a short overlap from the previous one so context is not cut.\"\"\"\n    size = size or CHUNK_CHARS\n    overlap = CHUNK_OVERLAP if overlap is None else max(0, overlap)\n    overlap = min(overlap, size // 3)\n    blocks = [b.strip() for b in _BLANK_RE.split(clean_text(text)) if b.strip()]\n    chunks: List[Dict[str, Any]] = []\n    heading = \"\"\n    current = \"\"\n    current_heading = \"\"\n    previous_text = \"\"\n\n    def flush() -> None:\n        nonlocal current, previous_text\n        body = current.strip()\n        if body:\n            chunks.append({\"position\": len(chunks),\n                           \"heading\": current_heading, \"content\": body})\n            previous_text = body\n        current = \"\"\n\n    for block in blocks:\n        if _is_heading(block):\n            flush()\n            previous_text = \"\"  # no overlap across sections\n            heading = _heading_text(block)\n            continue\n        inline_heading, block = _split_heading(block)\n        if inline_heading:\n            flush()\n            previous_text = \"\"\n            heading = inline_heading\n        # long paragraphs are packed a little below ``size`` so the overlap\n        # carried in from the previous chunk still fits\n        pieces = [block] if len(block) <= size else _split_long(\n            block, max(size // 2, size - overlap))\n        for piece in pieces:\n            if current and len(current) + len(piece) + 2 > size:\n                flush()\n            if not current:\n                current_heading = heading\n                tail = _overlap_tail(previous_text, overlap)\n                current = (tail + \" \" + piece).strip() if tail and len(\n                    tail) + len(piece) + 1 <= size else piece\n            else:\n                current = current + \"\\n\\n\" + piece\n    flush()\n    if len(chunks) > 1:\n        # a tiny chunk is noise unless its heading makes it meaningful\n        # (\"Charges\" + \"Call 0300-1234567\" stays; \"B\" + \"ok\" goes)\n        chunks = [c for c in chunks if len(c[\"content\"]) >= MIN_CHUNK_CHARS\n                  or (c[\"heading\"] and len(c[\"heading\"]) + 1\n                      + len(c[\"content\"]) >= MIN_CHUNK_CHARS)]\n        for index, chunk in enumerate(chunks):\n            chunk[\"position\"] = index\n    return chunks\n\n\ndef _matches(word: str, token: str) -> bool:\n    \"\"\"Exact match, or a prefix match once the token is long enough to be\n    a stem (return -> returned/returns, deliver -> delivery). Short Roman\n    Urdu words (din, kab) stay exact.\"\"\"\n    if word == token:\n        return True\n    if len(token) >= 4 and word.startswith(token):\n        return True\n    return len(word) >= 4 and token.startswith(word) and len(token) - len(word) <= 3\n\n\ndef _count(token: str, word_list: List[str]) -> int:\n    return sum(1 for w in word_list if _matches(w, token))\n\n\ndef score_candidates(tokens: List[str], candidates: List[Dict[str, Any]],\n                     n: int) -> List[Dict[str, Any]]:\n    \"\"\"BM25-style ranking without an index: per-token tf saturation,\n    inverse candidate frequency, title/heading boost, adjacent-token phrase\n    bonus and query coverage. Deterministic; ties break on shorter text\n    then id.\"\"\"\n    if not tokens or not candidates:\n        return []\n    prepared = []\n    for row in candidates:\n        title_words = words(row.get(\"title\"))\n        body_words = words(row.get(\"content\")) + words(row.get(\"extra\"))\n        title_hits = {t: _count(t, title_words) for t in tokens}\n        body_hits = {t: _count(t, body_words) for t in tokens}\n        prepared.append((row, title_words, body_words, title_hits, body_hits))\n    total = len(prepared)\n    df = {t: sum(1 for p in prepared if p[3][t] or p[4][t]) for t in tokens}\n    idf = {t: math.log(1.0 + total / (1.0 + df[t])) + 0.1 for t in tokens}\n    ranked = []\n    for row, title_words, body_words, title_hits, body_hits in prepared:\n        matched: List[str] = []\n        score = 0.0\n        for token in tokens:\n            tf = body_hits[token]\n            in_title = title_hits[token] > 0\n            if not tf and not in_title:\n                continue\n            matched.append(token)\n            weight = (1.0 + math.log(1.0 + tf)) if tf else 0.6\n            if in_title:\n                weight += 1.5\n            score += weight * idf[token]\n        if not matched:\n            continue\n        if len(tokens) > 1:\n            text_words = title_words + body_words\n            for a, b in zip(tokens, tokens[1:]):\n                for i in range(len(text_words) - 1):\n                    if _matches(text_words[i], a) and _matches(text_words[i + 1], b):\n                        score += 1.0\n                        break\n        coverage = len(matched) / float(len(tokens))\n        score *= 0.5 + 0.5 * coverage\n        ranked.append((round(score, 4), matched, row))\n    ranked.sort(key=lambda item: (-item[0], len(str(item[2].get(\"content\") or \"\")),\n                                  int(item[2].get(\"id\") or 0)))\n    hits = []\n    for score, matched, row in ranked[:max(1, n)]:\n        content = str(row.get(\"content\") or \"\")\n        hits.append({\n            \"kind\": str(row.get(\"kind\") or \"entry\"),\n            \"id\": int(row.get(\"id\") or 0),\n            \"title\": str(row.get(\"title\") or \"\"),\n            \"content\": content[:SNIPPET_CHARS],\n            \"source_id\": int(row.get(\"source_id\") or 0),\n            \"source\": str(row.get(\"source_title\") or \"\"),\n            \"position\": int(row.get(\"position\") or 0),\n            \"score\": score,\n            \"matched\": matched,\n        })\n    return hits\n\n\n# ---------------------------------------------------------------------------\n# URL fetch with SSRF guard\n# ---------------------------------------------------------------------------\n\ndef assert_public_url(url: str, resolver=None) -> Tuple[str, str]:\n    \"\"\"Validate an owner-supplied URL: http(s) only, a real host name, no\n    credentials, and every resolved address public (no loopback, private,\n    link-local, multicast or reserved ranges). Returns (scheme, host).\n    Raises ValueError with an owner-readable message.\"\"\"\n    parsed = urllib.parse.urlsplit(str(url or \"\").strip())\n    if parsed.scheme not in (\"http\", \"https\"):\n        raise ValueError(\"Only http and https links are supported.\")\n    host = (parsed.hostname or \"\").strip().lower().rstrip(\".\")\n    if not host or parsed.username or parsed.password:\n        raise ValueError(\"That link is not a valid web address.\")\n    if host == \"localhost\" or host.endswith(\".localhost\") or host.endswith(\n            \".local\") or host.endswith(\".internal\"):\n        raise ValueError(\"Internal addresses cannot be fetched.\")\n    resolve = resolver or socket.getaddrinfo\n    try:\n        infos = resolve(host, parsed.port or (443 if parsed.scheme == \"https\"\n                                                else 80))\n    except Exception:\n        raise ValueError(\"That web address could not be resolved.\")\n    addresses = []\n    for info in infos or []:\n        try:\n            addresses.append(ipaddress.ip_address(info[4][0]))\n        except Exception:\n            continue\n    if not addresses:\n        raise ValueError(\"That web address could not be resolved.\")\n    for address in addresses:\n        if (address.is_private or address.is_loopback or address.is_link_local\n                or address.is_multicast or address.is_reserved\n                or address.is_unspecified):\n            raise ValueError(\"Internal addresses cannot be fetched.\")\n    return parsed.scheme, host\n\n\nclass _SafeRedirectHandler(urllib.request.HTTPRedirectHandler):\n    \"\"\"Re-validates every redirect target (a public page may not bounce\n    the fetch onto an internal address).\"\"\"\n\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\n        assert_public_url(newurl)\n        return super().redirect_request(req, fp, code, msg, headers, newurl)\n\n\ndef fetch_url(url: str) -> Tuple[str, str]:\n    \"\"\"Download a public page and return (text, title). Raises ValueError\n    with an owner-readable message on any problem.\"\"\"\n    assert_public_url(url)\n    req = urllib.request.Request(str(url).strip(), method=\"GET\")\n    req.add_header(\"Accept\", \"text/html, text/plain;q=0.9, */*;q=0.5\")\n    req.add_header(\"User-Agent\", \"OmniFlow-Knowledge/1.0 (+knowledge sources)\")\n    opener = urllib.request.build_opener(_SafeRedirectHandler())\n    try:\n        with opener.open(req, timeout=URL_TIMEOUT) as resp:\n            content_type = str(resp.headers.get(\"Content-Type\") or \"\").lower()\n            raw = resp.read(URL_BYTES_MAX + 1)\n    except urllib.error.HTTPError as error:\n        raise ValueError(\"The page answered with HTTP \" + str(error.code) + \".\")\n    except ValueError:\n        raise\n    except Exception:\n        raise ValueError(\"The page could not be fetched (timeout or \"\n                         \"connection error).\")\n    if len(raw) > URL_BYTES_MAX:\n        raise ValueError(\"The page is too large to import (limit \"\n                         + str(URL_BYTES_MAX // 1000) + \" KB).\")\n    kind = content_type.split(\";\")[0].strip()\n    if kind and not (kind.startswith(\"text/\") or kind in (\n            \"application/json\", \"application/xhtml+xml\", \"application/xml\")):\n        raise ValueError(\"Only web pages and text files can be imported \"\n                         \"from a link (got \" + kind + \").\")\n    charset = \"utf-8\"\n    match = re.search(r\"charset=([\\w-]+)\", content_type)\n    if match:\n        charset = match.group(1)\n    try:\n        body = raw.decode(charset, \"replace\")\n    except Exception:\n        body = raw.decode(\"utf-8\", \"replace\")\n    if kind in (\"text/html\", \"application/xhtml+xml\") or \"<html\" in body[:2000].lower():\n        return html_to_text(body), html_title(body)\n    return clean_text(body), \"\"\n\n\n# ---------------------------------------------------------------------------\n# DB helpers\n# ---------------------------------------------------------------------------\n\nSOURCE_COLS = (\"id, client_id, title, kind, origin, status, version, chunk_count,\"\n               \" char_count, last_error, ingested_at, created_at, updated_at,\"\n               \" auto_refresh, checked_at\")\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None or value == \"\":\n        return None\n    if hasattr(value, \"isoformat\"):\n        return value.isoformat()\n    return str(value)\n\n\ndef _is_stale(row: Dict[str, Any]) -> bool:\n    \"\"\"A web page neither indexed nor confirmed unchanged (automatic\n    refresh) within OF_KB_URL_STALE_DAYS.\"\"\"\n    if str(row.get(\"kind\") or \"\") != \"url\":\n        return False\n    stamps = []\n    for key in (\"ingested_at\", \"checked_at\"):\n        stamp = row.get(key)\n        if isinstance(stamp, datetime):\n            stamps.append(stamp if stamp.tzinfo else stamp.replace(\n                tzinfo=timezone.utc))\n    if not stamps:\n        return False\n    return max(stamps) < datetime.now(timezone.utc) - timedelta(days=URL_STALE_DAYS)\n\n\ndef source_public(row: Dict[str, Any]) -> Dict[str, Any]:\n    return {\n        \"id\": int(row.get(\"id\") or 0),\n        \"title\": str(row.get(\"title\") or \"\"),\n        \"kind\": str(row.get(\"kind\") or \"text\"),\n        \"origin\": str(row.get(\"origin\") or \"\"),\n        \"status\": str(row.get(\"status\") or \"draft\"),\n        \"version\": int(row.get(\"version\") or 0),\n        \"chunk_count\": int(row.get(\"chunk_count\") or 0),\n        \"char_count\": int(row.get(\"char_count\") or 0),\n        \"last_error\": str(row.get(\"last_error\") or \"\"),\n        \"stale\": _is_stale(row),\n        \"auto_refresh\": bool(row.get(\"auto_refresh\"))\n        and str(row.get(\"kind\") or \"\") == \"url\",\n        \"checked_at\": _iso(row.get(\"checked_at\")),\n        \"ingested_at\": _iso(row.get(\"ingested_at\")),\n        \"created_at\": _iso(row.get(\"created_at\")),\n        \"updated_at\": _iso(row.get(\"updated_at\")),\n    }\n\n\ndef get_source(cur, client_id: int, source_id: int) -> Optional[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT \" + SOURCE_COLS + \" FROM \" + portal_db._q(SOURCES_TABLE) +\n        \" WHERE id = %s AND client_id = %s\",\n        (int(source_id), client_id),\n    )\n    rows = portal_db.rows(cur)\n    return rows[0] if rows else None\n\n\ndef list_sources(cur, client_id: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT \" + SOURCE_COLS + \" FROM \" + portal_db._q(SOURCES_TABLE) +\n        \" WHERE client_id = %s ORDER BY updated_at DESC, id DESC LIMIT %s\",\n        (client_id, MAX_SOURCES + 50),\n    )\n    return portal_db.rows(cur)\n\n\ndef health(sources: List[Dict[str, Any]]) -> Dict[str, Any]:\n    out = {\"sources\": len(sources), \"published\": 0, \"drafts\": 0, \"paused\": 0,\n           \"chunks\": 0, \"errors\": 0, \"stale\": 0}\n    for row in sources:\n        status = str(row.get(\"status\") or \"draft\")\n        if status == \"published\":\n            out[\"published\"] += 1\n            out[\"chunks\"] += int(row.get(\"chunk_count\") or 0)\n        elif status == \"paused\":\n            out[\"paused\"] += 1\n        else:\n            out[\"drafts\"] += 1\n        if str(row.get(\"last_error\") or \"\"):\n            out[\"errors\"] += 1\n        if _is_stale(row):\n            out[\"stale\"] += 1\n    return out\n\n\ndef stored_text(text: Any) -> str:\n    \"\"\"Exactly what ingest stores as a version (the refresh job compares\n    a fresh fetch against it).\"\"\"\n    return clean_text(text)[:MAX_SOURCE_CHARS]\n\n\ndef ingest(cur, client_id: int, source: Dict[str, Any], text: str,\n           note: str = \"\", actor_user_id: Optional[int] = None,\n           origin: Optional[str] = None,\n           actor_kind: str = \"customer_user\") -> Dict[str, Any]:\n    \"\"\"Chunk ``text`` for ``source``: replace its chunks, snapshot the raw\n    text as the next version, prune old versions, refresh the counters and\n    audit. ``origin`` replaces the stored file name (new upload of a file\n    source). Returns the updated source row. Never publishes.\"\"\"\n    source_id = int(source.get(\"id\") or 0)\n    content = stored_text(text)\n    chunks = chunk_text(content)\n    version = int(source.get(\"version\") or 0) + 1\n    cur.execute(\n        \"DELETE FROM \" + portal_db._q(CHUNKS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s\",\n        (client_id, source_id),\n    )\n    for start in range(0, len(chunks), INSERT_BATCH):\n        batch = chunks[start:start + INSERT_BATCH]\n        values = \", \".join([\"(%s, %s, %s, %s, %s, %s, %s)\"] * len(batch))\n        params: List[Any] = []\n        for chunk in batch:\n            params.extend([client_id, source_id, version, chunk[\"position\"],\n                           chunk[\"heading\"], chunk[\"content\"],\n                           len(chunk[\"content\"])])\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(CHUNKS_TABLE) +\n            \" (client_id, source_id, version, position, heading, content,\"\n            \" char_count) VALUES \" + values,\n            tuple(params),\n        )\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(VERSIONS_TABLE) +\n        \" (client_id, source_id, version, content, chunk_count, char_count,\"\n        \" note) VALUES (%s, %s, %s, %s, %s, %s, %s)\",\n        (client_id, source_id, version, content, len(chunks), len(content),\n         str(note or \"\")[:200]),\n    )\n    cur.execute(\n        \"DELETE FROM \" + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s AND version <= %s\",\n        (client_id, source_id, version - MAX_VERSIONS),\n    )\n    params: List[Any] = [version, len(chunks), len(content)]\n    if origin:\n        params.append(str(origin)[:200])\n    cur.execute(\n        \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n        \" SET version = %s, chunk_count = %s, char_count = %s, last_error = '',\"\n        + (\" origin = %s,\" if origin else \"\") +\n        \" ingested_at = NOW(), checked_at = NOW(), updated_at = NOW()\"\n        \" WHERE id = %s AND client_id = %s RETURNING \" + SOURCE_COLS,\n        tuple(params + [source_id, client_id]),\n    )\n    rows = portal_db.rows(cur)\n    updated = rows[0] if rows else dict(source, version=version,\n                                        chunk_count=len(chunks),\n                                        char_count=len(content), last_error=\"\")\n    portal_db.log_action(\n        cur, client_id, \"kb.source_ingested\", actor_kind, actor_user_id,\n        None, \"Indexed '\" + str(updated.get(\"title\") or \"\")[:60] + \"' v\"\n        + str(version) + \" (\" + str(len(chunks)) + \" sections, \"\n        + str(len(content)) + \" chars)\" + (\" - \" + note if note else \"\"),\n    )\n    return updated\n\n\ndef record_error(cur, client_id: int, source_id: int, message: str) -> None:\n    cur.execute(\n        \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n        \" SET last_error = %s, updated_at = NOW()\"\n        \" WHERE id = %s AND client_id = %s\",\n        (str(message or \"\")[:300], int(source_id), client_id),\n    )\n\n\ndef version_content(cur, client_id: int, source_id: int,\n                    version: Optional[int] = None) -> Optional[Dict[str, Any]]:\n    where = \" AND version = %s\" if version else \"\"\n    params: Tuple[Any, ...] = (client_id, int(source_id)) + (\n        (int(version),) if version else ())\n    cur.execute(\n        \"SELECT version, content, chunk_count, char_count, note, created_at FROM \"\n        + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s\" + where +\n        \" ORDER BY version DESC LIMIT 1\",\n        params,\n    )\n    rows = portal_db.rows(cur)\n    return rows[0] if rows else None\n\n\ndef list_versions(cur, client_id: int, source_id: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT version, chunk_count, char_count, note, created_at FROM \"\n        + portal_db._q(VERSIONS_TABLE) +\n        \" WHERE client_id = %s AND source_id = %s ORDER BY version DESC LIMIT %s\",\n        (client_id, int(source_id), MAX_VERSIONS),\n    )\n    return [{\"version\": int(r.get(\"version\") or 0),\n             \"chunk_count\": int(r.get(\"chunk_count\") or 0),\n             \"char_count\": int(r.get(\"char_count\") or 0),\n             \"note\": str(r.get(\"note\") or \"\"),\n             \"created_at\": _iso(r.get(\"created_at\"))}\n            for r in portal_db.rows(cur)]\n\n\ndef retrieve(cur, client_id: int, query: str, n: int = 5,\n             include_entries: bool = True) -> List[Dict[str, Any]]:\n    \"\"\"The one knowledge read for the brain and the owner's tester: active\n    Q&A entries + chunks of PUBLISHED sources, ranked deterministically.\n\n    Keyword ranking first (BM25-style over the query tokens); when the\n    semantic index is active and populated, meaning-based hits are fused\n    in (portal_kb_semantic.hybrid). Every hit carries ``via``\n    (keyword|semantic|both) and ``semantic`` (similarity or None).\n    Blank query -> [] without touching the DB.\"\"\"\n    if not str(query or \"\").strip():\n        return []\n    tokens = query_tokens(query)\n    keyword = _keyword_hits(cur, client_id, tokens,\n                            max(n, SEMANTIC_KEYWORD_POOL), include_entries)\n    try:\n        import portal_kb_semantic\n\n        fused = portal_kb_semantic.hybrid(cur, client_id, query, keyword, n,\n                                          include_entries, SNIPPET_CHARS)\n    except Exception as error:  # fail-soft: keyword ranking stands\n        logger.info(\"semantic retrieval skipped: %s\", error)\n        fused = None\n    if fused is not None:\n        return fused\n    out = []\n    for hit in keyword[:max(1, n)]:\n        hit[\"via\"] = \"keyword\"\n        hit[\"semantic\"] = None\n        out.append(hit)\n    return out\n\n\nSEMANTIC_KEYWORD_POOL = _env_int(\"OF_KB_HYBRID_KEYWORD_POOL\", 12, 1, 100)\n\n\ndef _keyword_hits(cur, client_id: int, tokens: List[str], n: int,\n                  include_entries: bool) -> List[Dict[str, Any]]:\n    \"\"\"Keyword candidates (ILIKE on the tokens) ranked by score_candidates.\n    No tokens -> [] without touching the DB.\"\"\"\n    if not tokens:\n        return []\n    patterns = [\"%\" + t + \"%\" for t in tokens]\n    limit = RETRIEVE_CANDIDATES\n    parts: List[str] = []\n    params: List[Any] = []\n    if include_entries:\n        parts.append(\n            \"SELECT 'entry' AS kind, e.id AS id, e.title AS title,\"\n            \" e.content AS content, e.keywords AS extra, 0 AS source_id,\"\n            \" '' AS source_title, 0 AS position FROM \"\n            + portal_db._q(ENTRIES_TABLE) + \" e\"\n            \" WHERE e.client_id = %s AND e.is_active IS TRUE\"\n            \" AND (e.title ILIKE ANY(%s) OR e.keywords ILIKE ANY(%s)\"\n            \" OR e.content ILIKE ANY(%s))\")\n        params.extend([client_id, patterns, patterns, patterns])\n    parts.append(\n        \"SELECT 'chunk' AS kind, c.id AS id, c.heading AS title,\"\n        \" c.content AS content, '' AS extra, c.source_id AS source_id,\"\n        \" s.title AS source_title, c.position AS position FROM \"\n        + portal_db._q(CHUNKS_TABLE) + \" c JOIN \" + portal_db._q(SOURCES_TABLE) +\n        \" s ON s.id = c.source_id AND s.client_id = c.client_id\"\n        \" WHERE c.client_id = %s AND s.status = 'published'\"\n        \" AND (c.heading ILIKE ANY(%s) OR c.content ILIKE ANY(%s))\")\n    params.extend([client_id, patterns, patterns])\n    params.append(limit)\n    cur.execute(\" UNION ALL \".join(parts) + \" LIMIT %s\", tuple(params))\n    return score_candidates(tokens, portal_db.rows(cur), n)\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\ndef _human_or_error():\n    principal, error = _principal_or_error()\n    if error:\n        return None, error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return None, forbidden\n    return principal, None\n\n\ndef _bad(message: str, code: str = \"bad_request\", status: int = 400):\n    return jsonify({\"error\": {\"code\": code, \"message\": message}}), status\n\n\ndef _limits() -> Dict[str, Any]:\n    out = {\"max_sources\": MAX_SOURCES, \"max_chars\": MAX_SOURCE_CHARS,\n           \"chunk_chars\": CHUNK_CHARS, \"max_versions\": MAX_VERSIONS,\n           \"kinds\": list(KINDS), \"refresh_hours\": REFRESH_HOURS}\n    out.update(portal_kb_files.limits())\n    return out\n\n\ndef _title_from(text: str, fallback: str) -> str:\n    for line in str(text or \"\").split(\"\\n\"):\n        line = _HEADING_RE.sub(\"\", line).strip().strip(\"#\").strip()\n        if line:\n            return line[:MAX_TITLE_CHARS]\n    return fallback[:MAX_TITLE_CHARS]\n\n\n@bp.get(\"/kb/sources\")\ndef get_sources():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            rows = list_sources(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"sources\": [source_public(r) for r in rows],\n                    \"health\": health(rows), \"limits\": _limits()}), 200\n\n\n@bp.post(\"/kb/sources\")\ndef post_source():\n    \"\"\"Create a source and index it right away. It stays a DRAFT until the\n    owner publishes it (KB auto-publish lock).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    kind = str(payload.get(\"kind\") or \"text\").strip().lower()\n    if kind not in KINDS:\n        return _bad(\"kind must be one of text, file, url.\")\n    title = str(payload.get(\"title\") or \"\").strip()[:MAX_TITLE_CHARS]\n    origin = \"\"\n    auto_refresh = kind == \"url\" and payload.get(\"auto_refresh\") is True\n    if kind == \"url\":\n        url = str(payload.get(\"url\") or \"\").strip()[:2000]\n        if not url:\n            return _bad(\"A web address is required.\")\n        try:\n            text, page_title = fetch_url(url)\n        except ValueError as problem:\n            return _bad(str(problem), \"fetch_failed\")\n        origin = url\n        title = title or page_title or _title_from(text, url)\n    else:\n        text = clean_text(payload.get(\"text\"))\n        origin = str(payload.get(\"filename\") or \"\").strip()[:200] if kind == \"file\" else \"\"\n        title = title or _title_from(text, origin or \"Pasted text\")\n    if len(text) < MIN_CHUNK_CHARS:\n        return _bad(\"There is not enough text to index (at least \"\n                    + str(MIN_CHUNK_CHARS) + \" characters).\")\n    if len(text) > MAX_SOURCE_CHARS:\n        return _bad(\"That source is too long (limit \"\n                    + str(MAX_SOURCE_CHARS) + \" characters). Split it into\"\n                    \" smaller documents.\", \"too_long\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"SELECT COUNT(*) AS n FROM \" + portal_db._q(SOURCES_TABLE) +\n                \" WHERE client_id = %s\",\n                (client_id,),\n            )\n            rows = portal_db.rows(cur)\n            if int((rows[0] if rows else {}).get(\"n\") or 0) >= MAX_SOURCES:\n                conn.rollback()\n                return _bad(\"This workspace already has the maximum of \"\n                            + str(MAX_SOURCES) + \" sources.\", \"limit\", 409)\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(SOURCES_TABLE) +\n                \" (client_id, title, kind, origin, status, auto_refresh)\"\n                \" VALUES (%s, %s, %s, %s, 'draft', %s) RETURNING \" + SOURCE_COLS,\n                (client_id, title, kind, origin, auto_refresh),\n            )\n            rows = portal_db.rows(cur)\n            source = rows[0] if rows else {\"id\": 0, \"title\": title,\n                                           \"kind\": kind, \"version\": 0}\n            source = ingest(cur, client_id, source, text, \"created\",\n                            principal.get(\"user_id\"))\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.put(\"/kb/sources/<int:source_id>\")\ndef put_source(source_id: int):\n    \"\"\"Owner review: publish / pause / back to draft, rename, and switch\n    automatic refresh of a web page on or off (audited).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    status = str(payload.get(\"status\") or \"\").strip().lower()\n    title = str(payload.get(\"title\") or \"\").strip()[:MAX_TITLE_CHARS]\n    if status and status not in STATUSES:\n        return _bad(\"status must be one of draft, published, paused.\")\n    auto_refresh = payload.get(\"auto_refresh\")\n    if auto_refresh is not None and not isinstance(auto_refresh, bool):\n        return _bad(\"auto_refresh must be true or false.\")\n    if not status and not title and auto_refresh is None:\n        return _bad(\"Nothing to update.\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            if status == \"published\" and int(source.get(\"chunk_count\") or 0) == 0:\n                conn.rollback()\n                return _bad(\"This source has no indexed text yet. Re-index it\"\n                            \" before publishing.\", \"empty_source\")\n            if auto_refresh and str(source.get(\"kind\") or \"\") != \"url\":\n                conn.rollback()\n                return _bad(\"Automatic refresh is only available for web\"\n                            \" pages.\")\n            sets = [\"updated_at = NOW()\"]\n            params: List[Any] = []\n            if status:\n                sets.append(\"status = %s\")\n                params.append(status)\n            if title:\n                sets.append(\"title = %s\")\n                params.append(title)\n            if auto_refresh is not None:\n                sets.append(\"auto_refresh = %s\")\n                params.append(auto_refresh)\n            params.extend([int(source_id), client_id])\n            cur.execute(\n                \"UPDATE \" + portal_db._q(SOURCES_TABLE) + \" SET \" +\n                \", \".join(sets) + \" WHERE id = %s AND client_id = %s RETURNING \"\n                + SOURCE_COLS,\n                tuple(params),\n            )\n            rows = portal_db.rows(cur)\n            updated = rows[0] if rows else dict(source)\n            if status and status != str(source.get(\"status\") or \"\"):\n                portal_db.log_action(\n                    cur, client_id, \"kb.source_\" + status, \"customer_user\",\n                    principal.get(\"user_id\"), None,\n                    (\"Published\" if status == \"published\" else\n                     \"Paused\" if status == \"paused\" else \"Unpublished\")\n                    + \" source '\" + str(updated.get(\"title\") or \"\")[:60] + \"'\",\n                )\n            if auto_refresh is not None and auto_refresh != bool(\n                    source.get(\"auto_refresh\")):\n                portal_db.log_action(\n                    cur, client_id, \"kb.source_auto_refresh_\"\n                    + (\"on\" if auto_refresh else \"off\"), \"customer_user\",\n                    principal.get(\"user_id\"), None,\n                    (\"Turned on\" if auto_refresh else \"Turned off\")\n                    + \" automatic refresh for '\"\n                    + str(updated.get(\"title\") or \"\")[:60] + \"'\",\n                )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(updated)}), 200\n\n\n@bp.delete(\"/kb/sources/<int:source_id>\")\ndef delete_source(source_id: int):\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(CHUNKS_TABLE) +\n                \" WHERE client_id = %s AND source_id = %s\",\n                (client_id, int(source_id)),\n            )\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(VERSIONS_TABLE) +\n                \" WHERE client_id = %s AND source_id = %s\",\n                (client_id, int(source_id)),\n            )\n            cur.execute(\n                \"DELETE FROM \" + portal_db._q(SOURCES_TABLE) +\n                \" WHERE id = %s AND client_id = %s\",\n                (int(source_id), client_id),\n            )\n            portal_db.log_action(\n                cur, client_id, \"kb.source_deleted\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                \"Deleted source '\" + str(source.get(\"title\") or \"\")[:60] + \"'\",\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.post(\"/kb/sources/<int:source_id>/reindex\")\ndef reindex_source(source_id: int):\n    \"\"\"Re-fetch a web page, or re-chunk pasted/uploaded text (new text in\n    the body, else the latest stored version). A file source given new\n    text plus ``filename`` is a new upload (the stored file name follows).\n    Publication state is kept.\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    new_text = clean_text(payload.get(\"text\"))\n    filename = str(payload.get(\"filename\") or \"\").strip()[:200]\n    if new_text and len(new_text) > MAX_SOURCE_CHARS:\n        return _bad(\"That text is too long (limit \" + str(MAX_SOURCE_CHARS)\n                    + \" characters).\", \"too_long\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            note = \"re-indexed\"\n            origin = None\n            if str(source.get(\"kind\") or \"\") == \"url\":\n                try:\n                    text, _title = fetch_url(str(source.get(\"origin\") or \"\"))\n                except ValueError as problem:\n                    record_error(cur, client_id, source_id, str(problem))\n                    conn.commit()\n                    return _bad(str(problem), \"fetch_failed\")\n                note = \"re-fetched\"\n            elif new_text:\n                text = new_text\n                note = \"text replaced\"\n                if filename and str(source.get(\"kind\") or \"\") == \"file\":\n                    note = \"new upload: \" + filename\n                    origin = filename\n            else:\n                latest = version_content(cur, client_id, source_id)\n                text = str((latest or {}).get(\"content\") or \"\")\n                if len(text) < MIN_CHUNK_CHARS:\n                    conn.rollback()\n                    return _bad(\"No stored text to re-index. Paste the text\"\n                                \" again.\", \"empty_source\")\n            if len(text) < MIN_CHUNK_CHARS:\n                record_error(cur, client_id, source_id,\n                             \"The page returned no readable text.\")\n                conn.commit()\n                return _bad(\"The page returned no readable text.\",\n                            \"fetch_failed\")\n            source = ingest(cur, client_id, source, text, note,\n                            principal.get(\"user_id\"), origin)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.get(\"/kb/sources/<int:source_id>/versions\")\ndef get_versions(source_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            versions = list_versions(cur, client_id, source_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"source\": source_public(source), \"versions\": versions}), 200\n\n\n@bp.post(\"/kb/sources/<int:source_id>/rollback\")\ndef rollback_source(source_id: int):\n    \"\"\"Re-index from an earlier version's stored text (creates a new\n    version, so history is never rewritten).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    try:\n        version = int(payload.get(\"version\") or 0)\n    except Exception:\n        version = 0\n    if version <= 0:\n        return _bad(\"version is required.\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            source = get_source(cur, client_id, source_id)\n            if source is None:\n                conn.rollback()\n                return _bad(\"No such source.\", \"not_found\", 404)\n            snapshot = version_content(cur, client_id, source_id, version)\n            if snapshot is None or len(str(snapshot.get(\"content\") or \"\")) < MIN_CHUNK_CHARS:\n                conn.rollback()\n                return _bad(\"That version is no longer stored.\", \"not_found\", 404)\n            source = ingest(cur, client_id, source, str(snapshot.get(\"content\")),\n                            \"rolled back to v\" + str(version),\n                            principal.get(\"user_id\"))\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"source\": source_public(source)}), 200\n\n\n@bp.get(\"/kb/search\")\ndef search_knowledge():\n    \"\"\"Owner tester: exactly what the AI would retrieve for a question.\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    query = str(request.args.get(\"q\") or \"\").strip()[:300]\n    if not query:\n        return _bad(\"q is required.\")\n    try:\n        n = int(request.args.get(\"n\") or 5)\n    except Exception:\n        n = 5\n    n = max(1, min(10, n))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            hits = retrieve(cur, client_id, query, n)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"query\": query, \"tokens\": query_tokens(query),\n                    \"hits\": hits}), 200\n\n\n@bp.post(\"/kb/extract\")\ndef extract_file():\n    \"\"\"\u00a7219: text of an uploaded PDF / Word file for the owner to review.\n    Human-only; stores nothing (the reviewed text is added through POST\n    /kb/sources as a draft, or as a new version through /reindex).\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    payload = request.get_json(silent=True) or {}\n    filename = str(payload.get(\"filename\") or \"\").strip()[:200]\n    if not filename:\n        return _bad(\"filename is required.\")\n    try:\n        data = portal_kb_files.decode_base64(payload.get(\"file_base64\"))\n        result = portal_kb_files.extract(filename, data, MAX_SOURCE_CHARS)\n    except portal_kb_files.ExtractError as problem:\n        return _bad(problem.message, problem.code,\n                    413 if problem.code == \"too_large\" else 400)\n    except Exception as problem:  # fail-soft: never a 500 for a bad file\n        logger.info(\"kb extract failed: %s\", problem)\n        return _bad(\"That file could not be read.\", \"extract_failed\")\n    return jsonify({\"filename\": filename, \"type\": result[\"type\"],\n                    \"text\": result[\"text\"], \"title\": result[\"title\"],\n                    \"pages\": result[\"pages\"], \"truncated\": result[\"truncated\"],\n                    \"chars\": len(result[\"text\"])}), 200\n\n\n# ---------------------------------------------------------------------------\n# \u00a7219 scheduled re-fetch of web pages (opt-in per source)\n# ---------------------------------------------------------------------------\n\n_DUE_AT = (\"GREATEST(COALESCE(checked_at, ingested_at, 'epoch'::timestamptz),\"\n           \" COALESCE(refresh_attempt_at, 'epoch'::timestamptz))\")\n_DUE = _DUE_AT + \" < NOW() - make_interval(hours => %s)\"\n_REFRESH_LOCK = threading.Lock()\n_REFRESH_RUNNING: set = set()\n_REFRESH_LAST: Dict[int, float] = {}\n\n\ndef due_refresh(cur, client_id: int, limit: int = 0) -> List[Dict[str, Any]]:\n    \"\"\"Opted-in web pages not checked for OF_KB_AUTO_REFRESH_HOURS, oldest\n    first, at most OF_KB_REFRESH_BATCH per run.\"\"\"\n    cur.execute(\n        \"SELECT \" + SOURCE_COLS + \" FROM \" + portal_db._q(SOURCES_TABLE) +\n        \" WHERE client_id = %s AND kind = 'url' AND auto_refresh AND \" + _DUE +\n        \" ORDER BY \" + _DUE_AT + \" ASC, id ASC LIMIT %s\",\n        (client_id, REFRESH_HOURS, int(limit or REFRESH_BATCH)),\n    )\n    return portal_db.rows(cur)\n\n\ndef _refresh_problem(cur, client_id: int, source_id: int, message: str) -> str:\n    cur.execute(\n        \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n        \" SET last_error = %s WHERE id = %s AND client_id = %s\",\n        ((\"Automatic refresh: \" + message)[:300], source_id, client_id),\n    )\n    return \"error\"\n\n\ndef refresh_source(client_id: int, source: Dict[str, Any]) -> str:\n    \"\"\"Re-fetch one opted-in page on its own connection. The row is claimed\n    atomically first (refresh_attempt_at), so two workers never fetch the\n    same page. Unchanged page -> only checked_at moves; changed page -> a\n    new version written by 'system' (publication state untouched).\n    Returns changed | unchanged | skipped | error; never raises.\"\"\"\n    source_id = int(source.get(\"id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n                \" SET refresh_attempt_at = NOW() WHERE id = %s AND client_id = %s\"\n                \" AND kind = 'url' AND auto_refresh AND \" + _DUE +\n                \" RETURNING id\",\n                (source_id, client_id, REFRESH_HOURS),\n            )\n            claimed = portal_db.rows(cur)\n            conn.commit()\n            if not claimed:\n                return \"skipped\"\n            try:\n                text, _title = fetch_url(str(source.get(\"origin\") or \"\"))\n            except ValueError as problem:\n                outcome = _refresh_problem(cur, client_id, source_id, str(problem))\n                conn.commit()\n                return outcome\n            except Exception as problem:\n                logger.info(\"kb refresh fetch crashed: %s\", problem)\n                outcome = _refresh_problem(cur, client_id, source_id,\n                                           \"the page could not be fetched.\")\n                conn.commit()\n                return outcome\n            content = stored_text(text)\n            if len(content) < MIN_CHUNK_CHARS:\n                outcome = _refresh_problem(cur, client_id, source_id,\n                                           \"the page returned no readable text.\")\n                conn.commit()\n                return outcome\n            latest = version_content(cur, client_id, source_id)\n            if latest is not None and str(latest.get(\"content\") or \"\") == content:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(SOURCES_TABLE) +\n                    \" SET checked_at = NOW(), last_error = ''\"\n                    \" WHERE id = %s AND client_id = %s\",\n                    (source_id, client_id),\n                )\n                conn.commit()\n                return \"unchanged\"\n            current = get_source(cur, client_id, source_id)\n            if current is None or str(current.get(\"kind\") or \"\") != \"url\" \\\n                    or not current.get(\"auto_refresh\"):\n                conn.commit()\n                return \"skipped\"\n            ingest(cur, client_id, current, content,\n                   \"automatic refresh: page changed\", None, None, \"system\")\n            conn.commit()\n            return \"changed\"\n    except Exception as problem:  # fail-soft: the next run retries\n        logger.info(\"kb refresh failed: %s\", problem)\n        try:\n            conn.rollback()\n        except Exception:\n            pass\n        return \"error\"\n    finally:\n        conn.close()\n\n\ndef run_refresh(client_id: int) -> Dict[str, int]:\n    \"\"\"One bounded refresh run for a tenant. Each page is isolated; a\n    changed page schedules a semantic-index sync.\"\"\"\n    counts = {\"changed\": 0, \"unchanged\": 0, \"error\": 0, \"skipped\": 0}\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            due = due_refresh(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    for source in due:\n        try:\n            outcome = refresh_source(client_id, source)\n        except Exception as problem:\n            logger.info(\"kb refresh crashed: %s\", problem)\n            outcome = \"error\"\n        counts[outcome if outcome in counts else \"error\"] += 1\n    if counts[\"changed\"]:\n        try:\n            import portal_kb_semantic\n\n            portal_kb_semantic.kick(client_id, \"edit\")\n        except Exception:\n            pass\n    return counts\n\n\ndef _refresh_job(client_id: int) -> None:\n    try:\n        run_refresh(client_id)\n    except Exception as problem:\n        logger.info(\"kb refresh job failed: %s\", problem)\n    finally:\n        with _REFRESH_LOCK:\n            _REFRESH_RUNNING.discard(client_id)\n\n\ndef kick_refresh(client_id: int) -> bool:\n    \"\"\"Connector-tick hook: start a background refresh run for the tenant,\n    at most once per OF_KB_REFRESH_TICK_SECONDS and one run at a time.\n    Returns True when a run was started.\"\"\"\n    try:\n        client_id = int(client_id or 0)\n    except Exception:\n        return False\n    if client_id <= 0:\n        return False\n    now = time.monotonic()\n    with _REFRESH_LOCK:\n        if client_id in _REFRESH_RUNNING:\n            return False\n        if now - _REFRESH_LAST.get(client_id, -1e18) < REFRESH_TICK_SECONDS:\n            return False\n        _REFRESH_RUNNING.add(client_id)\n        _REFRESH_LAST[client_id] = now\n    try:\n        threading.Thread(target=_refresh_job, args=(client_id,),\n                         name=\"kb-refresh-\" + str(client_id),\n                         daemon=True).start()\n    except Exception:\n        with _REFRESH_LOCK:\n            _REFRESH_RUNNING.discard(client_id)\n        return False\n    return True\n\n\n@bp.after_request\ndef _kb_semantic_after(response):\n    \"\"\"D1: a successful owner write schedules a semantic-index sync\n    (extract stores nothing, so it schedules nothing).\"\"\"\n    try:\n        if request.path.endswith(\"/kb/extract\"):\n            return response\n        import portal_kb_semantic\n\n        return portal_kb_semantic.kick_after_mutation(response)\n    except Exception:\n        return response\n\n");
writeNewRepair("omniflow-backend-patch/connector_api.py", "portal_knowledge.kick_refresh(tenant[\"client_id\"])", false,
    "\"\"\"\nOmniFlow Control Plane \u2014 CONNECTOR endpoints (shared channel queue).\n\nYe endpoints customer ke apne device (home laptop) par chalne wale connector\nke liye hain \u2014 server par WhatsApp session KABHI nahi chalta. Instagram\ncommands use the same queue and a server-side Meta Graph dispatch adapter.\nAuth: X-Omniflow-Key header = OMNIFLOW_SERVICE_KEY ya\nOMNIFLOW_ADMIN_API_KEY (wahi proven pattern jo admin endpoints use karte hain).\n\nConnector ka tenant resolve hota hai (pehla match jeeta):\n  1. Request body/query me explicit `client_id`\n  2. Backend env OMNIFLOW_CONNECTOR_USER_EMAIL -> platform_users lookup\n\nEndpoints:\n  POST /api/v1/connector/whatsapp/status          {state, phone?, account_name?, client_id?}\n  GET  /api/v1/connector/whatsapp/commands        ?limit=20  (pending, oldest first)\n  POST /api/v1/connector/whatsapp/commands/ack    {command_id, ok, note?, client_id?}\n  GET  /api/v1/connector/bot                      (tenant ka agent config)\n  POST /api/v1/connector/whatsapp/messages        {messages:[{from, body, name?, direction?}]}\n                                                  -> conversation upsert + message store\n\"\"\"\n\nimport logging\nimport os\nimport secrets\nimport threading\nimport time\nfrom datetime import datetime, timezone\nfrom typing import Any, Dict, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nimport portal_cod\nimport portal_contacts\nimport portal_sequences\n\n\nlogger = logging.getLogger(\"omniflow.connector-api\")\n\nbp = Blueprint(\"connector_api\", __name__, url_prefix=\"/api/v1/connector\")\n\nALLOWED_STATES = (\"disconnected\", \"connecting\", \"connected\")\n_TENANT_TTL_SECONDS = 300.0\n_tenant_lock = threading.Lock()\n_tenant_cache: Dict[str, Any] = {\"email\": None, \"value\": None, \"at\": 0.0}\n\n\ndef _authorized() -> bool:\n    key = request.headers.get(\"X-Omniflow-Key\", \"\")\n    if not key:\n        return False\n    accepted = [\n        os.environ.get(\"OMNIFLOW_SERVICE_KEY\"),\n        os.environ.get(\"OMNIFLOW_ADMIN_API_KEY\"),\n    ]\n    return any(k for k in accepted if k and secrets.compare_digest(key, k))\n\n\n@bp.before_request\ndef _guard():\n    if request.method == \"OPTIONS\":\n        return None\n    if not _authorized():\n        return jsonify({\"error\": {\"code\": \"forbidden\",\n                                  \"message\": \"Service key missing or invalid.\"}}), 403\n\n\ndef _resolve_tenant(explicit_client_id: Any) -> Optional[Dict[str, Any]]:\n    \"\"\"client_id (explicit > env email lookup). None = not configurable.\"\"\"\n    if isinstance(explicit_client_id, str) and explicit_client_id.strip().isdigit():\n        explicit_client_id = int(explicit_client_id.strip())\n    if isinstance(explicit_client_id, int) and not isinstance(explicit_client_id, bool) \\\n            and explicit_client_id > 0:\n        return {\"client_id\": explicit_client_id, \"user_id\": None, \"source\": \"request\"}\n\n    email = os.environ.get(\"OMNIFLOW_CONNECTOR_USER_EMAIL\", \"\").strip().lower()\n    if not email:\n        return None\n\n    now = time.time()\n    with _tenant_lock:\n        cached = (\n            _tenant_cache[\"email\"] == email\n            and _tenant_cache[\"value\"] is not None\n            and (now - float(_tenant_cache[\"at\"])) < _TENANT_TTL_SECONDS\n        )\n        if cached:\n            return dict(_tenant_cache[\"value\"])\n\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"SELECT id, client_id FROM \" + portal_db._q(portal_db.USERS_TABLE) +\n                \" WHERE \" + portal_db._q(portal_db.USER_EMAIL_COL) + \" = %s LIMIT 1\",\n                (email,),\n            )\n            found = portal_db.rows(cur)\n    finally:\n        conn.close()\n\n    if not found:\n        return None\n    tenant = {\"client_id\": found[0][\"client_id\"], \"user_id\": found[0][\"id\"], \"source\": \"env\"}\n    with _tenant_lock:\n        _tenant_cache.update({\"email\": email, \"value\": tenant, \"at\": now})\n    return dict(tenant)\n\n\ndef _tenant_or_error(explicit_client_id: Any):\n    try:\n        tenant = _resolve_tenant(explicit_client_id)\n    except Exception as error:\n        return None, (jsonify(portal_db.portal_unavailable(error, \"tenant resolve\")[0]), 503)\n    if tenant is None:\n        return None, (jsonify({\"error\": {\n            \"code\": \"connector_not_configured\",\n            \"message\": (\n                \"Connector tenant resolve nahi hua: body/query me client_id bhejein \"\n                \"ya backend par OMNIFLOW_CONNECTOR_USER_EMAIL set karein.\"\n            ),\n        }}), 503)\n    return tenant, None\n\n\ndef _json_body() -> Dict[str, Any]:\n    payload = request.get_json(silent=True)\n    return payload if isinstance(payload, dict) else {}\n\n\ndef _query_int(name: str, default: int, low: int, high: int) -> int:\n    raw = request.args.get(name, \"\")\n    try:\n        value = int(raw)\n    except (TypeError, ValueError):\n        return default\n    return max(low, min(high, value))\n\n\n@bp.post(\"/whatsapp/status\")\ndef report_status():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    state = payload.get(\"state\")\n    if state not in ALLOWED_STATES:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"state disconnected|connecting|connected hon.\"}}), 400\n    phone = payload.get(\"phone\")\n    phone = phone.strip() if isinstance(phone, str) else None\n    account_name = payload.get(\"account_name\")\n    account_name = account_name.strip() if isinstance(account_name, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(portal_db.STATUS_TABLE) +\n                    \" (client_id, state, phone, account_name, last_seen_at,\"\n                    \" reported_by, updated_at) \"\n                    \"VALUES (%s, %s, %s, %s, NOW(), %s, NOW()) \"\n                    \"ON CONFLICT (client_id) DO UPDATE SET \"\n                    \" state = EXCLUDED.state,\"\n                    \" phone = EXCLUDED.phone,\"\n                    \" account_name = EXCLUDED.account_name,\"\n                    \" last_seen_at = EXCLUDED.last_seen_at,\"\n                    \" reported_by = EXCLUDED.reported_by,\"\n                    \" updated_at = NOW()\",\n                    (tenant[\"client_id\"], state, phone, account_name, tenant[\"user_id\"]),\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"wa status write\")[0]), 503\n\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/whatsapp/commands\")\ndef list_commands():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 20, 1, 50)\n    channel = (args.get(\"channel\") or \"\").strip()\n    if channel and channel not in ALLOWED_CHANNELS:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"channel whatsapp|telegram|instagram hon.\"}}), 400\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_growth\n\n                    portal_growth.materialize_due_broadcasts(cur, tenant[\"client_id\"], conn)\n                    import portal_digest\n\n                    portal_digest.materialize_due_digest(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    import portal_checkout\n\n                    portal_checkout.materialize_cart_reminders(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    try:\n                        import portal_bi\n                        portal_bi.materialize_weekly_problems(\n                            cur, tenant[\"client_id\"], conn\n                        )\n                    except Exception:\n                        pass\n\n                except Exception:\n                    pass\n                try:\n                    import portal_webhooks\n\n                    portal_webhooks.deliver_pending_webhooks(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_sequences\n\n                    portal_sequences.deliver_due_sequence_steps(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_workflows\n\n                    portal_workflows.run_due_workflows(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_kb_semantic\n\n                    # D1: throttled background top-up of the knowledge\n                    # semantic index (no-op when off or up to date).\n                    portal_kb_semantic.kick(tenant[\"client_id\"], \"tick\")\n                except Exception:\n                    pass\n                try:\n                    import portal_knowledge\n\n                    # \u00a7219: scheduled re-fetch of opted-in knowledge web\n                    # pages (background, throttled per tenant; a changed\n                    # page becomes a new version, never auto-published).\n                    portal_knowledge.kick_refresh(tenant[\"client_id\"])\n                except Exception:\n                    pass\n                try:\n                    import portal_inbound_media\n\n                    # \u00a7214: retention sweep for stored customer files\n                    # (own connection, throttled per process).\n                    portal_inbound_media.maybe_purge(tenant[\"client_id\"])\n                except Exception:\n                    pass\n                try:\n                    import portal_events\n\n                    portal_events.requeue_due_commands(\n                        cur, tenant[\"client_id\"]\n                    )\n                except Exception:\n                    pass\n                cmd_sql = (\n                    \"SELECT id, action, payload, created_at FROM \"\n                    + portal_db._q(portal_db.CMD_TABLE) +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                )\n                cmd_params: list = [tenant[\"client_id\"]]\n                if channel:\n                    cmd_sql += \" AND channel = %s\"\n                    cmd_params.append(channel)\n                cmd_sql += \" ORDER BY id ASC LIMIT %s\"\n                cmd_params.append(limit)\n                cur.execute(cmd_sql, tuple(cmd_params))\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"commands read\")[0]), 503\n\n    commands = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        commands.append({\n            \"id\": row.get(\"id\"),\n            \"action\": row.get(\"action\"),\n            \"payload\": row.get(\"payload\") or {},\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"commands\": commands}), 200\n\n\n@bp.post(\"/whatsapp/commands/ack\")\ndef ack_command():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    command_id = payload.get(\"command_id\")\n    if isinstance(command_id, bool) or not isinstance(command_id, int) or command_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"command_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.CMD_TABLE) +\n                    \" SET status = %s, result_note = %s, updated_at = NOW() \"\n                    \"WHERE id = %s AND client_id = %s RETURNING id\",\n                    (\"done\" if ok_flag else \"failed\", note, command_id, tenant[\"client_id\"]),\n                )\n                try:\n                    import portal_events\n\n                    portal_events.on_command_ack(\n                        cur,\n                        tenant[\"client_id\"],\n                        command_id,\n                        ok_flag,\n                        note,\n                        payload.get(\"provider_message_id\"),\n                    )\n                except Exception:\n                    pass\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"command ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Command nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/bot\")\ndef connector_bot_config():\n    tenant, error = _tenant_or_error(request.args.get(\"client_id\"))\n    if error:\n        return error\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT agent_name, tone, greeting, fallback,\"\n                    \" working_hours_enabled, working_hours_start, working_hours_end,\"\n                    \" human_handoff_enabled, updated_at\"\n                    \" FROM \" + portal_db._q(portal_db.BOT_TABLE) +\n                    \" WHERE client_id = %s\",\n                    (tenant[\"client_id\"],),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"connector bot read\")[0]), 503\n\n    if not found:\n        return jsonify({\n            \"agent_name\": \"OmniFlow Assistant\",\n            \"tone\": \"friendly\",\n            \"greeting\": \"\",\n            \"fallback\": \"\",\n            \"working_hours_enabled\": False,\n            \"working_hours_start\": \"09:00\",\n            \"working_hours_end\": \"18:00\",\n            \"human_handoff_enabled\": False,\n            \"updated_at\": None,\n        }), 200\n\n    row = found[0]\n    updated = row.get(\"updated_at\")\n    if isinstance(updated, datetime) and updated.tzinfo is None:\n        updated = updated.replace(tzinfo=timezone.utc)\n    return jsonify({\n        \"agent_name\": row.get(\"agent_name\") or \"OmniFlow Assistant\",\n        \"tone\": row.get(\"tone\") if row.get(\"tone\") in (\"friendly\", \"professional\", \"concise\") else \"friendly\",\n        \"greeting\": row.get(\"greeting\") or \"\",\n        \"fallback\": row.get(\"fallback\") or \"\",\n        \"working_hours_enabled\": row.get(\"working_hours_enabled\") is True,\n        \"working_hours_start\": row.get(\"working_hours_start\") or \"09:00\",\n        \"working_hours_end\": row.get(\"working_hours_end\") or \"18:00\",\n        \"human_handoff_enabled\": row.get(\"human_handoff_enabled\") is True,\n        \"updated_at\": updated.isoformat() if isinstance(updated, datetime) else None,\n    }), 200\n\n\nMAX_INGEST_MESSAGES = 100\nALLOWED_DIRECTIONS = (\"in\", \"out\")\nALLOWED_CHANNELS = (\"whatsapp\", \"telegram\", \"instagram\")\n\n\n_AWAY_TABLE_READY = False\nAWAY_COOLDOWN_HOURS = 4\n_AWAY_DEFAULTS = {\n    \"enabled\": False,\n    \"timezone\": \"Asia/Karachi\",\n    \"days\": [\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n    ],\n    \"away_message\": \"\",\n}\n\n\ndef _ensure_away_table() -> None:\n    global _AWAY_TABLE_READY\n    if _AWAY_TABLE_READY:\n        return\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(\"portal_away_replies\") +\n                \" (id BIGSERIAL PRIMARY KEY, client_id BIGINT NOT NULL,\"\n                \" conversation_id BIGINT, contact_id TEXT NOT NULL,\"\n                \" body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',\"\n                \" result_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n                \" sent_at TIMESTAMPTZ)\"\n            )\n            cur.execute(\n                \"CREATE INDEX IF NOT EXISTS portal_away_pending_idx ON \" +\n                portal_db._q(\"portal_away_replies\") +\n                \" (client_id, status, id)\"\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    _AWAY_TABLE_READY = True\n\n\ndef _load_business_hours(cur, client_id):\n    try:\n        cur.execute(\n            \"SELECT settings -> 'business_hours' AS business_hours FROM \" +\n            portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n    except Exception:\n        return _AWAY_DEFAULTS\n    stored = rows[0].get(\"business_hours\") if rows and rows[0] else None\n    return stored if isinstance(stored, dict) else _AWAY_DEFAULTS\n\n\ndef _away_closed_now(config) -> bool:\n    try:\n        from zoneinfo import ZoneInfo\n\n        days = config.get(\"days\")\n        if not isinstance(days, list) or len(days) != 7:\n            return False\n        now = datetime.now(ZoneInfo(str(config.get(\"timezone\") or \"UTC\")))\n        day = days[(now.weekday() + 1) % 7]\n        if not isinstance(day, dict) or day.get(\"enabled\") is not True:\n            return True\n        current = now.strftime(\"%H:%M\")\n        start = day.get(\"start\")\n        end = day.get(\"end\")\n        if not isinstance(start, str) or not isinstance(end, str):\n            return True\n        return not (start <= current <= end)\n    except Exception:\n        return False\n\n\ndef _maybe_enqueue_away_reply(client_id, conversation_id, contact_id, direction, conn) -> Optional[bool]:\n    \"\"\"Queue one automatic away reply, inside the ingest transaction.\n\n    Fires only for inbound messages while business hours are enabled and\n    currently closed, at most once per conversation per cooldown window.\n    Never raises into the caller: wrap in try/except there.\n    \"\"\"\n    if direction != \"in\":\n        return\n    with conn.cursor() as cur:\n        config = _load_business_hours(cur, client_id)\n        message = config.get(\"away_message\")\n        if (\n            config.get(\"enabled\") is not True\n            or not isinstance(message, str)\n            or not message.strip()\n        ):\n            return\n        if not _away_closed_now(config):\n            return\n        cur.execute(\n            \"SELECT 1 FROM \" + portal_db._q(\"portal_away_replies\") +\n            \" WHERE client_id = %s AND conversation_id = %s\"\n            \" AND created_at > NOW() - INTERVAL '\" +\n            str(AWAY_COOLDOWN_HOURS) + \" hours'\"\n            \" LIMIT 1\",\n            (client_id, conversation_id),\n        )\n        if portal_db.rows(cur):\n            return\n        try:\n            contact_lang = portal_contacts.stored_language(\n                cur, client_id, contact_id)\n        except Exception:\n            contact_lang = None\n        if contact_lang == \"ur\":\n            variant = config.get(\"away_message_ur\")\n        elif contact_lang == \"roman\":\n            variant = config.get(\"away_message_roman\")\n        else:\n            variant = None\n        if isinstance(variant, str) and variant.strip():\n            message = variant\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(\"portal_away_replies\") +\n            \" (client_id, conversation_id, contact_id, body)\"\n            \" VALUES (%s, %s, %s, %s)\",\n            (client_id, conversation_id, contact_id, message.strip()),\n        )\n        return True\n\n\n@bp.get(\"/away-replies\")\ndef list_due_away_replies():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 5, 1, 20)\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id, contact_id, body, created_at FROM \" +\n                    portal_db._q(\"portal_away_replies\") +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                    \" ORDER BY id ASC LIMIT %s\",\n                    (tenant[\"client_id\"], limit),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away replies read\")[0]), 503\n\n    replies = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        replies.append({\n            \"id\": row.get(\"id\"),\n            \"external_user_id\": row.get(\"contact_id\"),\n            \"body\": row.get(\"body\"),\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"away_replies\": replies}), 200\n\n\n@bp.post(\"/away-replies/ack\")\ndef ack_away_reply():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    away_id = payload.get(\"away_id\")\n    if isinstance(away_id, bool) or not isinstance(away_id, int) or away_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"away_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(\"portal_away_replies\") +\n                    \" SET status = %s, result_note = %s, sent_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s AND status = 'pending' RETURNING id\",\n                    (\"sent\" if ok_flag else \"failed\", note, away_id, tenant[\"client_id\"]),\n                )\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Away reply nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\nclass MessageValidationError(ValueError):\n    \"\"\"A connector payload failed the shared message contract.\"\"\"\n\n\nclass IngestRateLimited(Exception):\n    \"\"\"The tenant exceeded the shared inbound ingest limit.\"\"\"\n\n\nclass IngestFailure(Exception):\n    \"\"\"Wrap a persistence/automation failure for route-level JSON errors.\"\"\"\n\n    def __init__(self, original: Exception, operation: str):\n        super().__init__(str(original))\n        self.original = original\n        self.operation = operation\n\n\ndef normalize_messages(messages: Any, default_channel: str = \"whatsapp\",\n                        require_nonempty: bool = True):\n    \"\"\"Normalize provider-neutral messages for every channel adapter.\n\n    The returned records are deliberately the same records consumed by the\n    existing conversation, event, automation, compliance and audit engine.\n    Provider adapters may retain ``id``, ``media`` and ``postback`` metadata;\n    the core still uses the normalized ``from/body/name/direction/channel``\n    contract for conversation work.\n    \"\"\"\n    if not isinstance(messages, list) or (require_nonempty and not messages):\n        raise MessageValidationError(\n            \"messages (non-empty list) zaroori hai.\"\n            if require_nonempty else \"messages list zaroori hai.\"\n        )\n    if len(messages) > MAX_INGEST_MESSAGES:\n        raise MessageValidationError(\n            \"Aik request me max \" + str(MAX_INGEST_MESSAGES)\n            + \" messages bhejein.\"\n        )\n\n    normalized = []\n    for item in messages:\n        if not isinstance(item, dict):\n            raise MessageValidationError(\"Har message aik object ho.\")\n        sender = item.get(\"from\")\n        if not isinstance(sender, str) or not sender.strip():\n            raise MessageValidationError(\"Har message me 'from' zaroori hai.\")\n        body = item.get(\"body\")\n        if body is None:\n            body = \"\"\n        elif not isinstance(body, str):\n            body = str(body)\n        try:\n            import portal_interactive\n\n            reply_body = portal_interactive.interactive_body_override(\n                item.get(\"interactive\"), body\n            )\n            if reply_body is not None:\n                body = reply_body\n        except Exception:\n            pass\n        direction = item.get(\"direction\", \"in\")\n        if direction not in ALLOWED_DIRECTIONS:\n            raise MessageValidationError(\"direction in|out hon.\")\n        channel = item.get(\"channel\", default_channel)\n        if channel not in ALLOWED_CHANNELS:\n            raise MessageValidationError(\n                \"channel \" + \"|\".join(ALLOWED_CHANNELS) + \" hon.\"\n            )\n        name = item.get(\"name\")\n        name = name.strip() if isinstance(name, str) else None\n        record = {\n            \"from\": sender.strip(),\n            \"body\": body,\n            \"name\": name,\n            \"direction\": direction,\n            \"channel\": channel,\n        }\n        provider_id = item.get(\"id\")\n        if isinstance(provider_id, (str, int)) and str(provider_id).strip():\n            record[\"id\"] = str(provider_id).strip()\n        # Keep adapter metadata in the event/audit payload without making it\n        # part of the core conversation contract.\n        for key in (\"media\", \"postback\", \"timestamp\", \"provider\"):\n            if key in item and item[key] is not None:\n                record[key] = item[key]\n        normalized.append(record)\n    return normalized\n\n\ndef ingest_messages_for_tenant(tenant: Dict[str, Any], normalized) -> int:\n    \"\"\"Run the existing message engine for any normalized channel.\n\n    Instagram calls this function rather than creating a second conversation\n    or automation pipeline. One-reply, approvals, compliance, sequences,\n    workflows, intelligence and event idempotency all remain in this path.\n    \"\"\"\n    inserted = 0\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_ratelimit\n\n                    if not portal_ratelimit.allow(\n                        cur,\n                        \"ingest:\" + str(tenant[\"client_id\"]),\n                        portal_ratelimit.ingest_limit(),\n                        60,\n                    ):\n                        conn.commit()\n                        raise IngestRateLimited()\n                except IngestRateLimited:\n                    raise\n                except Exception:\n                    pass\n                # D5: inline media bytes leave the records before the\n                # idempotency row is written (never stored in events).\n                media_blobs: Dict[int, Any] = {}\n                media_budget = None\n                store_budget = None\n                try:\n                    import portal_media_ai\n\n                    media_blobs = portal_media_ai.detach_blobs(normalized)\n                    media_budget = portal_media_ai.Budget()\n                except Exception:\n                    media_blobs, media_budget = {}, None\n                try:\n                    import portal_inbound_media\n\n                    store_budget = portal_inbound_media.Budget()\n                except Exception:\n                    store_budget = None\n                for item in normalized:\n                    try:\n                        import portal_events\n\n                        if not portal_events.record_inbound(\n                            cur, tenant[\"client_id\"], item\n                        ):\n                            continue\n                    except Exception:\n                        pass\n                    if item.get(\"media\") and media_budget is not None:\n                        try:\n                            # D5: voice notes / images -> text before the\n                            # one ingest path runs (deduped above, so a\n                            # replayed delivery never spends twice).\n                            portal_media_ai.enrich(\n                                cur, tenant[\"client_id\"], item,\n                                media_blobs.get(id(item)), media_budget)\n                        except Exception:\n                            pass\n                    if item[\"channel\"] == \"instagram\":\n                        try:\n                            import portal_identity\n\n                            identity_handle = item[\"from\"]\n                            if identity_handle.startswith(\"ig:\"):\n                                identity_handle = identity_handle[3:]\n                            portal_identity.resolve(\n                                cur,\n                                tenant[\"client_id\"],\n                                \"instagram\",\n                                identity_handle,\n                                item[\"name\"] or \"\",\n                                create=True,\n                                source=\"instagram_webhook\",\n                            )\n                        except Exception:\n                            pass\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.CONV_TABLE) +\n                        \" (client_id, channel, contact_id, contact_name,\"\n                        \" status, last_message_preview, last_message_at,\"\n                        \" created_at, updated_at) \"\n                        \"VALUES (%s, %s, %s, %s, 'open', %s, NOW(), NOW(), NOW()) \"\n                        \"ON CONFLICT (client_id, channel, contact_id) DO UPDATE SET \"\n                        \" contact_name = COALESCE(EXCLUDED.contact_name,\"\n                        \" \" + portal_db._q(portal_db.CONV_TABLE) + \".contact_name), \"\n                        \" last_message_preview = EXCLUDED.last_message_preview, \"\n                        \" last_message_at = EXCLUDED.last_message_at, \"\n                        \" updated_at = NOW() \"\n                        \"RETURNING id\",\n                        (tenant[\"client_id\"], item[\"channel\"], item[\"from\"],\n                         item[\"name\"], item[\"body\"]),\n                    )\n                    conv = portal_db.rows(cur)\n                    conversation_id = conv[0][\"id\"] if conv else None\n                    # \u00a7215: inbound media needs the message id (chat-bubble\n                    # previews); every other message keeps the plain INSERT.\n                    keep_media = bool(item.get(\"media\")) \\\n                        and item[\"direction\"] == \"in\" \\\n                        and store_budget is not None\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.MSGS_TABLE) +\n                        \" (conversation_id, client_id, direction, body,\"\n                        \" sender_name, status, created_at) \"\n                        \"VALUES (%s, %s, %s, %s, %s, %s, NOW())\"\n                        + (\" RETURNING id\" if keep_media else \"\"),\n                        (conversation_id, tenant[\"client_id\"], item[\"direction\"],\n                         item[\"body\"], item[\"name\"],\n                         \"received\" if item[\"direction\"] == \"in\" else \"sent\"),\n                    )\n                    message_id = None\n                    if keep_media:\n                        try:\n                            returned = portal_db.rows(cur)\n                            message_id = returned[0].get(\"id\") \\\n                                if returned else None\n                        except Exception:\n                            message_id = None\n                    if keep_media:\n                        try:\n                            # \u00a7214: keep customer images / voice notes so\n                            # the inbox can show them after provider links\n                            # expire (savepoint-guarded, never raises).\n                            portal_inbound_media.capture(\n                                cur, tenant[\"client_id\"], conversation_id,\n                                item, media_blobs.get(id(item)),\n                                store_budget, message_id)\n                        except Exception:\n                            pass\n                    item.pop(\"_media_fetched\", None)\n                    # One-reply law (B2): the first automation that sends a\n                    # customer-visible reply claims the message; the other\n                    # reply hooks stay quiet. Side-effect hooks (language\n                    # detection, compliance, listen, routing, sequences)\n                    # always run.\n                    claimed_by = None\n                    if claimed_by is None:\n                        try:\n                            import portal_approvals\n\n                            if portal_approvals.maybe_decide(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"approvals\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if _maybe_enqueue_away_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"away\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if portal_cod.maybe_cod_flow(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"cod\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_brain\n\n                            if portal_brain.maybe_answer(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                conn,\n                            ):\n                                claimed_by = \"brain\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_kb\n                            import portal_intents\n\n                            import portal_llm\n\n                            with portal_llm.usage_scope(\n                                    \"intent\", tenant[\"client_id\"]):\n                                intent = portal_intents.classify(item[\"body\"])\n                            if portal_kb.maybe_auto_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                intent,\n                                conn,\n                            ):\n                                claimed_by = \"kb\"\n                        except Exception:\n                            pass\n                    if claimed_by:\n                        try:\n                            import portal_events\n\n                            portal_events.note_claim(\n                                cur, tenant[\"client_id\"], item, claimed_by\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_contacts.maybe_detect_language(\n                            tenant[\"client_id\"],\n                            item[\"from\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    if item[\"direction\"] == \"in\":\n                        try:\n                            import portal_compliance\n\n                            portal_compliance.maybe_opt_out(\n                                tenant[\"client_id\"],\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_listen\n\n                            portal_listen.maybe_listen(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_routing\n\n                            portal_routing.maybe_route(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_intelligence\n\n                            portal_intelligence.maybe_analyze(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_approvals\n\n                            portal_approvals.maybe_request(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_sequences.maybe_enroll_new_contact(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_enroll_keyword(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_auto_pause_replies(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_workflows\n\n                        portal_workflows.maybe_trigger_message(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            item[\"direction\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_events\n\n                        portal_events.mark_inbound_done(\n                            cur, tenant[\"client_id\"], item\n                        )\n                    except Exception:\n                        pass\n                    inserted += 1\n            conn.commit()\n        finally:\n            conn.close()\n    except IngestRateLimited:\n        raise\n    except Exception as error:\n        raise IngestFailure(error, \"messages ingest\") from error\n    return inserted\n\n\n@bp.post(\"/whatsapp/messages\")\ndef ingest_whatsapp_messages():\n    \"\"\"Store connector-delivered messages through the shared channel engine.\"\"\"\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n    try:\n        normalized = normalize_messages(\n            payload.get(\"messages\"), default_channel=\"whatsapp\"\n        )\n    except MessageValidationError as error:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": str(error)}}), 400\n\n    try:\n        inserted = ingest_messages_for_tenant(tenant, normalized)\n    except IngestRateLimited:\n        return jsonify({\"error\": {\n            \"code\": \"rate_limited\",\n            \"message\": \"Too many messages; slow down.\",\n        }}), 429\n    except IngestFailure as failure:\n        return jsonify(portal_db.portal_unavailable(\n            failure.original, failure.operation)[0]), 503\n\n    logger.info(\"whatsapp messages ingested client_id=%s count=%s\",\n                tenant[\"client_id\"], inserted)\n    return jsonify({\"ok\": True, \"inserted\": inserted}), 200\n\n");
writeNewRepair("OmniFlow-Control-Plane/connector_api.py", "portal_knowledge.kick_refresh(tenant[\"client_id\"])", true,
    "\"\"\"\nOmniFlow Control Plane \u2014 CONNECTOR endpoints (shared channel queue).\n\nYe endpoints customer ke apne device (home laptop) par chalne wale connector\nke liye hain \u2014 server par WhatsApp session KABHI nahi chalta. Instagram\ncommands use the same queue and a server-side Meta Graph dispatch adapter.\nAuth: X-Omniflow-Key header = OMNIFLOW_SERVICE_KEY ya\nOMNIFLOW_ADMIN_API_KEY (wahi proven pattern jo admin endpoints use karte hain).\n\nConnector ka tenant resolve hota hai (pehla match jeeta):\n  1. Request body/query me explicit `client_id`\n  2. Backend env OMNIFLOW_CONNECTOR_USER_EMAIL -> platform_users lookup\n\nEndpoints:\n  POST /api/v1/connector/whatsapp/status          {state, phone?, account_name?, client_id?}\n  GET  /api/v1/connector/whatsapp/commands        ?limit=20  (pending, oldest first)\n  POST /api/v1/connector/whatsapp/commands/ack    {command_id, ok, note?, client_id?}\n  GET  /api/v1/connector/bot                      (tenant ka agent config)\n  POST /api/v1/connector/whatsapp/messages        {messages:[{from, body, name?, direction?}]}\n                                                  -> conversation upsert + message store\n\"\"\"\n\nimport logging\nimport os\nimport secrets\nimport threading\nimport time\nfrom datetime import datetime, timezone\nfrom typing import Any, Dict, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nimport portal_cod\nimport portal_contacts\nimport portal_sequences\n\n\nlogger = logging.getLogger(\"omniflow.connector-api\")\n\nbp = Blueprint(\"connector_api\", __name__, url_prefix=\"/api/v1/connector\")\n\nALLOWED_STATES = (\"disconnected\", \"connecting\", \"connected\")\n_TENANT_TTL_SECONDS = 300.0\n_tenant_lock = threading.Lock()\n_tenant_cache: Dict[str, Any] = {\"email\": None, \"value\": None, \"at\": 0.0}\n\n\ndef _authorized() -> bool:\n    key = request.headers.get(\"X-Omniflow-Key\", \"\")\n    if not key:\n        return False\n    accepted = [\n        os.environ.get(\"OMNIFLOW_SERVICE_KEY\"),\n        os.environ.get(\"OMNIFLOW_ADMIN_API_KEY\"),\n    ]\n    return any(k for k in accepted if k and secrets.compare_digest(key, k))\n\n\n@bp.before_request\ndef _guard():\n    if request.method == \"OPTIONS\":\n        return None\n    if not _authorized():\n        return jsonify({\"error\": {\"code\": \"forbidden\",\n                                  \"message\": \"Service key missing or invalid.\"}}), 403\n\n\ndef _resolve_tenant(explicit_client_id: Any) -> Optional[Dict[str, Any]]:\n    \"\"\"client_id (explicit > env email lookup). None = not configurable.\"\"\"\n    if isinstance(explicit_client_id, str) and explicit_client_id.strip().isdigit():\n        explicit_client_id = int(explicit_client_id.strip())\n    if isinstance(explicit_client_id, int) and not isinstance(explicit_client_id, bool) \\\n            and explicit_client_id > 0:\n        return {\"client_id\": explicit_client_id, \"user_id\": None, \"source\": \"request\"}\n\n    email = os.environ.get(\"OMNIFLOW_CONNECTOR_USER_EMAIL\", \"\").strip().lower()\n    if not email:\n        return None\n\n    now = time.time()\n    with _tenant_lock:\n        cached = (\n            _tenant_cache[\"email\"] == email\n            and _tenant_cache[\"value\"] is not None\n            and (now - float(_tenant_cache[\"at\"])) < _TENANT_TTL_SECONDS\n        )\n        if cached:\n            return dict(_tenant_cache[\"value\"])\n\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"SELECT id, client_id FROM \" + portal_db._q(portal_db.USERS_TABLE) +\n                \" WHERE \" + portal_db._q(portal_db.USER_EMAIL_COL) + \" = %s LIMIT 1\",\n                (email,),\n            )\n            found = portal_db.rows(cur)\n    finally:\n        conn.close()\n\n    if not found:\n        return None\n    tenant = {\"client_id\": found[0][\"client_id\"], \"user_id\": found[0][\"id\"], \"source\": \"env\"}\n    with _tenant_lock:\n        _tenant_cache.update({\"email\": email, \"value\": tenant, \"at\": now})\n    return dict(tenant)\n\n\ndef _tenant_or_error(explicit_client_id: Any):\n    try:\n        tenant = _resolve_tenant(explicit_client_id)\n    except Exception as error:\n        return None, (jsonify(portal_db.portal_unavailable(error, \"tenant resolve\")[0]), 503)\n    if tenant is None:\n        return None, (jsonify({\"error\": {\n            \"code\": \"connector_not_configured\",\n            \"message\": (\n                \"Connector tenant resolve nahi hua: body/query me client_id bhejein \"\n                \"ya backend par OMNIFLOW_CONNECTOR_USER_EMAIL set karein.\"\n            ),\n        }}), 503)\n    return tenant, None\n\n\ndef _json_body() -> Dict[str, Any]:\n    payload = request.get_json(silent=True)\n    return payload if isinstance(payload, dict) else {}\n\n\ndef _query_int(name: str, default: int, low: int, high: int) -> int:\n    raw = request.args.get(name, \"\")\n    try:\n        value = int(raw)\n    except (TypeError, ValueError):\n        return default\n    return max(low, min(high, value))\n\n\n@bp.post(\"/whatsapp/status\")\ndef report_status():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    state = payload.get(\"state\")\n    if state not in ALLOWED_STATES:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"state disconnected|connecting|connected hon.\"}}), 400\n    phone = payload.get(\"phone\")\n    phone = phone.strip() if isinstance(phone, str) else None\n    account_name = payload.get(\"account_name\")\n    account_name = account_name.strip() if isinstance(account_name, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(portal_db.STATUS_TABLE) +\n                    \" (client_id, state, phone, account_name, last_seen_at,\"\n                    \" reported_by, updated_at) \"\n                    \"VALUES (%s, %s, %s, %s, NOW(), %s, NOW()) \"\n                    \"ON CONFLICT (client_id) DO UPDATE SET \"\n                    \" state = EXCLUDED.state,\"\n                    \" phone = EXCLUDED.phone,\"\n                    \" account_name = EXCLUDED.account_name,\"\n                    \" last_seen_at = EXCLUDED.last_seen_at,\"\n                    \" reported_by = EXCLUDED.reported_by,\"\n                    \" updated_at = NOW()\",\n                    (tenant[\"client_id\"], state, phone, account_name, tenant[\"user_id\"]),\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"wa status write\")[0]), 503\n\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/whatsapp/commands\")\ndef list_commands():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 20, 1, 50)\n    channel = (args.get(\"channel\") or \"\").strip()\n    if channel and channel not in ALLOWED_CHANNELS:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"channel whatsapp|telegram|instagram hon.\"}}), 400\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_growth\n\n                    portal_growth.materialize_due_broadcasts(cur, tenant[\"client_id\"], conn)\n                    import portal_digest\n\n                    portal_digest.materialize_due_digest(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    import portal_checkout\n\n                    portal_checkout.materialize_cart_reminders(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    try:\n                        import portal_bi\n                        portal_bi.materialize_weekly_problems(\n                            cur, tenant[\"client_id\"], conn\n                        )\n                    except Exception:\n                        pass\n\n                except Exception:\n                    pass\n                try:\n                    import portal_webhooks\n\n                    portal_webhooks.deliver_pending_webhooks(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_sequences\n\n                    portal_sequences.deliver_due_sequence_steps(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_workflows\n\n                    portal_workflows.run_due_workflows(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_kb_semantic\n\n                    # D1: throttled background top-up of the knowledge\n                    # semantic index (no-op when off or up to date).\n                    portal_kb_semantic.kick(tenant[\"client_id\"], \"tick\")\n                except Exception:\n                    pass\n                try:\n                    import portal_knowledge\n\n                    # \u00a7219: scheduled re-fetch of opted-in knowledge web\n                    # pages (background, throttled per tenant; a changed\n                    # page becomes a new version, never auto-published).\n                    portal_knowledge.kick_refresh(tenant[\"client_id\"])\n                except Exception:\n                    pass\n                try:\n                    import portal_inbound_media\n\n                    # \u00a7214: retention sweep for stored customer files\n                    # (own connection, throttled per process).\n                    portal_inbound_media.maybe_purge(tenant[\"client_id\"])\n                except Exception:\n                    pass\n                try:\n                    import portal_events\n\n                    portal_events.requeue_due_commands(\n                        cur, tenant[\"client_id\"]\n                    )\n                except Exception:\n                    pass\n                cmd_sql = (\n                    \"SELECT id, action, payload, created_at FROM \"\n                    + portal_db._q(portal_db.CMD_TABLE) +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                )\n                cmd_params: list = [tenant[\"client_id\"]]\n                if channel:\n                    cmd_sql += \" AND channel = %s\"\n                    cmd_params.append(channel)\n                cmd_sql += \" ORDER BY id ASC LIMIT %s\"\n                cmd_params.append(limit)\n                cur.execute(cmd_sql, tuple(cmd_params))\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"commands read\")[0]), 503\n\n    commands = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        commands.append({\n            \"id\": row.get(\"id\"),\n            \"action\": row.get(\"action\"),\n            \"payload\": row.get(\"payload\") or {},\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"commands\": commands}), 200\n\n\n@bp.post(\"/whatsapp/commands/ack\")\ndef ack_command():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    command_id = payload.get(\"command_id\")\n    if isinstance(command_id, bool) or not isinstance(command_id, int) or command_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"command_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.CMD_TABLE) +\n                    \" SET status = %s, result_note = %s, updated_at = NOW() \"\n                    \"WHERE id = %s AND client_id = %s RETURNING id\",\n                    (\"done\" if ok_flag else \"failed\", note, command_id, tenant[\"client_id\"]),\n                )\n                try:\n                    import portal_events\n\n                    portal_events.on_command_ack(\n                        cur,\n                        tenant[\"client_id\"],\n                        command_id,\n                        ok_flag,\n                        note,\n                        payload.get(\"provider_message_id\"),\n                    )\n                except Exception:\n                    pass\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"command ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Command nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/bot\")\ndef connector_bot_config():\n    tenant, error = _tenant_or_error(request.args.get(\"client_id\"))\n    if error:\n        return error\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT agent_name, tone, greeting, fallback,\"\n                    \" working_hours_enabled, working_hours_start, working_hours_end,\"\n                    \" human_handoff_enabled, updated_at\"\n                    \" FROM \" + portal_db._q(portal_db.BOT_TABLE) +\n                    \" WHERE client_id = %s\",\n                    (tenant[\"client_id\"],),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"connector bot read\")[0]), 503\n\n    if not found:\n        return jsonify({\n            \"agent_name\": \"OmniFlow Assistant\",\n            \"tone\": \"friendly\",\n            \"greeting\": \"\",\n            \"fallback\": \"\",\n            \"working_hours_enabled\": False,\n            \"working_hours_start\": \"09:00\",\n            \"working_hours_end\": \"18:00\",\n            \"human_handoff_enabled\": False,\n            \"updated_at\": None,\n        }), 200\n\n    row = found[0]\n    updated = row.get(\"updated_at\")\n    if isinstance(updated, datetime) and updated.tzinfo is None:\n        updated = updated.replace(tzinfo=timezone.utc)\n    return jsonify({\n        \"agent_name\": row.get(\"agent_name\") or \"OmniFlow Assistant\",\n        \"tone\": row.get(\"tone\") if row.get(\"tone\") in (\"friendly\", \"professional\", \"concise\") else \"friendly\",\n        \"greeting\": row.get(\"greeting\") or \"\",\n        \"fallback\": row.get(\"fallback\") or \"\",\n        \"working_hours_enabled\": row.get(\"working_hours_enabled\") is True,\n        \"working_hours_start\": row.get(\"working_hours_start\") or \"09:00\",\n        \"working_hours_end\": row.get(\"working_hours_end\") or \"18:00\",\n        \"human_handoff_enabled\": row.get(\"human_handoff_enabled\") is True,\n        \"updated_at\": updated.isoformat() if isinstance(updated, datetime) else None,\n    }), 200\n\n\nMAX_INGEST_MESSAGES = 100\nALLOWED_DIRECTIONS = (\"in\", \"out\")\nALLOWED_CHANNELS = (\"whatsapp\", \"telegram\", \"instagram\")\n\n\n_AWAY_TABLE_READY = False\nAWAY_COOLDOWN_HOURS = 4\n_AWAY_DEFAULTS = {\n    \"enabled\": False,\n    \"timezone\": \"Asia/Karachi\",\n    \"days\": [\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n    ],\n    \"away_message\": \"\",\n}\n\n\ndef _ensure_away_table() -> None:\n    global _AWAY_TABLE_READY\n    if _AWAY_TABLE_READY:\n        return\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(\"portal_away_replies\") +\n                \" (id BIGSERIAL PRIMARY KEY, client_id BIGINT NOT NULL,\"\n                \" conversation_id BIGINT, contact_id TEXT NOT NULL,\"\n                \" body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',\"\n                \" result_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n                \" sent_at TIMESTAMPTZ)\"\n            )\n            cur.execute(\n                \"CREATE INDEX IF NOT EXISTS portal_away_pending_idx ON \" +\n                portal_db._q(\"portal_away_replies\") +\n                \" (client_id, status, id)\"\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    _AWAY_TABLE_READY = True\n\n\ndef _load_business_hours(cur, client_id):\n    try:\n        cur.execute(\n            \"SELECT settings -> 'business_hours' AS business_hours FROM \" +\n            portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n    except Exception:\n        return _AWAY_DEFAULTS\n    stored = rows[0].get(\"business_hours\") if rows and rows[0] else None\n    return stored if isinstance(stored, dict) else _AWAY_DEFAULTS\n\n\ndef _away_closed_now(config) -> bool:\n    try:\n        from zoneinfo import ZoneInfo\n\n        days = config.get(\"days\")\n        if not isinstance(days, list) or len(days) != 7:\n            return False\n        now = datetime.now(ZoneInfo(str(config.get(\"timezone\") or \"UTC\")))\n        day = days[(now.weekday() + 1) % 7]\n        if not isinstance(day, dict) or day.get(\"enabled\") is not True:\n            return True\n        current = now.strftime(\"%H:%M\")\n        start = day.get(\"start\")\n        end = day.get(\"end\")\n        if not isinstance(start, str) or not isinstance(end, str):\n            return True\n        return not (start <= current <= end)\n    except Exception:\n        return False\n\n\ndef _maybe_enqueue_away_reply(client_id, conversation_id, contact_id, direction, conn) -> Optional[bool]:\n    \"\"\"Queue one automatic away reply, inside the ingest transaction.\n\n    Fires only for inbound messages while business hours are enabled and\n    currently closed, at most once per conversation per cooldown window.\n    Never raises into the caller: wrap in try/except there.\n    \"\"\"\n    if direction != \"in\":\n        return\n    with conn.cursor() as cur:\n        config = _load_business_hours(cur, client_id)\n        message = config.get(\"away_message\")\n        if (\n            config.get(\"enabled\") is not True\n            or not isinstance(message, str)\n            or not message.strip()\n        ):\n            return\n        if not _away_closed_now(config):\n            return\n        cur.execute(\n            \"SELECT 1 FROM \" + portal_db._q(\"portal_away_replies\") +\n            \" WHERE client_id = %s AND conversation_id = %s\"\n            \" AND created_at > NOW() - INTERVAL '\" +\n            str(AWAY_COOLDOWN_HOURS) + \" hours'\"\n            \" LIMIT 1\",\n            (client_id, conversation_id),\n        )\n        if portal_db.rows(cur):\n            return\n        try:\n            contact_lang = portal_contacts.stored_language(\n                cur, client_id, contact_id)\n        except Exception:\n            contact_lang = None\n        if contact_lang == \"ur\":\n            variant = config.get(\"away_message_ur\")\n        elif contact_lang == \"roman\":\n            variant = config.get(\"away_message_roman\")\n        else:\n            variant = None\n        if isinstance(variant, str) and variant.strip():\n            message = variant\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(\"portal_away_replies\") +\n            \" (client_id, conversation_id, contact_id, body)\"\n            \" VALUES (%s, %s, %s, %s)\",\n            (client_id, conversation_id, contact_id, message.strip()),\n        )\n        return True\n\n\n@bp.get(\"/away-replies\")\ndef list_due_away_replies():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 5, 1, 20)\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id, contact_id, body, created_at FROM \" +\n                    portal_db._q(\"portal_away_replies\") +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                    \" ORDER BY id ASC LIMIT %s\",\n                    (tenant[\"client_id\"], limit),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away replies read\")[0]), 503\n\n    replies = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        replies.append({\n            \"id\": row.get(\"id\"),\n            \"external_user_id\": row.get(\"contact_id\"),\n            \"body\": row.get(\"body\"),\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"away_replies\": replies}), 200\n\n\n@bp.post(\"/away-replies/ack\")\ndef ack_away_reply():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    away_id = payload.get(\"away_id\")\n    if isinstance(away_id, bool) or not isinstance(away_id, int) or away_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"away_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(\"portal_away_replies\") +\n                    \" SET status = %s, result_note = %s, sent_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s AND status = 'pending' RETURNING id\",\n                    (\"sent\" if ok_flag else \"failed\", note, away_id, tenant[\"client_id\"]),\n                )\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Away reply nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\nclass MessageValidationError(ValueError):\n    \"\"\"A connector payload failed the shared message contract.\"\"\"\n\n\nclass IngestRateLimited(Exception):\n    \"\"\"The tenant exceeded the shared inbound ingest limit.\"\"\"\n\n\nclass IngestFailure(Exception):\n    \"\"\"Wrap a persistence/automation failure for route-level JSON errors.\"\"\"\n\n    def __init__(self, original: Exception, operation: str):\n        super().__init__(str(original))\n        self.original = original\n        self.operation = operation\n\n\ndef normalize_messages(messages: Any, default_channel: str = \"whatsapp\",\n                        require_nonempty: bool = True):\n    \"\"\"Normalize provider-neutral messages for every channel adapter.\n\n    The returned records are deliberately the same records consumed by the\n    existing conversation, event, automation, compliance and audit engine.\n    Provider adapters may retain ``id``, ``media`` and ``postback`` metadata;\n    the core still uses the normalized ``from/body/name/direction/channel``\n    contract for conversation work.\n    \"\"\"\n    if not isinstance(messages, list) or (require_nonempty and not messages):\n        raise MessageValidationError(\n            \"messages (non-empty list) zaroori hai.\"\n            if require_nonempty else \"messages list zaroori hai.\"\n        )\n    if len(messages) > MAX_INGEST_MESSAGES:\n        raise MessageValidationError(\n            \"Aik request me max \" + str(MAX_INGEST_MESSAGES)\n            + \" messages bhejein.\"\n        )\n\n    normalized = []\n    for item in messages:\n        if not isinstance(item, dict):\n            raise MessageValidationError(\"Har message aik object ho.\")\n        sender = item.get(\"from\")\n        if not isinstance(sender, str) or not sender.strip():\n            raise MessageValidationError(\"Har message me 'from' zaroori hai.\")\n        body = item.get(\"body\")\n        if body is None:\n            body = \"\"\n        elif not isinstance(body, str):\n            body = str(body)\n        try:\n            import portal_interactive\n\n            reply_body = portal_interactive.interactive_body_override(\n                item.get(\"interactive\"), body\n            )\n            if reply_body is not None:\n                body = reply_body\n        except Exception:\n            pass\n        direction = item.get(\"direction\", \"in\")\n        if direction not in ALLOWED_DIRECTIONS:\n            raise MessageValidationError(\"direction in|out hon.\")\n        channel = item.get(\"channel\", default_channel)\n        if channel not in ALLOWED_CHANNELS:\n            raise MessageValidationError(\n                \"channel \" + \"|\".join(ALLOWED_CHANNELS) + \" hon.\"\n            )\n        name = item.get(\"name\")\n        name = name.strip() if isinstance(name, str) else None\n        record = {\n            \"from\": sender.strip(),\n            \"body\": body,\n            \"name\": name,\n            \"direction\": direction,\n            \"channel\": channel,\n        }\n        provider_id = item.get(\"id\")\n        if isinstance(provider_id, (str, int)) and str(provider_id).strip():\n            record[\"id\"] = str(provider_id).strip()\n        # Keep adapter metadata in the event/audit payload without making it\n        # part of the core conversation contract.\n        for key in (\"media\", \"postback\", \"timestamp\", \"provider\"):\n            if key in item and item[key] is not None:\n                record[key] = item[key]\n        normalized.append(record)\n    return normalized\n\n\ndef ingest_messages_for_tenant(tenant: Dict[str, Any], normalized) -> int:\n    \"\"\"Run the existing message engine for any normalized channel.\n\n    Instagram calls this function rather than creating a second conversation\n    or automation pipeline. One-reply, approvals, compliance, sequences,\n    workflows, intelligence and event idempotency all remain in this path.\n    \"\"\"\n    inserted = 0\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_ratelimit\n\n                    if not portal_ratelimit.allow(\n                        cur,\n                        \"ingest:\" + str(tenant[\"client_id\"]),\n                        portal_ratelimit.ingest_limit(),\n                        60,\n                    ):\n                        conn.commit()\n                        raise IngestRateLimited()\n                except IngestRateLimited:\n                    raise\n                except Exception:\n                    pass\n                # D5: inline media bytes leave the records before the\n                # idempotency row is written (never stored in events).\n                media_blobs: Dict[int, Any] = {}\n                media_budget = None\n                store_budget = None\n                try:\n                    import portal_media_ai\n\n                    media_blobs = portal_media_ai.detach_blobs(normalized)\n                    media_budget = portal_media_ai.Budget()\n                except Exception:\n                    media_blobs, media_budget = {}, None\n                try:\n                    import portal_inbound_media\n\n                    store_budget = portal_inbound_media.Budget()\n                except Exception:\n                    store_budget = None\n                for item in normalized:\n                    try:\n                        import portal_events\n\n                        if not portal_events.record_inbound(\n                            cur, tenant[\"client_id\"], item\n                        ):\n                            continue\n                    except Exception:\n                        pass\n                    if item.get(\"media\") and media_budget is not None:\n                        try:\n                            # D5: voice notes / images -> text before the\n                            # one ingest path runs (deduped above, so a\n                            # replayed delivery never spends twice).\n                            portal_media_ai.enrich(\n                                cur, tenant[\"client_id\"], item,\n                                media_blobs.get(id(item)), media_budget)\n                        except Exception:\n                            pass\n                    if item[\"channel\"] == \"instagram\":\n                        try:\n                            import portal_identity\n\n                            identity_handle = item[\"from\"]\n                            if identity_handle.startswith(\"ig:\"):\n                                identity_handle = identity_handle[3:]\n                            portal_identity.resolve(\n                                cur,\n                                tenant[\"client_id\"],\n                                \"instagram\",\n                                identity_handle,\n                                item[\"name\"] or \"\",\n                                create=True,\n                                source=\"instagram_webhook\",\n                            )\n                        except Exception:\n                            pass\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.CONV_TABLE) +\n                        \" (client_id, channel, contact_id, contact_name,\"\n                        \" status, last_message_preview, last_message_at,\"\n                        \" created_at, updated_at) \"\n                        \"VALUES (%s, %s, %s, %s, 'open', %s, NOW(), NOW(), NOW()) \"\n                        \"ON CONFLICT (client_id, channel, contact_id) DO UPDATE SET \"\n                        \" contact_name = COALESCE(EXCLUDED.contact_name,\"\n                        \" \" + portal_db._q(portal_db.CONV_TABLE) + \".contact_name), \"\n                        \" last_message_preview = EXCLUDED.last_message_preview, \"\n                        \" last_message_at = EXCLUDED.last_message_at, \"\n                        \" updated_at = NOW() \"\n                        \"RETURNING id\",\n                        (tenant[\"client_id\"], item[\"channel\"], item[\"from\"],\n                         item[\"name\"], item[\"body\"]),\n                    )\n                    conv = portal_db.rows(cur)\n                    conversation_id = conv[0][\"id\"] if conv else None\n                    # \u00a7215: inbound media needs the message id (chat-bubble\n                    # previews); every other message keeps the plain INSERT.\n                    keep_media = bool(item.get(\"media\")) \\\n                        and item[\"direction\"] == \"in\" \\\n                        and store_budget is not None\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.MSGS_TABLE) +\n                        \" (conversation_id, client_id, direction, body,\"\n                        \" sender_name, status, created_at) \"\n                        \"VALUES (%s, %s, %s, %s, %s, %s, NOW())\"\n                        + (\" RETURNING id\" if keep_media else \"\"),\n                        (conversation_id, tenant[\"client_id\"], item[\"direction\"],\n                         item[\"body\"], item[\"name\"],\n                         \"received\" if item[\"direction\"] == \"in\" else \"sent\"),\n                    )\n                    message_id = None\n                    if keep_media:\n                        try:\n                            returned = portal_db.rows(cur)\n                            message_id = returned[0].get(\"id\") \\\n                                if returned else None\n                        except Exception:\n                            message_id = None\n                    if keep_media:\n                        try:\n                            # \u00a7214: keep customer images / voice notes so\n                            # the inbox can show them after provider links\n                            # expire (savepoint-guarded, never raises).\n                            portal_inbound_media.capture(\n                                cur, tenant[\"client_id\"], conversation_id,\n                                item, media_blobs.get(id(item)),\n                                store_budget, message_id)\n                        except Exception:\n                            pass\n                    item.pop(\"_media_fetched\", None)\n                    # One-reply law (B2): the first automation that sends a\n                    # customer-visible reply claims the message; the other\n                    # reply hooks stay quiet. Side-effect hooks (language\n                    # detection, compliance, listen, routing, sequences)\n                    # always run.\n                    claimed_by = None\n                    if claimed_by is None:\n                        try:\n                            import portal_approvals\n\n                            if portal_approvals.maybe_decide(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"approvals\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if _maybe_enqueue_away_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"away\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if portal_cod.maybe_cod_flow(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"cod\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_brain\n\n                            if portal_brain.maybe_answer(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                conn,\n                            ):\n                                claimed_by = \"brain\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_kb\n                            import portal_intents\n\n                            import portal_llm\n\n                            with portal_llm.usage_scope(\n                                    \"intent\", tenant[\"client_id\"]):\n                                intent = portal_intents.classify(item[\"body\"])\n                            if portal_kb.maybe_auto_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                intent,\n                                conn,\n                            ):\n                                claimed_by = \"kb\"\n                        except Exception:\n                            pass\n                    if claimed_by:\n                        try:\n                            import portal_events\n\n                            portal_events.note_claim(\n                                cur, tenant[\"client_id\"], item, claimed_by\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_contacts.maybe_detect_language(\n                            tenant[\"client_id\"],\n                            item[\"from\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    if item[\"direction\"] == \"in\":\n                        try:\n                            import portal_compliance\n\n                            portal_compliance.maybe_opt_out(\n                                tenant[\"client_id\"],\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_listen\n\n                            portal_listen.maybe_listen(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_routing\n\n                            portal_routing.maybe_route(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_intelligence\n\n                            portal_intelligence.maybe_analyze(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_approvals\n\n                            portal_approvals.maybe_request(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_sequences.maybe_enroll_new_contact(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_enroll_keyword(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_auto_pause_replies(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_workflows\n\n                        portal_workflows.maybe_trigger_message(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            item[\"direction\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_events\n\n                        portal_events.mark_inbound_done(\n                            cur, tenant[\"client_id\"], item\n                        )\n                    except Exception:\n                        pass\n                    inserted += 1\n            conn.commit()\n        finally:\n            conn.close()\n    except IngestRateLimited:\n        raise\n    except Exception as error:\n        raise IngestFailure(error, \"messages ingest\") from error\n    return inserted\n\n\n@bp.post(\"/whatsapp/messages\")\ndef ingest_whatsapp_messages():\n    \"\"\"Store connector-delivered messages through the shared channel engine.\"\"\"\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n    try:\n        normalized = normalize_messages(\n            payload.get(\"messages\"), default_channel=\"whatsapp\"\n        )\n    except MessageValidationError as error:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": str(error)}}), 400\n\n    try:\n        inserted = ingest_messages_for_tenant(tenant, normalized)\n    except IngestRateLimited:\n        return jsonify({\"error\": {\n            \"code\": \"rate_limited\",\n            \"message\": \"Too many messages; slow down.\",\n        }}), 429\n    except IngestFailure as failure:\n        return jsonify(portal_db.portal_unavailable(\n            failure.original, failure.operation)[0]), 503\n\n    logger.info(\"whatsapp messages ingested client_id=%s count=%s\",\n                tenant[\"client_id\"], inserted)\n    return jsonify({\"ok\": True, \"inserted\": inserted}), 200\n\n");
